/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180827-5","meetingId":"h30-cm08","date":"2018年8月27日","dateIso":"2018-08-27","committee":"総務委員会","time":"午後 １時００分～午後 ３時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"「」を聴取いたします。 (1)平成３０年度都区財政調整交付金当初算定結果","agenda":"「」を聴取いたします。 (1)平成３０年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今後の見通しとして、どういう推移をたどっていくと都と区では認識を共有されているのか、伺いたいと思います。なくなったもの、そういった事業があれば、ご説明ほしいと求めました。","respondent":"品川財政課長","answer":"都と区の共通認識というところなのですけれども、全都ということになりますので、基本的には東京都の予測ということで出しているというものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"新規が１２項目で改善が３２項目という説明がありましたけれども、これらについては、資料の示し方について改善を要望させてほしいと求めました。２月末の最終調整に向けてということですけれども、最終調整の項目にはどういう事業があるのか、お伺いしたいと思います。","respondent":"品川財政課長","answer":"それから、いろいろ細かい部分の調整が入るということで、現時点でどこにどの金額が調整として入るかというところはまだ把握ができない状況です。最終的に東京都が配分の割合等を見て、やっていくものですので、現時点では細かくどこに入るかというところはわかりかねます。","id":"exchange-002"}]},{"id":"topic-02","title":"シティプロモーションの取組について（ＰＲ冊子・ワークショップ）","agenda":"シティプロモーションの取組について（ＰＲ冊子・ワークショップ）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"客観的に誰かにアンケートをとって、無理やり掘り起こしていくのかなという感じを与えると思うのですけれども、その辺についてはどうなのですか。だんだん限界と言ったらおかしいのですけれども、無理やりやっているような感じを受けるのですが、あわせてご見解を説明するよう求めました。","respondent":"木村報道・プロモーション担当課長","answer":"新たな切り口で発信すること、そういうことをうまく引き出していただくことを専門家にお願いしようと考えています。そして、これからどうやってもっと打ち出していこうかなということがメインです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回、区民から、それほど熱心にやってほしいというご意見やご要望を聞くことがあまりありません。今後、シティプロモーションのＰＲ冊子やワークショップなどの事業というのは、どういう方向に向かっていくのか、伺いたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"行政が音頭をとってずっとこれからもというよりも、幅広くやっていこうという形に本年度からシフトしてまいりたいと考えております。進め方の強弱、区民の方々と一緒に進めていこう、一緒に盛り上げていこうという姿勢で取り組んでまいりたいと考えています。","id":"exchange-004"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それだってオリンピック競技を開催するという１つの品川区の魅力という部分であるので、他部署との連携がどうなっているのか教えていただきたい。もしかしたらほかで答えが出ていることがあるかもしれないので、そういうことも踏まえて、全庁的にどういう連携をとっているのか教えていただきたい。","respondent":"木村報道・プロモーション担当課長","answer":"商店街支援であったり、その具現化ということで、この冊子の中でコンパクトにまとめご紹介をさせていただいたという部分があります。あるいはどう引っ張って出していけるかということを常日ごろ考えておりまして、これからもそういう視点で進めてまいりたいと考えております。","id":"exchange-005"},{"speaker":"いながわ委員","kind":"意見","question":"「つなごう品川」には、おもしろい字体が使用されていて、すごく魅力のある、手にとった人が見たいなと思う冊子のような気が私はします。創造性というものの欠如がないように、いろいろな視点から総合的に考えて品川区の魅力を創出していってもらいたいので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"このパンフレットのつくりについて少しお伺いしたいのですけれども、魅力的で、障害のある人に対するパンフレットの作成のあり方についてです。音声コードがここには反映されていないのですけれども、その考え方についてお伺いできればと思います。","respondent":"木村報道・プロモーション担当課長","answer":"こういう冊子を配っていますよということをお伝えしなくてはいけないので、これからどういう形で周知していくか考えてまいりたいと思います。そういう部分もこれから注意しながらやっていきたいと考えています。","id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ぜひよろしくお願いいたします。例えば障害のある方でもこういう方法で見られるということを、該当団体の方にぜひお伝えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"商店街だけというと何かちょっと寂しいなと思っていまして、もしまた改訂があるときに、検討していただきたいなと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-03","title":"Ｏ歩道橋補修工事請負契約","agenda":"Ｏ歩道橋補修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"場所はわかるけれども、状況がわからないので、そこを伺いたいと思います。日常的な点検の体制や項目に不備はないのか、今回を機に何か改めることはないのか、そこも含めて教えてほしいと求めました。","respondent":"立木経理課長","answer":"通常５年ごとにこういう橋梁等の点検が行われると聞いてあります。ですので、通常の劣化に関する点検に該当したものでございまして、それは順番にやっていく工事の一環ということを所管から聞いております。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"念のため、今回はやらないけれども近いうちにやるというものがあるのか。危険な場所がないようにという意味なのですけれども、ご説明ほしいと求めました。","respondent":"立木経理課長","answer":"今回の点検につきまして、補修箇所が外装というところで、特にそのほかの不具合ということではなく、今回はただの外装工事というか、通常の補修工事をすると聞いております。","id":"exchange-011"},{"speaker":"いながわ委員","kind":"確認","question":"平成２５年度に実施した歩道橋の日常点検で発見された損傷箇所で、大体５年ぐらいのスパンののち、今回なのか。先ほど説明を聞き逃してしまったのかもしれないので、確認をいたします。","respondent":"立木経理課長","answer":"点検をした結果、補修が必要なものに優先順位をつけてやっていくということで、それが大体５年スパンで回ってくると所管からは聞いております。５年で大体一回りするというような形です。","id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問","question":"それとも、たまたま最後の１本が今回なのか、何というのだろう、言わんとしていることはわかりますよね。５年間、何していたのですかと感じてしまいます。","respondent":"立木経理課長","answer":"損傷具合によって全体を５年に分けて順番に修理していくため、それは損傷具合によって緊急度に優先順位をつけていると聞いてあります。工事の金額によりまして、報告が上がらない場合もありますが、毎年きちんと計画を立ててやっていると聞いてあります。","id":"exchange-013"},{"speaker":"いながわ委員","kind":"質問","question":"９,０００万円以下の補修工事をどんどんやっていて、たまたま最後ぐらいなのですか、今回たまたま９,０００万円超えてしまったと。それから５年放っておけるぐらいのダメージだったということか尋ねました。","respondent":"立木経理課長","answer":"委員おっしゃるとおりです。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"そちらにも影響とかはあるのでしょうか、ないのでしょうか。それも含めて理解できないので説明を求めました。","respondent":"立木経理課長","answer":"今回は外装ですので、外側の工事でございまして、私どもが聞いているのは、歩道橋の下は道路ですので、そちらは片側ずつ夜間通行どめにして、仮設を組みながら工事をするため、歩道橋を通行する方への影響はほぼないです。","id":"exchange-015"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"平成２６年度から試験的に延山小学校で始めて、そのほかの学校では、この数が実施した学校数ということでよろしいのですか。我が会派でも要望して、期日前投票所をアトレの中に設置していただきました。","respondent":"秋山選挙管理委員会事務局長","answer":"１つは場所がないということ、いろいろ相手方の対応が難しいということで、なかなか実現できていないというのが正直なところです。増やしていかなければいけないと考えていますが、必要なものがありますので、今後とも検討はしていきたいと思っているところです。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"選挙公報なんかも準備するのですかね。それから今後の見通しを含めて、お考えがあったら教えていただきたいのですが、いかがか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"私の説明が足りなかったのかなと思うのですが、決して投票行為だけを体験してもらおうということを主眼に置いているわけではございません。今後につきましては、まずは全校でやりたいと考えておりますし、今後も続けていきたいと考えております。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう１つ、伺うのを忘れてしまったのですけれども、出前模擬選挙というのは大体１時間なのでしょうか。でもやっぱり学校でやらなければだめだよねという感じで意見を言っているわけなのですが、この内容は１時間で行うと理解してよろしいのか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"教育委員会との連携ですけれども、今、実施しています。実施数が増えていきますと、その辺を含めて、もう少し頑張っていきたいなと思っているところです。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"その視点を広げる１つとして、ぜひそういうＮＰＯとの連携というのも今後考えていっていただきたいなと思います。これは要望にとどめますので、ぜひ検討を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"大学、それぞれの教育機関などで体験をしながら、社会のあり方について考えていくという機会に発展させてほしいと求めました。選挙管理委員会としてのアイデアや学校独自のアイデア、関係機関との連携の強化について、ご意見を伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"臨機応変な対応というのもやりたいところではありますが、まずは出前模擬選挙というのを一つ品川区としてのパッケージをつくり上げていく。今年は９月に選挙があるため、期間は短いのですが、学校での出前模擬選挙をどんどん進めていきたいというふうに活動しています。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問と意見なのですけれども、まだ有権者でない中学生のときですか、投票所に一緒に入ることができなかったという話をおっしゃっていたのです。３点目は、現状の対応のご紹介やそれに対してのご意見を伺うという場があると、それぞれいかがか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"指定施設に対する説明会も区では行っておりますので、入院されている方で希望する方については、お話させていただきたいなと思ってあります。どういう方法で、どなたとやるのが一番いいのかとか、その辺については、今後、よく検討させていただきたいと思ってあります。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"みんなの目につく受付なのかどこかはわかりませんけれども、そういう工夫は必要なことですので、ぜひ検討していただきたいと要望したいと思います。ぜひそういう思いが実現できるように、こちらは要望で、先ほどの病院内での投票については一言ご答弁ほしいと求めました。","respondent":"秋山選挙管理委員会事務局長","answer":"障害のある方に対する投票できますということを、目立つように書いておりますので、そちらのほうで対応していければなと思っています。説明会のときに、いろいろ周知をしていただくように、こちらからも働きかけていきたいと思っています。","id":"exchange-022"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２点質問します。やはり東京都の選挙管理委員会が窓口になるのかどうなのかと思いまして、その２点、お聞きしたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"私たちとしても、協力して、バックアップしていきたいなと思ってあります。こちらに問い合わせがあった場合は、東京都に回すということではなくて、私どもでちゃんと対応させていただいているです。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":33730,"voices":70}},{"id":"h30-20180828-14","meetingId":"h30-cm08","date":"2018年8月28日","dateIso":"2018-08-28","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ５時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"本日の進め方でございますが、(1)の基礎自治体のあり方に関すること","agenda":"本日の進め方でございますが、(1)の基礎自治体のあり方に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"２点目は、現時点で具体的に何ができるのか、施設の目的やそれぞれのおおよその定員数や規模なども伺います。少なくともこの案に対するパブリックコメント実施は必要だと思いますし、それを求めたいと思いますけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"細かいボリューム感につきましては、まだまだ検討が必要だと考えていますので、これはさらに検討を深めながらです。説明会という形がいいのか、いろいろ方法はありますけれども、地元の方々のご意見をさまざま伺いながら決定していきたいというふうに思ってあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域住民や障害者団体など、関係団体に説明をして意見を伺う説明会を開き、同時にパブリックコメントの実施も最低限必要だと思います。議会への報告のみで進めるのではなく、計画の立案に幅広い住民参加を位置づけた区政運営を求めたいと思いますけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"この方針についても、これまでも報告を差し上げているところです。いろいろなチャネルを通じて、ご意見を伺う機会を設けながら、よりよい施設をつくっていきたいというふうに思ってあります。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"導入施設のほうで、荏原消防署小山出張所をこちらに移転する予定だということをお聞きしましたが、この地域は本当に閑静な住宅街なのです。近隣の方が驚くような状況になるかと思うのですが、その辺に対してはどのような検討、また考えをお持ちか尋ねました。","respondent":"柏原企画調整課長","answer":"音の問題であるとか、とにかく道がとても狭いところですので、交通の課題などがあるということを、区としても認識しております。これは区もそうですけれども、東京都や消防も含めた形でご説明しながら、施設としてうまく立ち上がっていけるように配慮していきたいと考えています。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"現在ある小山五丁目にある地域では、なれ親しんだというか、そういう意味で地域住民の方も長い期間をかけて協力してくださったと思います。本当に閑静な地域であり、地域の皆さんの理解を十分いただいて、ご協力していただけるように最大限配慮しながら進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"新妻委員","kind":"確認","question":"今の質問に関連しまして確認だけします。そこはしっかりされていることと思いますが、目黒区に関しての動き、その住民への説明というのはどうなっているのか説明を求めました。","respondent":"柏原企画調整課長","answer":"そうした施設計画があるときには、法令等々にのっとりながら説明をしていきたいということで思っております。この後、目黒区側のやり方というのもありますので、相談しながらきちんと事業を進められるようにやっていきたいと考えています。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/237826?Template=document&Id=6056#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":7910,"voices":19}},{"id":"h30-20180829-18","meetingId":"h30-cm08","date":"2018年8月29日","dateIso":"2018-08-29","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ４時１０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"の１、特定事件調査","agenda":"の１、特定事件調査","exchanges":[{"speaker":"本多委員","kind":"意見","question":"は出口、出て左に、左折しかできないのですね。その辺の道路など、細か過ぎて申し訳ないのですけれども、もう一度総点検したほうがいいのかなと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"提案","question":"試しにやってみて、本番のときにこういうのをと、品川区も、大会組織委員会なり何なりに提案できるではないですか。大井競馬場前駅の周辺、後は、これがだめと言われているのはわかっていてあえて言うのですけれども、橋脚が結構見えるではないか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"競馬だけではなく、競馬場でさまざま、いろいろなイベントが打てるわけではないですか。例えばパックができるなら、リオなどでも、チラシが来るとそういうセットのパックみたいになっているのがあるではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問・要望","question":"自転車はどういう扱いになるかということで、橋の歩道側と言うのですか、もし何かあればお聞きしたいと思います。東京都としても、大会組織委員会としても考えてらっしゃるとは思いますけれども、対策をしっかりやっていただきたいと思っているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"大会組織委員会が認めてくれるのかどうかわかりませんけれども、スポーツで終わらない、文化というところで組み合わせをしてほしいと求めました。それとも、できるだけそういう転換性を持たせてやったほうがいいとか、その辺のお考えをお聞かせほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"見た後に区の中を回遊していただく、品川区の魅力を十分に楽しんでいただくような方策はないかというのは、常々考えているところです。ホームページ等で先に発信して誘致するような方策であるとか、そういったことを私どもも考えていきたいとは思っております。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう宿場町で栄えたわけですから、江戸の情緒を感じられるような品川らしさと言うのでしょうか、来訪される特に外国人の方などに。スポット的にやれることなのかなと思うのですが、このあたりの考えについて何かご意見があれば、答弁としてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ちょうど９月中旬あたりから、何か品川を盛り上げるためにやっているのだよというような統一した気持ちになれるものはお配りはしたいと思っています。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"もう１つの動線としてどうなのかがわからないので聞くのですけれども、わからないので教えていただきたいと思っています。それだけ整備も大変だし、混雑もあるしということも１つ気になるところですけれども、どうなっているのか教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やはり、会場の近くになれば木が多いのですが、そこまではかなり照り返しも強いですし、ミストは必要かなという認識は持っております。舟のほうは、観客を運ぶためと言いますか、観客が行くためのというような認識は持っておりません。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つ、毎年私たちもご要望をいただいております音響信号ですとか、エスコートゾーンなどの整備。これはぜひ要望として出させてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから、大井町駅が最寄り駅かどうかということなのですけれども、最寄り駅と言いますか、使う方もいるだろうという想定はしているという認識です。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"参加できるようにしてほしいと求めましたし、意欲的に積極的にやっていただく方が、しっかりとできるようにしてほしいと求めました。これは意見として言っておきます。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ボランティアはまさにご本人の自発的意思のもとにやるものでございまして、決して強制するものではないというのは認識として持っております。","id":"exchange-009"},{"speaker":"大倉委員","kind":"質問","question":"そういったような取り組みはできないのか伺ったときに、そういった話は全くないので、というようなお話でした。一つやり方としてあるのかなと思ったので、その辺、ぜひ考えていただければと思いました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員がおっしゃいますように、区民の方にまた近くのところを回っていただくというような、そういう方策もまた考えてはいきたいと思います。そこはまだわからないのですけれども、そういったところを活用しながら、一緒に盛り上げていくような方策は考えていきたいと思います。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"先ほど競技時間が午前・午後でもう決定しているというお話があったのですけれども、すみません。オリンピック・パラリンピックのホームページのところを見たのですけれども、時間帯がわからなかったので、そこだけまず教えていただけますか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらは、ホームページに、組織委員会のものがリリースで出ているのですが、ホッケーですと７月２５日から８月７日の９時３０分から一旦は１３時１５分までと、夜の部が１８時３０分から２２時４５分という２つのセッションが基本になっているです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ地域の方たちの声も聞いてほしいということと、バリアフリーについても、自分たちの不便に感じていることがわかるではないですか。何か答弁があればほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"休憩場所をつくるような話は聞いておりますので、そのあたりはいろいろ要望を出しながら、最適な形というのをつくっていきたいと考えています。それに当たりましては、地域の声をもちろん聞きながら、最適な形をとっていきたいと考えております。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"スタッフと道案内、ボランティアと今、分けて発言されていましたが、私はオリンピック・パラリンピック全体、かかわる方全ての人たちに対して暑さ対策など、体調に何か悪影響が起きないように、何かしら配慮していただきたいと思うので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"委員会でも要望しているものとして、例えば大井町、大崎へのバスというのもありましたけれども、ぜひこれからも強調してもらいたいと思います。その中で障害のある方のことを考えたときには、やはり何か対応策を今から考えておかないと、その辺もしお考えがありましたらお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私もそのように感じることはあるのですが、ただやはり、品川の中に非常にいいところもたくさんあります。ラストマイルの仮設トイレの中で多目的の部分をつくっていくのかというのは、一旦東京都のほうとも相談しながら要望していきたいと思います。","id":"exchange-014"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"何台かそちらに回すような形をとれるのか、お金の問題も出てくるので、それも検討していってもらいたいと思いますとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ぜひ欲しいというようなお声もいただきまして、こちらは９月中旬から販売を予定しております。この配付が、どの程度機運醸成に貢献しているかということはいろいろ検討しながら、効果が高いかというのを考えながら進めていきたいと考えています。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"９月中旬からキーチェーンとぬいぐるみを販売予定ということだったのですけれども、どういったところで販売がされるのかということと、金額を教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今、まだあくまで未定なのですが、販売するところは庁舎のふれあい売店と、あと数カ所を予定しております。金額なのですが、ぬいぐるみが１,８００円、キーチェーンのマスコットが６００円を予定しております。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"ふれあい売店のほかと言うのは、具体的にどの辺なのですか。やはり区役所に来ないと買えないのかということを聞きたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"２店舗を考えているのですが、まだ販売体制が整っていないので、今のところはしながわ観光協会と総合体育館を考えています。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"メモ帳などほかのものというのは、売店のところに並べたりはしないのですか。ぜひ教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ここにも書いてあるのですけれども、缶バッジは今度の２年前フェスタのときに配る予定ですので、ぜひいらしてください。大体、当課のイベント、それからスポーツ大会ですとか、そういったところで配布しております。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"提案","question":"今、２年前フェスタがこれからあるということで、オリンピックに特化した特設のホームページをつくってみてはどうでしょうかという提案です。期間中、終わるまで対応するべきだと思うし、その中でこの３つのキャラクターを活かす方法を検討してはいかがでしょうかという提案ですとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その中での３キャラクターのアニメといったようなものはなかなか金額の関係で難しいとは思うのですが、いつも見たら新しいホットな情報が載っているであるとか、そういったようなサイトづくりはしていきたいと考えています。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"提案","question":"ですから、品川区のホームページから飛ぶのももちろんいい。３競技を本当にＰＲしていくことを考えたら、もっと飛躍的に考えてもいいのではないかということで提案していますので、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"品川区のホームページから飛ぶことはできまして、特設サイトから大会組織委員会にはリンクを張っていますが、相互リンクには確かなっていないです。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"それからもう１点は、インターネットなどで売ってはいけないのですか。私はインターネットで売ってもいいような気がするのですけれども、なぜそういうことを考えていないのかというのも説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"どのくらいの反応があるかということも、素人なものでなかなか見えないところで、そこまでは検討しておりませんでした。気軽に買えて、機運醸成につながっていくのかというのは、もう少し研究させていただきたいと思います。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"区で真面目にいろいろ構築してどうのこうのと言うのではなくても、そういうところに出せばいいのではないのかなと思うのですけれども。そのようにはならないのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"インターネット販売、ちまたで今非常に有効に、たくさんのサイトがあって、多くの方が利用していると思います。なかなかその分野では行政はおくれておりますので、本当に研究をさせていただいて、できるのかどうかも含めて考えてまいります。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"建設委員会で水辺千本桜計画への寄附を目的にふるさと納税をした方には、例えばこういうセットを、期間限定でふるさと納税の返礼品の中に添えるとか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"寄附する方は、少しの返礼をもらって、わくわく感を手に入れるという形だと思います。その商品に加えられるかどうかというのは、また税務課とも相談しながら、それが適切なのかどうかも含めまして研究していきたいと思います。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"意見","question":"適切かどうかも含めてとあったのですけれども、品川区文化スポーツ振興基金でしたか、そういう基金を積んでいますよね。一般のふるさと納税として、その中の返礼品のメニューに加えるということもあると思いますので、ぜひ検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"つる委員","kind":"確認","question":"ノベルティというようなお話で、先ほど石田秀男委員のときにもありましたが、もう１回確認です。２０２０年のオリンピック・パラリンピックを１つの区切りとして、用意をしているイメージでいいのか説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員おっしゃるとおりに、２０２０年のオリンピック・パラリンピックまでと考えているところです。","id":"exchange-025"},{"speaker":"つる委員","kind":"提案","question":"先ほどインターネット販売という提案もありましたけれども、そういうのも、そういう形で活用していくという手はあるのだろうなと思うのですね。要は、税金を使ってつくっているということだと思うのですが、それを説明するよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"永遠に残るのであればうれしいと考えています。それともう１つ、今きちんとした金額を持っていませんが、２,５００万円あるです。","id":"exchange-026"},{"speaker":"つる委員","kind":"意見","question":"ぬいぐるみだったら１個１,８００円、マニアの方が３つ全部そろえたいとかとなってくると、ぬいぐるみだけで金額が５,４００円になるわけですよね。その収入というのは幾らぐらいと見込んでいますかとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今、確実な数で持っていないのですが、ぬいぐるみ１体当たり、確か２００体程度の販売を見込んでいました。それで、キーチェーンのほうは確か４００個で見込んでいましたので、その程度の歳入だと思っています。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問","question":"そうしたものも含めて、せっかくなので、そこまで検討されたほうがいいのではないでしょうか。そのぐらいの商魂を持ってやってもいいのではないかと思うのですが、そのあたりはどうか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その１つとして考えたほうがいいのではないかという意見と、２つの意見がありまして、今回は原価ぎりぎりの方です。その先の２０２０年以後に関して、それは販売等や、部全体としてどうするのかというのは研究していきたいと思います。","id":"exchange-028"},{"speaker":"つる委員","kind":"意見","question":"このキャラクターが引っ張る部分と、もともと持っている品川区のそういう魅力ある商品とコラボをさせることは、お互いの相乗効果が出るわけですよね。そうしたことにも活用していく、知恵を活かしていくことも必要ではないかと思うので、ぜひ課を越えていろいろ検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"今、１,８００円のぬいぐるみが１体当たり２００体販売という話でしたが、キーチェーンのほうの数はどのぐらいずつなのかをお聞きしたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"キーチェーンのほうは４００個です。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうのはどうなるのかなと思うのと、応援キャラクターで、応援グッズというのはつくらないのですか。区としてできないのかどうかというのもあると思うので、その辺はどのように考えたらいいのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"開催会場での販売なのですが、いろいろライセンシーの関係があって厳しいかなと思います。応援グッズなのですが、これは検討して楽しいものをつくっていきます。","id":"exchange-031"},{"speaker":"大倉委員","kind":"質問・要望","question":"知らない人たちに知ってもらうには、その辺のイベントへの出演の考え方について教えてください。そういうファンをどうやってつくっていくかという考え方も１つ視点としてあるのかと思うので、その辺の考え方を説明するよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"基本は当課が行っているイベントに出ているところですが、それ以外にも出演要請があったときには、区民まつり等にも出ていく予定です。ハッシュタグをつけてほかの人にも拡散していくこともできますので、そういったいろいろなものを使いながら広めていきたいと考えています。","id":"exchange-032"},{"speaker":"大倉委員","kind":"意見","question":"本当に真剣に広めていく、２０２０年までやるのだというところがあれば、もう少し広がるのかなと。違う発想のところへ考えを飛ばし、伸ばしながらやっていっていただけるといいのかなと思いましたので、ぜひ盛り上げていきましょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"先ほど工事現場に３カ所貼っていらっしゃるということでしたが、そういうところに貼る、そのほうが効果があるのではないかと思うのですが。やはり意識のない人が何かこういう柄を見れば、その辺も機運醸成になるのではないかと思うのですが、どうお考えか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"どのぐらいの大きさで貼るかというのもあると思うのですけれども、これから来年度に向かっては検討の余地があるかとは思います。その反応も見ながら、またいろいろなところで、目にすることが周知には一番だと思いますので、広げていきたいと思います。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"先ほど、区が利益団体ではないというお話もありました。今回、販売予定というところで、どういった経緯だったのか伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"特にこれを一般に配布するであるとか、そういったことは考えてはいなかったところです。つくったものを目にした方から、かわいいから欲しいというご意見を幾つかいただいた中で、販売しようということになったです。","id":"exchange-035"},{"speaker":"つる委員","kind":"提案","question":"先ほど提案しようと思っていたのですが、いろいろな自治体で、ＬＩＮＥスタンプなどをつくってやっているところもありますよね。先ほど言ったように、ＬＩＮＥスタンプなどが検討できるかどうか、そもそものところをまず１つ説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長、いながわ委員長","answer":"東京都内ではないですけれども、オリンピック関係でもやっている、ＬＩＮＥスタンプをつくっているところが確かあったと思います。… 視察の時間もだんだん近づいてまいりましたので、特にご発言をされる方がいらっしゃいましたらお願いいたします。いらっしゃらないようですので… 東京２０２０大会を契機として、その魅力発信や新たな文化の発掘などを目的に、昨年平成２９年６月より実施しています。","id":"exchange-036"}]},{"id":"topic-02","title":"しながわ文化プログラムのロゴマークの変更","agenda":"しながわ文化プログラムのロゴマークの変更","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"何ですかという質問の先に行かないので、きちんと、つけた人がわかって、気になった人にも伝えられるようにしておかないといけないと思います。あえて２個ある必要性、ロゴとしてはこれがあるというところがどうなっていくのか説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１点目の、スタッフが説明できるようにということなのですが、現在は、申請をいただいたときに、オリンピックというのは文化の祭典でもあります。","id":"exchange-037"},{"speaker":"大倉委員","kind":"質問・要望","question":"スタッフの方にということだったのですが、一般の方はなかなかつけられないということなのでしょうか。その辺を教えていただきたいのと、つけたいかどうかという視点で見ると、その辺の考え方。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ああ、これもオリンピックを盛り上げる一環なのだと認識していただく、そういうことを目的にやっております。日本語を入れた、こちらはやはり日本語が入っていたほうが万人にわかりやすいだろうということで明示させていただきました。","id":"exchange-038"},{"speaker":"大倉委員","kind":"質問・要望","question":"こんなことをやっていますという説明も一緒につけてお渡しできるようにすると、なおいいかと思ったので、ぜひご検討いただきたい。工事現場などへシールを貼る、これを貼って広めていくというところもぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-03","title":"ラリンピック推進特別委員会を再開いたします。 視察、大変お疲れさまでございました。お暑い中ありがとうございました。 先ほど、予定表の３、その他を議題に供し…","agenda":"ラリンピック推進特別委員会を再開いたします。 視察、大変お疲れさまでございました。お暑い中ありがとうございました。 先ほど、予定表の３、その他を議題に供し…","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"非常に暑くて、また出演者の方も大変つらい場面があったので、委員会等でもそれについて質問させていただきました。これは要するにここにいれば、いろいろな競技をここで見られて、休めるということなのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"委員のご指摘のとおり、こちらは休憩する場所でございまして、バザー等をやった場合、もしくはスポーツ・競技で楽しんだ後、こちらのほうでひと時休んでいただくというものです。","id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういう支援ができる体制を、こういう１つ１つのイベントでいろいろなところで支援できる体制がある程度できているのかというのを伺いたい。なぜこのようなことを聞くかと言うと、来てもらってその方々に払うのはいいのだけれども、ただそれだけだと、競技が伸びていかないではないか尋ねました。","respondent":"池田スポーツ推進課長","answer":"障害者スポーツの普及ということでの業者のプロポーザルで実施しているものでございましたので、バスケットはバスケットボール連盟というような形で。１つ、５人制サッカーにつきましては、一般社団の障害者サッカーの普及団体の方が主になる形になっているところです。","id":"exchange-041"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"パンフレットともに、やたたまか何かをつけるとか、まずブラインドサッカーと出ていないのがなぜかというのが気になっています。その辺、なぜ連携していないのかなと、その辺がどうなっているのか伺います。","respondent":"池田スポーツ推進課長","answer":"ふくしまつりのほうではホッケーもやりますので、３種のキャラクターも一緒に出さなければいけないところが漏れてしまいました。次回以降、気をつけるようにいたします。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"このイベントについて教育委員会等々の案内などもされているとは思うのですけれども、その辺と、意識向上についてどのように捉えているかを説明するよう求めました。","respondent":"池田スポーツ推進課長","answer":"体を動かすことを習慣づける、好きになってほしいということを願いまして、障害者スポーツチャレンジデーを開催するです。多くの方が参加することを願っているところです。","id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"確認","question":"こういうところには前もって話をして、案内のチラシ等もつくるわけではないですか。こういうところにも動いてみるとどうかとか、何か情報を、そういうことも一緒になって話ができているのかという確認だけとりたいです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回の３月の大会には、プロジェクトの実行委員会をつくってくださって、たくさんご協力をいただいたところです。キックオフのときは、これからもまた地元の方のご協力を仰ぎながら、いい大会にしていきたいと思っています。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"品川区議会公明党の1)のところで、現状で認められているのか、認められていないのか。認められていると言うのであれば、大会組織委員会に尋ねる必要もないので、その辺についての認識を説明するよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"たまたま先日、このことは確認をしたのですが、個人の方がＩＤ登録をして購入いただくというのが基本だという線です。まとめ買いと言いますか、そういったことも考えてはいます、検討はしている段階ですというお答えはいただいております。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"確認","question":"ステージなどをつくって、いろいろなイベントをやることについては基本的に言ってもいいのでしょうか。こちらのほうはいいのかというのを確認だけお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そこの中でイベントを行うというのは少し厳しいかと、私の認識では思っております。反対側の公園のところなどはどういう使い方をするのか、確認しておりませんので、検討の余地があるかと思っているところです。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"確認","question":"確認ですが、チケットを出してというところですけれども、大井ふ頭中央海浜公園の会場があって、練習ピッチがありますよね。そこ自体は会場だけれども、例えば野球場はだめなのかという、その辺のところがよく理解できなかったのですが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私どもが聞いている話としては、野球場も含めて、道路に挟まれた部分が会場で、そこは大会組織委員会のエリアというふうに認識しております。そちらはどのように使うか聞いておりませんので、検討の余地があるのではないかと考えています。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/125111?Template=document&Id=6542#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":40768,"voices":145}},{"id":"h30-20180830-10","meetingId":"h30-cm08","date":"2018年8月30日","dateIso":"2018-08-30","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"平成３０年第３回定例会","agenda":"平成３０年第３回定例会","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"第３回定例会の一般質問なのですけれども、これはいわゆる補欠選挙後なので構成が変わるではないですか。それはどうなるのか尋ねました。","respondent":"久保田区議会事務局長","answer":"これはまだ今の時点でですので、補欠選挙が終わりまして、お二人の方が入ってくる予定ですけれども、時間のほうの持ち時間が変わってきます。あくまでも現時点での予定ですので、時間の変更等はできますので、よろしくお願いします。","id":"exchange-001"}]},{"id":"topic-02","title":"品川区議会防災訓練","agenda":"品川区議会防災訓練","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"これ、これは貸与されている意味自体がどうなのというところもあるのですが、それは実は団体の方からもそういうご要望があります。例えば、品川区議会議員という腕章もありますから、それをつけて参加をするとか、そういうことを提案したいのですが、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"石田（し）委員","kind":"確認","question":"以前、防災訓練のときにどういう服装でという話をしたら、「基本的に区議会の方たちはそれを着ないでください」と行政サイドから言われて、着ないというのが、二、三年ぐらい前に私が確認をしたときにはそんな話があったのは覚えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"意見","question":"それこそまた議会改革になってしまうのかどうかわからないけれども、それは５年ぐらい前の話だと思うので、そのまま話が止まっています。だから、またどこかで１回考えるなら、やってもいいのかなと思うけれども、そのときは、そういう対応で腕章だけになったというぐらいだねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういう防災の団体の方からそういうお声が２年連続ぐらいあったものですから、それはちょっとやはりこの場で申し上げなければいけないのかなと。これはどこかでつくっていただきたい、ぜひ取り上げていただきたいということで、今日はそれで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5298#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":7794,"voices":32}},{"id":"h30-20180918-6","meetingId":"h30-cm09","date":"2018年9月18日","dateIso":"2018-09-18","committee":"区民委員会","time":"午後 １時００分～午後 ３時４９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件整理しています。","topics":[{"id":"topic-01","title":"しながわ観光フェア２０１８","agenda":"しながわ観光フェア２０１８","exchanges":[{"speaker":"渡辺委員","kind":"確認","question":"この事業自体は、これが直営で何かをするのではなくて、地域のイベントをつなげていく、そして情報発信をしていくものというふうに捉えたのですが、たぶんそういうことだろうという確認と、予算額１,２００万円のうち、主なものでいいので内訳を説明するよう求めました。","respondent":"立川文化観光課長","answer":"各地域のうち実行委員会等が中心になって実施しているものでございまして、各地域の観光フェアのいわゆる出店やイベント開催経費となっております。スタンプラリーの実施経費等です。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"イベントの頭数で言えば８等分に分かれるのか、金額幾らまではあれなのですが、比率だけ教えてもらっていいですか。どんなものが多数を占めるのか。","respondent":"立川文化観光課長","answer":"比率といたしましては、約半分がえばら観光フェアの開催経費となりまして、そのほかの経費としまして、各地域イベントへの出店経費が主なものでございまして、またスタンプラリーの実施経費もその中に含まれているものです。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"意見","question":"ほとんどの運営は地域が頑張るけれども、行政がすべき支援の中にこういうＰＲだとか広報関係、これは比重が高くてもいいかなと。２年目よりも３年目で、ここ３年ぐらいなのか、その辺をお聞かせ願えますかとの意見を述べました。","respondent":"立川文化観光課長","answer":"観光フェアとして実施して、いわゆる広告の相乗効果というのがやはり一番の観光フェアの売りだというふうに思っているところです。この観光フェアに参加していただけるような事業につきまして、皆さんのご意見を伺いながら拡大に努めてまいりたいと思います。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"意見","question":"なぜかというと、今度は運営している地域の方以外、お客さんの目線で考えたときに、メニューが多いと。リクエストですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"イベントを３年間行われているということだったのですけれども、その３年間の実績というか、どうか尋ねました。","respondent":"立川文化観光課長","answer":"今委員ご指摘のことです。今後はその辺につきましても、なるべくわかりやすい資料づくりに努めてまいりたいと思います。","id":"exchange-005"},{"speaker":"大倉委員","kind":"質問・要望","question":"どういうふうになっているのか教えていただきたいのと、例えばこの間中央公園でやった大井どんたくの日と同じ日に開催されたイベント、何でしたか。２０１８」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"大倉委員","kind":"質問","question":"ＧＯＯＤ ＰＡＲＫ！２０１８、同じ日にやっているイベントとどういうふうにそれを落とし込んでうまく反映できるのかなというところの考えがあれば説明を求めました。","respondent":"立川文化観光課長","answer":"１回スタンプをもらうと２つ目ももらおうと、今回、体育の日スポーツイベントを加えたところです。約２,０００人から２,５００人、いわゆるイベントの相互でチラシを配り合うということは、かなりの効果があるのかなということを実感しています。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"こちらでは６００万円というところで言うと、楽しかったらまた来たいねと思ってもらえるようにしていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"イルミネーション事業","agenda":"イルミネーション事業","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"すみません、また予算額の内訳を教えていただきたいのと、あとで資料をいただけたらと思います。減額の理由を教えていただきたいです。","respondent":"立川文化観光課長","answer":"大井町駅西口につきましては２,７００万円、目黒川沿いにつきましては２,２００万円、西小山駅前については７５０万円です。今年はその分がございませんので減額した予算を組んだところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"西小山７５０万円のその各場所でのイルミネーション設置場所での内訳は、もし今お答えできるようでしたらお答えしてほしいです。なかったら、資料をあとでほしいと求めました。","respondent":"立川文化観光課長","answer":"それで、目黒川沿いについては、設置と撤去については約１,２００万円を見込んでいるところです。西小山駅につきましては、設置、撤去につきましては大体２７０万円を予定しております。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"大井町駅前での設置についてなのですけれども、去年の委員会の中では、阪急との協議の場は特にはないというお話でした。設置するという話だったのですけれども、今年は設置前に阪急のほうとの意見交換だったり、そういうものはあるのかというのを伺いたいです。","respondent":"立川文化観光課長","answer":"ちょっと耐久性に課題があるということで、その辺を今年改善するということで、経費がかかっているところです。当然阪急の目の前ですので、イルミネーションを今年も設置するということで、お声がけをしています。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"シナモロールは、膨らませていたものを強化したとか、そういうことなのですか。それとも新しいものになったのか。","respondent":"立川文化観光課長","answer":"膨らませる方式というのは、実は耐久性に課題がありまして、今度はいわゆる樹脂ですのできっちり何十年も使えるような形です。それで、ほかの部品については当然使い回しになりますので、そういったつくりにしたものです。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"シナモロールだけが空気で膨らんでいたのですか。イルミネーション事業は今年で４年目だったと思うのですけれども、効果が見えたのかというのですかね、教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"効果について、もともとこのイルミネーション事業自体が地元の３商店街から強い要望がございまして、各店舗の売上につなげるという狙いもあります。","id":"exchange-013"},{"speaker":"田中委員","kind":"意見","question":"では、意見を聞きに行けば、効果測定をとれるということですね。商店街だったりとか、地域の声だったり、こういうところでよかったよという声が聞こえないと何なのかなと思ってしまうのですがとの意見を述べました。","respondent":"立川文化観光課長","answer":"実際、町場の声でどういったご意見があるのか、またツイッター等も発信していただいている方もいらっしゃいます。その辺、やはり情報収集して、その効果については見極めていきたいなというふうに考えているところです。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"わかりました。情報収集していただきたいのと、ちょっと計画というか、これからのスケジュール感を教えていただきたいのですけど。","respondent":"立川文化観光課長","answer":"区としてはイルミネーション事業につきましては、ご説明いたしました３地域での展開を考えてあります。内容につきましては、こちらは目黒川みんなのイルミネーション実行委員会というところが実施主体となっておりますので、その辺との連携をとりながら。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"ここで質問を求めていいのかちょっとわからないので聞きたいのですけれども、「品川区都市型観光プラン」という冊子があるではないですか。これをこの区民委員会のここで見られるようにという設定というのはできるものなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"では、事務事業概要とかのように資料として入るということはないということなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-03","title":"品川歴史館特別展「明治維新－そのとき品川は－」","agenda":"品川歴史館特別展「明治維新－そのとき品川は－」","exchanges":[{"speaker":"大倉委員","kind":"質問","question":"これも１０月７日からということで、先ほどの観光フェアとか、その辺とうまく絡めたりするのは難しいのでしょうか。こういうのを周知していくというところで、うまくこういったところ、観光フェアとかも活用していくというのはできないのか尋ねました。","respondent":"立川文化観光課長","answer":"ご指摘いただきましたご意見です。私も来年度、そういった方向でやりたいとちょうど考えていたところですので、所管のほうと協議してまいりたいというふうに考えているところです。","id":"exchange-018"},{"speaker":"大倉委員","kind":"意見","question":"どこまで入れて、ここまででやめますみたいな、その幅とかというのは結構大事なのかなと思いますし、ただ２０２０年東京オリンピック・パラリンピック大会に向けて、できるだけアピールしたほうがいいのかなと思っているので、いろいろ検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"できればここに金額が書いてあるともっとわかりやすいし、こういう質問もしなくて済むなと思うので、ぜひ書いていただけるとありがたいです。いかがか尋ねました。","respondent":"立川文化観光課長","answer":"内訳につきましては、実際執行段階で多少動く可能性がありますので、ちょっと実際数字を載せるというのは、現段階では難しいかなと。","id":"exchange-020"},{"speaker":"浅野副委員長","kind":"質問","question":"私も何とか時間をつくって見に行きたいなと考えていますが、予算額が１,４００万円ということで、非常にやはり喜ばしいことだなと思うのですね。例えば、実際に何名ぐらい見ていただけるのかという予測というのですか、それがございましたら教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"特別展につきましては、事務事業概要のほうに数字を載せておりまして、年度によってかなり差がありますが、おおむね４,０００名から５,０００名ぐらいの方が入館されているところです。","id":"exchange-021"},{"speaker":"浅野副委員長","kind":"意見","question":"４,０００名から５,０００名というと、かなり力を入れて、統合ちらしとかに入れていただいていると思います。ぜひとも力を入れて区民の方に知らせてあげていただければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-04","title":"ＵＮＩＴＥ ＨＥＡＲＴ ＦＥＳＴＩＶＡＬの開催","agenda":"ＵＮＩＴＥ ＨＥＡＲＴ ＦＥＳＴＩＶＡＬの開催","exchanges":[{"speaker":"田中委員","kind":"質問","question":"同じなのですけれども、予算額の内訳と、あと障害のある方たちや国籍、文化の違いなどの多様性への理解を深めということなのですけれども、当事者の方たちへの周知というものはどのようにされているのかということを伺いたいです。","respondent":"立川文化観光課長","answer":"こちらにつきましては個別にご案内を差し上げる、また団体を通じてご案内を差し上げるということを実施していると聞いております。鑑賞型文化関連イベントとしましても、ほぼ同額を予定しています。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"スクエア荏原前広場のライトアップは、先ほどのイルミネーション事業とはまた別でということなのでしょうか。１０月中旬ごろからライトアップをし始めるということなのですけれども、そういうものはどうなっているのか教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"こちらは１０月中旬から一応イベント開催までというふうな仕切りでございまして、ライトアップする場所につきましては、いわゆる施設前の広場の樹木です。","id":"exchange-024"},{"speaker":"田中委員","kind":"意見","question":"何本ぐらいに、どのような設置がされるのか。このライトアップとイルミネーションで使うライトを再利用するとかではない、全然別物なのかということを聞きたいのですけどとの意見を述べました。","respondent":"立川文化観光課長","answer":"ですから、もともとこちらも昨年度から実施しておりますので、一応ライトアップの機材については別途確保してあるというふうに聞いているところです。設置についてだけ委託で実施をするものです。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"別途ということは、この予算額外でということか尋ねました。","respondent":"立川文化観光課長","answer":"この全体の予算額の中に、ライトアップ経費についても含んでいるです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"確認","question":"ご説明がなかったので確認の意味で質問するのですけれども、これで先ほどと同じように回遊性を出すということなのかという確認と、大人も参加しやすいような形になっているのかというところをお聞きしたい。","respondent":"立川文化観光課長","answer":"委員ご指摘のとおりでございまして、スタンプラリーを全館回ると１枚の絵ができ上がる。その景品としまして、瓦割体験ができるですので、子どもから大人までぜひスタンプラリーに参加していただきたいというふうに考えているところです。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのは、イベントが各種ありますけれども、どういう方がどうやって選んでやっているのかというのを説明するよう求めました。","respondent":"立川文化観光課長","answer":"この４課が絡んでいるイベントでございまして、またいわゆるイベントの企画をするプロ等のご意見等も伺いながら、全体の計画をつくっているものです。","id":"exchange-028"},{"speaker":"大倉委員","kind":"質問","question":"もう１点は、このいろいろなイベントが区内の人たちとどういう関係があるのかを教えてください。そういうチャンバラをできる人たちが品川区内にいて、そういう区内の人たちがやっているものを選んでいるのか、そのあたりを説明するよう求めました。","respondent":"立川文化観光課長","answer":"こちらにつきましては、いわゆるこの辺のプロジェクトを実施している実施団体がございまして、例えば品川のイベントで実施するのであれば。この辺につきましては、いわゆる担当者がいろいろ考えまして、この辺の企画を考えているです。","id":"exchange-029"},{"speaker":"大倉委員","kind":"質問・要望","question":"ギネス記録があるよと行っていただきたいのですが、品川区はこんなことをやっていますよというのをどうやってアピールしていくかというのが大事だと思うので、その辺の考え方を最後に説明を求めました。","respondent":"立川文化観光課長","answer":"ちょっと説明を訂正させていただきたいのですが、ギネス記録によって、そういったものを提案していただいているものです。区民委員会の皆さんもぜひご参加いただきたいと考えていますので、よろしくお願いいたします。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"参加人数の見込みがあれば、どの程度、どう考えていらっしゃるのか伺いたいと思います。","respondent":"立川文化観光課長","answer":"一応５,０００人、頑張らせていただきます。","id":"exchange-031"}]},{"id":"topic-05","title":"スクエア荏原 観光案内およびカフェ施設の開設","agenda":"スクエア荏原 観光案内およびカフェ施設の開設","exchanges":[{"speaker":"田中委員","kind":"意見","question":"どこをターゲットに絞っているのかとか、ちょっと何かぼやけているような気がして、ご説明いただけたらと思うのですけどとの意見を述べました。","respondent":"立川文化観光課長","answer":"中につきましては、かなりいじるです。そんな施設の考え方になっておりますので、見方によっては、何かぼやけた感じというご意見もあるのかなというふうに思っているところです。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"スクエア荏原そのものがまだそんなに古くないというか、それでもやはりカフェをちょっと大きく変えていかなければいけないくらい危機的状況に陥ってしまったのか尋ねました。","respondent":"立川文化観光課長","answer":"荏原地区にはない観光案内所機能をどう持ってくるかというところが中心ですので、カフェを中心に考えていただくよりは、いわゆる観光情報をどう発信していく施設になるのかというところに注目していただきたいというふうに考えているところです。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"そうしたら、観光案内がメインということが施設や名前とかにないと、もともと荏原地域の人たちにとってはカフェとしての場所ではないですか。それはこのカフェ内なのですか、それとも広場のところに出して、そういうオブジェを飾るのかとかも聞きたいのですけど。","respondent":"立川文化観光課長","answer":"それから、いわゆるシナモロールのオブジェですけれども、こちらにつきましては、お店の上のほうにちょっと空間があります。外から見ても、「あれは何だろうね」というふうに思っていただけるような、そういったものを配置したいというふうに考えているところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"地域の人間としても、観光に来た方たちにどこがお勧めと聞かれることとかがあるではないですか。そういうときに、カフェとかシナモロールが先行するのではなくて、地域の方も理解できるような観光案内所になるようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の席数とか、どういうふうに変わるのかというところをもう少し教えていただければと思うのですが、広くなるのでしょうか。ちょっと聞いた話によると、なかなかいつもいっぱいで入れないという声も聞いていますので、教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"先ほどご説明したとおり、３商店街の真ん中にある、またこの場所がたまたま確保できたというところもあります。そういった意味では、ちょうど真ん中にあるという立地というのは、バランスよく情報提供ができるのかなというふうに考えているところです。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"観光案内所としての役目もなかなか果たせないのかなと思いますので、そこは周知をしていってほしいと求めました。カフェの受付と観光案内所の受付が一緒になるということですかね。","respondent":"立川文化観光課長","answer":"周知につきましては、最善を尽くして実施していきたいというふうに考えております。委員からご指摘がございましたいわゆる総合受付とは別でございまして、カフェと観光案内につきましては、同一のスペースです。","id":"exchange-037"},{"speaker":"大倉委員","kind":"質問","question":"そういったところの考え方についてはどうでしょうかというのと、ものすごい発信力があって、そういったものの提供とかというのができるのか。それが観光協会の方たちでもできるようなものがあるのかというところの考え方とかを説明するよう求めました。","respondent":"立川文化観光課長","answer":"ここを目指して来てもらうためにどういったことができるのかというのは、今後ともいろいろ工夫していかなければならないというふうに考えております。そういったこともいろいろ試行錯誤しながら、この施設を少しずつ充実させていければなというふうに考えているところです。","id":"exchange-038"},{"speaker":"大倉委員","kind":"意見","question":"さらに口コミで広げてもらうとか、品川区に誇りを持ってもらうとか、例えば先ほどのギネスの世界記録もそうだと思うのですね。大変だと思いますけれども、いいかなと思いますので、頑張ってくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"このしながわ観光協会の方が観光案内をして、カフェとコーヒーとかを提供するのでしょうか。情報提供をしながらという感じになるのか尋ねました。","respondent":"立川文化観光課長","answer":"いわゆる運営の中身、どういった感じなのかなですけれども、当然観光案内機能とカフェ機能がありますので、同時にはできないです。それで、人員については複数配置ということを考えているところです。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"今年の１１月ですよね。１１月に開設で、今まだ人の配置は確定していないのか尋ねました。","respondent":"立川文化観光課長","answer":"基本的には、カフェ機能の運営については、カフェおよび地域コミュニティの専門の事業者に委託するという形で進めているところです。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"今回の資料には、運営としてしながわ観光協会だけが書かれていたのは、これは観光案内をする方たちで、カフェのほうは書かれなかった何か理由というのはあるのか尋ねました。","respondent":"立川文化観光課長","answer":"位置づけとしましては、いわゆる観光案内について運営いたします。それから、考え方としましては、カフェ機能については、観光協会の独自自主事業といった位置づけになっております。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"次からは、もうちょっとわかりやすい資料の提供をお願いしたいと思います。要望です。","respondent":"立川文化観光課長","answer":"資料づくりにつきましては、なるべくわかりやすい内容を心がけてまいります。","id":"exchange-043"}]},{"id":"topic-06","title":"第５回障害者水泳大会の開催","agenda":"第５回障害者水泳大会の開催","exchanges":[{"speaker":"田中委員","kind":"質問","question":"その水泳教室に入っていなくても、興味がある障害のある方たちが見学とか参加することというのはできるのか、できないのか、どうなのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"障害者手帳や愛の手帳の交付を受けている方ですので、障害者水泳教室に参加されていない方もこちらの水泳大会にご参加いただくことも可能です。実際には、昨年も身体障害の方もいらっしゃいましたし、聴覚障害の方もいましたので、いろいろな方が参加されております。","id":"exchange-044"},{"speaker":"大倉委員","kind":"質問","question":"２５ｍを泳げなくても、何か自己肯定感ではないですけれども、達成感というのはこういったイベントでは難しいのかなと思って聞きます。模範演技がオリンピックメダリストというところでは、パラリンピックの選手とかというのは難しいのですかというところを説明するよう求めました。","respondent":"池田スポーツ推進課長","answer":"パラリンピックのパラリンピアンも実際には検討させていただいたのですけれども。そこら辺は検討させていただきました。","id":"exchange-045"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"改めてお伺いしますが、まず消費者センターの目的について教えてください。それと、最後に、担当の課としては、消費者センターの今後の課題はどういうふうに思っているか説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"これは出前講座などで相談員が行って、そうした意味で９０％という数字をご紹介させていただいたということでご理解いただきたいと考えています。","id":"exchange-046"},{"speaker":"藤原委員","kind":"質問・要望","question":"増加傾向にあるのではないかという答弁をいただいて、こういうことこそ行政がやるべき仕事の一つだと私は思うのですね。目的の中に入っているわけですから、しっかり守っていっていただきたいという思い、その辺についてご答弁ほしいと求めました。","respondent":"山崎商業・ものづくり課長、菅生活安全担当課長","answer":"必要な措置は検討を考えていく余地はあるかなというふうには思っていますが、それから昨年からやり始めましたけれども、地域にいるサポーター養成。ただ、委員おっしゃった意味での充実というものも… 特殊詐欺の関係なのですけれども、認知していただいて、何とか被害を未然に防いでいくということが一番肝心かなというふうに考えております。","id":"exchange-047"},{"speaker":"藤原委員","kind":"質問・要望","question":"単身の高齢者も増えていくわけですから、やはり生活安全、例えば電話通話録音機を取りつけてというのをやられましたよね。区というのは区民にとって一番身近な行政ですから、ここら辺はきちんとしっかり守っていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"大きなところでちょっと伺いたいのですけれども、八つあって紹介させていただきたいのですけれども、これに基づいて区のほうでも事業をやっているのかということをまず確認させてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"一口で、私ども今の表現を賢い消費者でありますとか、そういうようなことで普及啓発に努めているようなところです。これは東京都と連携しておりますけれども、今おっしゃられた基本的な消費者の施策の部分については、貫いているところです。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこを確認させていただきたいのですが、あと１人当たりの担当件数というのですかね、そういうものがあれば教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"この３名常時配置体制になりましたのは、それは日によっては２人で回すしかない日が出てしまったりとかということが実はありました。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"相談員が今６人ということで、これは交代の頻度というのですか、この交代の頻度はどういったスパンになっているのか伺います。","respondent":"山崎商業・ものづくり課長","answer":"それぞれ専門家の方が品川区で３日、例えば他区で２日とか、そういう方も実はいます。そちらの講師を実は残りの２日間でやられていたり、その辺はそうしたことで、ご理解をいただければというふうに思っているところです。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に確認なのですけれども、相談員の方の希望でというのですかね、それで専門非常勤ということになっているということでいいのかということを確認させてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"もちろん勤務をしていただくときに当該ご本人の希望ということで品川区の消費者センターに来ていただいているというふうに考えているところです。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"住宅のリフォームの業者なのですかね、近くに来たので、そういった事例というのは品川区にはあるのか。そして、その場合、どういった対応をされているのか伺います。","respondent":"山崎商業・ものづくり課長","answer":"それから、８階で施工業者として来て、下を見たら屋根が大変な状況になっていますよというように入ってくるパターンがすごく多いそうなのですね。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"消費者団体というのは区内にもあると思うのですけれども、そういったところへの支援というのはどういったことをされているのか伺いたいと思います。消費者団体が区民に消費の仕方というのですかね、そういったことを広げるためにも大きな役割を発揮しているところもあると思うので伺います。","respondent":"山崎商業・ものづくり課長","answer":"２月にはなかなか消費者団体のほうも、近年団体の構成員の高齢化などによって活動が以前と比べるとなかなか活力がということも一つ課題です。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"気軽にというのですか、すぐ相談する場所がわかるというのがやはり必要だと思いますので、周知をしっかりとやっていってほしいと求めました。これは意見として言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"大倉委員","kind":"質問・要望","question":"最初にちょっと教えていただきたいのですが、大体１件当たりどのぐらい相談する時間というのはかかるのですかというのと、何かもしそういうようなデータがあれば説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"さまざま、ケース・バイ・ケースといいますかね、そういうことかなというふうに考えております。必ず詐欺まがいのこと、救済した金額１億４,０００万円で百七十何件を割返すと、そういう意味では８０万円かなというようなところで把握しています。","id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば平成２９年度に相談件数２,５８５件ということで、それというのはちゃんと相談は受け切れているのかなというところを教えていただきたい。しっかりお一人お一人対応していると思いますが、そういったことも検討の余地があるのかなと思っているのですが、その辺について。","respondent":"山崎商業・ものづくり課長","answer":"その結果、３名の体制であれば、相談に今現在はしっかり応えていける体制になったなというふうに考えているところです。時間によっては同時に３人の方が相談中で、概要を職員も聞き取り、体制としては一定相談にしっかり対応できていると判断しています。","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"今はそういう意味では全ての人に対応ができているということで確認しました。１点、より相談をいつでもどうぞというサービスを大きくしていくというところの考え方について教えていただきたいのと、土曜日はやっていますよね。","respondent":"山崎商業・ものづくり課長","answer":"最適であるかどうかというのは常に研究していく必要はあるだろうなというふうに思っているところです。それから、ホームページにつきましては、大至急しっかり確認をして、当然正しい現状を示す表記であるべきでありますので、すぐに確認をします。","id":"exchange-058"},{"speaker":"大倉委員","kind":"意見","question":"いつでも相談できるという、手軽に相談できるというところでも、相談サービスの拡充というところでも、さまざま需要を満たしていただけるようにこれからもやっていただくというお話だと思いますので、ぜひ進めていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"今の報告は、結構大事かなと思うのですけれども、休館する期間とかの資料の提供というのは、なぜなかったのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"期間については口頭で足りると思ったので、口頭でご報告させていただきました。","id":"exchange-060"},{"speaker":"田中委員","kind":"質問","question":"そもそも「報告」と「その他」というのはどうやって分けているのかということと、その他で報告するときに、そこら辺をちょっと教えていただければ。どちらに聞けばいいのでしょうか、どなたに聞いていいかわからないのですけれども。","respondent":"池田スポーツ推進課長","answer":"私どもの考え方としましては、第５回ということで、記念の大会ということでの報告事項とさせていただきました。体育の日につきましては、こちらのほうは委員会のほうで、その他というところでイベントのご紹介ということでする形にしております。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問","question":"そのほかの、今日私たちは報告事項を聞きに来ていて、その他で何が出るというのはわからないわけではないですか。なるべくその他でも今の体育の日記念事業のように資料があっていただけると、とても助かるのですけれども、これはどなたに聞いたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほどの体育の日、しながわ観光フェア２０１８と体育の日スポーツイベントとは別でということでいいのですよね。という確認をさせていただきたいのと、どういうすみ分けというか、やっていくのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"こちら、毎年市区町村は体育の日に催し物をやりなさいよというものがございまして、こちらのほうはずっとこの時期にやっているところです。","id":"exchange-063"},{"speaker":"大倉委員","kind":"質問","question":"今までやっている体育の日記念事業に千客万来事業の中の体育の日スポーツイベントを一緒にやって、さらにやっていこうということでいいのかなと思ったのですが、それで大丈夫か尋ねました。","respondent":"池田スポーツ推進課長","answer":"はい、そのとおりです。体育の日のイベントだけれども、しながわ観光フェアの部分と全て一緒で、連携してというようなイベントになっております。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"総合体育館のほうでは、いろいろイベントがあるのですけれども、戸越体育館のほうは、企画はないということなのですか。フリー利用だけだと、いつもどおりの感じがするのですけれども、何か戸越体育館はどうしてこうなってしまったのか、企画はないのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"できるというようなことで、それでスポーツをぜひやっていただきたいということで、戸越体育館はフリー利用ということで拡大的にやっているところです。","id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2820#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":44845,"voices":183}},{"id":"h30-20180918-7","meetingId":"h30-cm09","date":"2018年9月18日","dateIso":"2018-09-18","committee":"厚生委員会","time":"午後 １時００分～午後 ３時２８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"平成３１年度分品川区立高齢者住宅（単身用）補欠登録者の募集","agenda":"平成３１年度分品川区立高齢者住宅（単身用）補欠登録者の募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"募集の時期を特養ホームの申請時期と同じような、最低でも年に２回とか、そのように増やすことはできないのかということを１つ伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"先ほどもご説明の中で触れさせていただきましたが、上から順番に空きが出たときにお声をかけするという形をとらせていただいております。今年度も６０名様程度を予定しております。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"私たちも公営住宅等々増やしてほしいという思いもあるのですけれども、高齢者住宅というところでは、やはり高齢者の方がと。その基準というものはあるのか、それで内容はどのようなものなのかを伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"実際に見に行って、どのぐらい条件がよくない住宅にお住まいか、こういったところも見しています。順位といいますか、恣意的なものが入らないように、公平な目で審査をさせていただいているところです。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。この基準というのは公表という形はないのか、そこを伺います。","respondent":"宮尾高齢者地域支援課長","answer":"ですから、今の時点では審査基準を公表するという考えはございません。どうかご理解をいただければと思います。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。去年何人申し込まれて、今の段階でどれくらい入居されているのかを伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"平成３０年度、今年の４月から来年の３月までの登載期間で、実際にご登録いただいている方というのは５５人いらっしゃいます。そのうち先週末の時点で１６人の方にお声がけをさせていただいている状況です。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問","question":"今の話にちょっと関連するところもあるのですけれども、申請資格の（２）番です。特にここをちょっとお聞きしたいのですけれども、どのような実態調査をされているのか、まずそこをお聞きしたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"申請をいただいた方のうち、住んでいる環境が悪いというふうにおっしゃっていただいた方には、実際に職員が見に行きます。そういったところもいろいろ細かく見させていただいて、記録をとり、基準に合わせて点数化をさせていただいているところです。","id":"exchange-005"},{"speaker":"こんの委員","kind":"意見","question":"いらっしゃる場合はお部屋の中も見する。頻度的にはどれぐらいの割合で、実態調査できていますかとの意見を述べました。","respondent":"宮尾高齢者地域支援課長","answer":"ご本人がご在宅の場合でも、家の中をつぶさに見るといいますか、玄関先でご本人様と基本的には会話の中でやりとりをしますので、ご不在であっても、ご在宅であっても、聞き取りをすることは差が出ないように工夫をさせていただいているところです。","id":"exchange-006"},{"speaker":"こんの委員","kind":"意見","question":"そうなると劣悪で申し込まれているからといって、感覚的で申しわけないのですけれども、順位が多分低いと思われるのです。その辺はどうなのでしょうとの意見を述べました。","respondent":"宮尾高齢者地域支援課長","answer":"必ずしも立ち退きを求められている方が上位に来ているという傾向はないというふうに認識をしております。そういったところも含めて、理由によって順位に差がつかないようにというところは、最大限配慮させていただいているところです。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"それはもういたし方ない、面談のときにやはり劣悪な部分というのはなかなか難しいというようなお話も出たりということが実はあったりします。求めている人と、どういったところが劣悪と皆さんおっしゃるのか、いかがか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"その申請をいただくそれぞれ個々の方の理由によって差がついてはいけないと考えていますので、過去の事例ですとか、そういった相談事例もそうですね。そういった過去の蓄積、データを最大限に活用し、大事にしながら、今後も適切に募集の受付事務を行ってまいりたいと思います。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それから入れた方は１６人ということで、平成２８年度だと申請者が何人いて、その申請者と入居者の数を説明するよう求めました。","respondent":"宮尾高齢者地域支援課長","answer":"先ほど今年度、今現在登録には５５人の方が名簿に登載をされていらっしゃるというふうにお答えしたとおりです。ちなみに昨年度は最終的にご案内でお声をかけさせていただいた方が３８人、３８番の方までお声をかけさせていただいたという実績です。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ということは、申込者全員が基本的に登録者ということになるということで考えてもいいのかという確認を１つお願いしたいのと、あともう一つ。２回ぐらいにふやすというような検討をぜひお願いしたいという意見と、高齢者住宅にしても、その点だけお願いしたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"募集時期を年２回なり、高齢者住宅の入れ替わる頻度というのは、かなり違いがあるのかなという認識です。もちろん利便性という面では検討しなければいけないことなのかもしれませんが、今のところはこのやり方をやらせていただければと考えています。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどお聞きしたところでは５９人申し込まれて３８人ということなので、かなりの、本当に確率の高い高齢者住宅になってきたと思うのです。そういうところでいえば、かなり以前に比べたら申請者が減っている中で、今後ぜひ検討していただきたいと要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認なのですけれども、この登載の順番というものはご本人には言っているのでしたか。その点と、それからもう一つ、今年度申し込みをしている最中の人は、新たに今年また、この申し込みをしなければいけないのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"載る方につきましては順位は何番になるということをあわせてご本人にお伝えをしています。１年間待ってお声がかからなかった方につきましては、次の年も同じように申請をいただくというような形をとらせていただいているところです。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"極端に言うと３９番だった人が、今年は１６人入居してしまっているけれども、例えば２０番目になっていると。その人が入れる可能性というのは、その辺はどのような判断をするのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"そうですね。今年度、また来年になったら新規にお申し込みをいただく方と同一のところで順位をつけさせていただいているというところが実際のところです。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"意見","question":"こういう状況だからやむを得ないのかなと思いながらも、非常にその辺が、前から感じている矛盾点かなということもあるので、何かその辺が、本人に番号を言っていて何番までいっているとわかっているだけに、非常につらいなという感じがするのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"声がけということが言われているのですが、声がけイコール入居されたのかどうかの確認です。それから入居しなかった場合の人数とか、その理由とか、ちょっと確認をさせてほしいと求めました。","respondent":"宮尾高齢者地域支援課長","answer":"実際にお声がけをすると、あくまでも推察ですけれども、そういったときに次を待ちますというふうにご辞退をされる方もいらっしゃいます。そういうことが３８人のお声がけに対して２２人の入居という差に結びついているのかなというふうに考えております。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"これは余り所得のことは出ていないですけれども、そういうところの新しいサービスも含めた、その他のサービスというものはどうなのか。平成２９年度でいうと２１名、この２１名の方への、様子はお聞きしているのか。","respondent":"宮尾高齢者地域支援課長","answer":"そのエリアに近い、強い、そういった個々の不動産店をご紹介させていただいたりということも適宜やらせていただいているところです。それと、登録期間が１年間で、そういう場合にはお手数ですが来年度もお申し込みをくださいというようなご案内はさせていただいているところです。","id":"exchange-016"}]},{"id":"topic-02","title":"東品川シルバーセンター大規模改修に伴うゆうゆうプラザ化","agenda":"東品川シルバーセンター大規模改修に伴うゆうゆうプラザ化","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"ゆうゆうプラザの中身は進んでいるので、それに対して反対するものではないです。その上でなのですけれども、もう始めているのでしょうけれども、実際工事に入ったときにはどのぐらいの金額を見込んでいるのかを１点説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"今回は老朽配管工事をベースに内部も手を加えする予定でおりますので、大体なのですけれども、５億円程度見込んでいるところです。ただ、これはあくまでもまだ設計段階の数字になりますので、今後ちょっと変動する要素は大いにあるということをお含みいただければと思います。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"意見","question":"文化センターも含めて５億円というのか、それからこの建物はご承知のように古い中で、都営住宅との絡みが出てきます。配管というのは品川の文化センターとシルバーセンターだけで配管をやるのか、都営のほうは大丈夫なのかということがちょっと今気になったところですとの意見を述べました。","respondent":"宮尾高齢者地域支援課長","answer":"先ほど申し上げた約５億円という工事費の概算ですけれども、延べ床面積約１,４００m2、この部分についての金額ということになります。給排水管の系統も別系統になっておりますことから、都営住宅は今回は一緒にやるという話は伺っておりません。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"では文化センターは別にお金がかかるということで、部署が違うから少し答えにくいところもあるけれども、それはどのぐらいというのはこちらではわからないか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"すみません。先ほどの金額はシルバーセンター部分のみということになります。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"なぜ金額にこだわったかというと、これはここの部署ではないので非常に言いにくいところなのだけれども、もう４７年の建築ですよね。だからそういう面で、このゆうゆうプラザはいいのだけれども、本当に区としていいのという、答えようがないかなというところなのですがとの意見を述べました。","respondent":"宮尾高齢者地域支援課長","answer":"その点はもちろん検討させていただいて、最終的にやはりあの建物は、基本的に今回の工事でも大規模な用途変更のようなものはできないと。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この建物の問題をここでやっても、これ以上お答えもできないし、別の場所になってしまうかなというところにまた絡むと悪いのだけれども、先ほどここの建物の中の浴室をいっぱい使っていらっしゃる中で、この期間中の話がなかったのですが、この間はどうなってくるのか説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"ここ東品川シルバーセンターというのは、全シルバーセンターの中でも一番入浴サービスをご利用いただく方が多い施設となっております。今考えているのが、半分の広さにはなってしまうのですが、継続をできればと思っているところです。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"だから逆に言うと、都営第３のところにも公園がありますが、例えばそういうところを利用した形の短期間浴室か何かつくれないのかと。この工事をしてそれをやったときに、費用的なものから考えると、その辺検討はされたのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"どちらも検討はさせていただいたところではありますが、多少工期に影響が出る部分はあるかと思いますが、今回半分ずつ工事を入れさせていただけたらと思っているところです。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"平成３１年度、最初からそういう考え方で設計していれば、何か方法はあったのではないかということは感じるところもありますけれども。これは配管というのは、昔清掃工場からお湯を持ってきていた、その配管の関係なのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"確かに運河のところを通って設備は残っているところかと思うのですが、今はもう使われていないということで、もうかなり前に、ちょっと具体的な年月まではわからなかったのですけれども、今はもう使われていないという状況です。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"意見","question":"報告はわかったのですけれども、余り賛成はしにくいなという考えのもとで、これも意見しか言いようがないのだけれども。別の場で少し聞きたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですから、地域センターとか増やしてほしいという声も、さらにその消防の土地というのは使えないのかなとなってくると思うのです。ですから私も隣の消防の土地というものは、有効に活用していただけないかという思いはあります。","respondent":"宮尾高齢者地域支援課長","answer":"代替施設、周りにお風呂施設のあるシルバーセンターを丁寧にご案内していくなど、その辺はしっかり丁寧に対応させていただきたいと思っています。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"指定管理の公募型のプロポーザルで１事業者しか来なかったというところで、ここはそうならないようにしてほしいなと。今回そのように、複数に応募してもらうために前回の指定管理が１事業者しか来なかったというところでの、何か対策は考えられているのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"ＰＲの体制を整えるということ、それと事業者の方が手を挙げていただきやすい魅力的な施設であるということかなと考えています。前回の１事業者であったということを反省すべきところは反省して、相手のあることですので、ここばかりは我々ができる最善のことは尽くす所存です。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"提案","question":"複数来ていただいて、その中から自由提案などもある中で選定していくわけですので、やはり複数あるべきものだと思います。それと、居ながら工事が難しいということで、区民が使えない期間というのはどれぐらいになるのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"公募期間のことに関しましては、周りの他の事例等も参考にさせていただきながら、最適な期間設定をさせていただきたいと考えています。場合によっては１年、１２カ月近くになるかもしれないというところで、今話を進めさせていただいているところです。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"浴室に関して、近隣のシルバーセンターをご紹介するということで、近隣というとどの辺まで含めて考えているのかということをまず説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"我々今の時点で考えしていますのが、近隣といえるかということはあるのですが、北品川シルバーセンター、南品川シルバーセンター、南大井シルバーセンター、以上の３カ所で考えさせていただいているところです。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問","question":"僕は余りわからないのだけれども、例えば南品川でいうと、非常に狭い中でカランも３つか４つしかないところに、男性と女性交代でやっている。もう少し広げてあげないと厳しいのではないかなと思うので、その辺開設時間を検討してもらいたいと思うのですが、いかがか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"そこはこれから少し詳細に、今周りのシルバーセンターでどのような浴室サービスのご利用状況なのかということをしっかり見きわめた上で、対策を考えさせていただきたいと考えています。","id":"exchange-029"},{"speaker":"若林委員","kind":"確認","question":"将来的にはどういう方向性を、ここにおいては考えていくのだと、そういう方向性というものは何か考えられているのですか。それをちょっと確認します。","respondent":"宮尾高齢者地域支援課長","answer":"今回の大規模改修は、それによってきちんと快適にご利用いただける期間というものを考えさせていただいて、その上で今回この計画に至ったです。","id":"exchange-030"},{"speaker":"若林委員","kind":"確認","question":"では確認だけ。どこかで委員会で当然報告されていると思うのですが、確認したいと求めました。","respondent":"宮尾高齢者地域支援課長","answer":"天井から少し水が垂れてきてしまっているとか、そういった事例もありまして、対症療法的に対応してきたという経過があります。このままそれを放置しておくと、しっかりと休館期間をとらせていただいて工事をするという判断に至ったところです。","id":"exchange-031"},{"speaker":"石田（秀）委員長","kind":"提案","question":"一番長いものでも４７年ぐらいだから、それは所管のほうが詳しいでしょうから、ぜひそれもまた違うときに質問します。この建築１つというか、内装という考えがなかったのかどうかとの意見を述べました。","respondent":"宮尾高齢者地域支援課長","answer":"その内装業者を建築の業者と別にさせて、その考え方をしっかり独立させてという検討までは、今回この東品川に関してはなかったと思います。ちょっと今後の勉強とさせていただきたいと思います。","id":"exchange-032"}]},{"id":"topic-03","title":"の２の所管事務調査","agenda":"の２の所管事務調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"皆さん手帳保持者になっていたのかということを伺いたいということと、あとこの発見経路の関係機関というのは大体どこなのかということを具体的に教えていただきたいということと、その件数を伺いたいと思います。","respondent":"榎本荏原保健センター所長","answer":"２７件のうち１６件ぐらいが手帳保持の方でいらっしゃいました。措置入院の件数ですが、ちょっとはっきりとはここのところはわからないのですけれども、このうちの半数前後ぐらいの件数だと思います。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"意見","question":"これたしか４月からこの事業が開始されていて、その時点で５月の厚生委員会で報告された際には、７件もうこの事業でやられている。そうするともう１００件、１００人を対象者として考えているということは、このように思われているということなのですねとの意見を述べました。","respondent":"榎本荏原保健センター所長","answer":"それぞれ各保健センターで導入検討会議を行いまして進めているということなので、一応多目で見ると１００件ぐらいかなと思っておりまして、そのぐらいは増えていくというふうに考えております。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"区内全域を見た中でどうして１００件と出るのかということをちょっと伺いたいのと、具体的に何のことなのかという素朴な疑問です。訪問看護も１つの福祉サービスになってきてしまうのではないかと思うので、この福祉サービスは何なのかということを伺いたいと思います。","respondent":"榎本荏原保健センター所長","answer":"質問の後のほうの福祉サービスのことについて、先にご説明します。それからどうして１００名かですが、このぐらいの件数が想定されるということで最後に整理した件数が１００件ということになります。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"最長で１年というふうにあったと思うのですが、そうすると１０月ぐらい、そういうものはもう見えてきているという状況なのでしょうか。それがどのぐらいいらっしゃるのかということを伺いたいと思います。","respondent":"榎本荏原保健センター所長","answer":"半年を目安に、対応をどうするかという検討はしていくと思いますが、普通の支援の状況に戻すというような形の整理の仕方をしていくのかなと思います。ケースによっては、そのような整理になると思います。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。同行受診、ちょっと細かく１事例でもわかるものがあるとよかったなと思うのですが、ここでちょっと言えるものというのは何かありませんか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"２７件それぞれ全部支援の仕方が異なってきておりまして、それは支援会議でその方の課題に合わせた支援の仕方というものを検討して。個別支援会議で治療再開をまず目指そうということで、あったりしますので、症状が一気に安定していったというような方もいらっしゃいました。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"地域支援体制の強化が求められるようになったということで始めたものということになってくるかと思うのですけれども、違うのでしょうか。要は特別な支援がこの事業で、それで安定してくると普通の支援に戻る、そういうイメージか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"もしくは地域で非常に多職種で治療を支援していく体制を整えておくことが大切だろうということを考えて、体制づくりをしておりました。国のほうもまだ法改正は予定はされていてしていないのですけれども、その動きと退院後の支援がなされたというのと。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"聞き方がおかしかったら指摘してください。あれは平成３１年度の事業になってしまうとは思うのですけれども、このサポート事業と、その辺を教えてもらえればと思います。","respondent":"榎本荏原保健センター所長","answer":"保健センターではこういったチーム支援ということで、区全体の地域の精神保健について課題を検討していく、一緒に地域の課題を検討して解決していくというようなところでは。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今お話あった連携のところで、地域の病院というより今度は区の中の直接の指定管理になってしまいますね、ここだけが。ですから区が指定管理することだけに、ぜひうまく連携をとってもらいたいなと、これはもう今お答えあったから要望としておきますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どこがどう違うのかということをもう少しわかるように教えていただきたいと思うのですけれども、各保健センターに１人精神保健相談員、臨床心理士か。だから、今までのものにその方がプラスしてチームというような形でやっているという、そのような感じで考えていいのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"今までとチーム支援のあり方がどのように違うかというご質問かと思うのですか、対応の仕方を考えていって実践していたという状況です。この方はどのような方向に行ったらいいのかということを検討して、深かったりというところが、手厚い支援になってきているということです。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"この導入検討会議ということは患者を支援の対象にするかどうかということですよね。面接相談、そういうものが今までよりもどれぐらい増えたのかというあたりもお答えいただけるものがあれば、ちょっとお答えいただけたらと思いますとの意見を述べました。","respondent":"榎本荏原保健センター所長","answer":"個別支援会議の頻度についてのご質問ですけれども、先ほどの導入検討会議の後行いますので、そういうことではないです。こちらもかなり何でしょう、電話でかなり細かく支援をできた結果、その方に合わせた支援のスタイルと頻度は増えてきているのは事実だと思います。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この事業が１人に対して６カ月から１年というようなことなのですけれども、あるいは１年の後のモニタリングをされていくということはどう考えられているのかということと、そのようなところとの連携はどのようにされているのか少し教えてほしいと求めました。","respondent":"榎本荏原保健センター所長","answer":"１年後の状況というか、終了と申しましても通常の支援に戻るということで先ほどお伝えいたしましたけれども、３カ月後に確認するとか。それから総合支援法等の計画との連携ということで、先ほどの退院後支援のガイドラインについてもまだ動き出したところで、いずれにしても。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保健センターとしては１人の精神保健相談員の方が、臨時のというか、非常勤のフルではない方が１人増えただけという状況だと思うのです。今回も改めて実感してきたところなのですが、そういう点でいえば、ぜひ保健師を増やしていただきたいという要望をさせていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"こんの委員","kind":"質問","question":"近隣住民からというところをちょっとお聞きしたいのですけれども、家族のある方、家族のない方いらっしゃると思うのです。どういう形でお受けしていただいて、近隣の方も安心できる、そうしたものへの対応というものはどのようになるのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"はご本人についても、非常に何らかの不安をお持ちの場合が多いです。やはり一番初めにご相談いただいた近隣の方にも、経過なり、このような状況ですということをお伝えしているというのが一般的な流れになります。","id":"exchange-045"},{"speaker":"こんの委員","kind":"質問","question":"一応お受けした、この方はこのように考えていますというような方向性だけでもお知らせしてあげると、近隣の方もご心配が少しなくなるのかなと。そういったところでもご協力を自然な形でいただくということも、１つ大事なことかなと考えますが、そういった点いかがお考えか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"連携ということでいいますと、その方のよりよい支援をということでご相談しながら、今後も進めさせていただきたいと考えています。","id":"exchange-046"},{"speaker":"こんの委員","kind":"質問・要望","question":"ご家族が近くにいらっしゃらない単身の方は、特にご近隣の方のそうした情報が大事な場合があると思うので、今おっしゃってくださったような連携で、ぜひ進めていただきたいという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"若林委員","kind":"質問・要望","question":"１つ、この初期の導入段階で、品川区としては男女比と年齢別をどのように捉えられているかというものを確認させてほしいと求めました。短期間の中で４分の３の方に導入効果ありと、その辺の導入後の変化の評価といいますか、分析もこの初期の段階で確認させてほしいと求めました。","respondent":"榎本荏原保健センター所長","answer":"大きく変化があるわけでは、分析というところまではちょっとご説明しにくいところがあるのですけれども、想定した結果だったと考えております。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"まずは一番の初期段階かもしれませんけれども、効果なのだということは、僕は大いに高く評価したいと思います。家族支援に効果が今後出るような、今のそういう意味での課題と、今後の方向性とか連携のあり方というものがあれば確認させてほしいと求めました。","respondent":"榎本荏原保健センター所長","answer":"１つの流れとしては、障害者福祉課でされている地域生活安定化支援事業につながる方が、そのように１つは整備できるかなと思っています。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問","question":"ですから、それはどの分野も含めてあるので、もしかしたらそこは１つ大きな課題があるのかなと思います。これもまたしっかり研究課題として捉えていただいて、今後の事業の拡充に期待をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3518#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":41497,"voices":124}},{"id":"h30-20180918-8","meetingId":"h30-cm09","date":"2018年9月18日","dateIso":"2018-09-18","committee":"建設委員会","time":"午後 １時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"第２９回東京都道路整備事業推進大会","agenda":"第２９回東京都道路整備事業推進大会","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"２３日の会は、以前の委員会でも報告がありましたけれども、代表で委員長、副委員長、大沢委員に参加していただくということで、その前に一回我々集まったりする必要もないということでよろしかったか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"品川区における温室効果ガス排出実績","agenda":"品川区における温室効果ガス排出実績","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"これは、引き続きというのは３・１１の後を示しているのかどうか。それと、これがどうして排出量の削減につながってきているのかというところのこの根拠について、もう少し詳しく説明を求めました。","respondent":"小林環境課長","answer":"２点目ですが、普及ですが、例えば電化製品等々につきましてはやはり耐用年数があります。今回今年の３月に策定しました環境基本計画の中でも、１０年前と比較して、やはり節電につながったものかと考えているところです。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区民の方に説明をするのに、本当にそうなのかなというところで、もう少しわかりやすいものをぜひ教えていただきたいというところです。この２点について、もう少しわかりやすくというところと周知・啓発について、お答えほしいと求めました。","respondent":"小林環境課長","answer":"それらの見せ方、やり方につきましては、もう少しわかりやすく丁寧に、改善できるところはないかも含めて、今後の検討課題となってくると思います。来年２月に開催される予定の環境講演会の中でもしっかりお示しして、より細かな啓発に努めてまいりたいと考えています。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"具体的な目に見える形での環境問題への対策をぜひ少しずつでもやっていってほしいと求めました。先ほど食品ロス削減が、このＣＯ２排出量について非常に大きな影響があるということがあったのですけれども、そこだけもう少し詳しく説明を求めました。","respondent":"小林環境課長","answer":"まず１つ、平成２７年度ですが、本来食べられるのに捨てられてしまう食品が６４６万トンと言われてあります。食品ロス由来と言われるものが約１５％ぐらいあるということが示されてありますので、区としても啓発に努めていきたいと考えています。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと概要を教えていただきたいのと、ここら辺ももっと強化していっていただきたいという思いがあるのですけれども、いかがか尋ねました。","respondent":"小林環境課長","answer":"区有施設の中で、今、３４施設に導入が進んでいるところです。今後も施設を建設する、太陽光も含めて再生可能エネルギー導入を検討していくということが、設置については引き続き進めてまいりたいと考えています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"でも、品川区全体の量は、この業務部門の排出量という点では大体どれぐらいになっているのか伺いたいと。ぜひそうすべきだと思うのですけれども、いかがか尋ねました。","respondent":"小林環境課長","answer":"業務部門の細かな数値のところかと考えていますが、業務部門では平成２５年と比較して、１６.６％削減されております。こういった削減が進むことも今後もまだまだあると考えていますが、業務部門に対してしっかりと区として発信していきたいと考えています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"しっかり部門ごとに、やはりどのような削減状況になっているのか。目標値などもしっかり定めていって、きめ細やかな排出削減の実現に向けて、見える化をぜひしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"２つほどお伺いいたします。そうなってきたとき、どのようにマニュアルをつくっていくのかというところ、この２点をお願いします。","respondent":"小林環境課長","answer":"そういったところを計画的に実施することで、この１６％は達成できると思ってあります。今考えられるものとしては、例えば照明器具等についても適切な検討方法、マニュアルづくりを進めていきたいと考えております。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"区有施設については１６％減という、今までのＬＥＤ化の効果もあるでしょうから、おそらくは達成できるのかなと直感的にわかります。最後１点だけお願いします。","respondent":"小林環境課長","answer":"区におけるまちづくりという観点かと考えていますが、今回この３３％削減の目標値も、ある程度将来予測も含みながらこの削減値を設定したです。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"一番左下の業務部門のところで、自動販売機についてちょっとお伺いしたいのですけれども、自動販売機の温室効果ガス対策について、区はどのように現状取り組まれているのか、教えていただけますか。","respondent":"小林環境課長","answer":"自動販売機に対する削減ですが、細かくはその自動販売機自体がどこに設置されているかということです。明るい時間帯であれば電気を消して自動販売機を運用させるとかいう方向で、節電対策を各メーカーのほうでもやっているという話は聞いてあります。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"節電もありますけれども、ノンフロン化という部分も今あると思うのですけれども、そこのあたり、区はどのように捉えられているか。概ね品川区内にどれぐらいの台数があるのか把握していらっしゃるか尋ねました。","respondent":"小林環境課長","answer":"ノンフロン化という観点ですが、やはり冷媒に使うことによってＣＯ２や、温室効果ガスが発生するという話は聞いているところです。申し訳ございません。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"２０２０年東京オリンピックまでにノンフロン化を１００％達成しようという数値目標があるやに聞いておりますけれども、どのぐらいか把握されているかどうかちょっとわからないのですけれども、そのあたりの取組みはされているのか尋ねました。","respondent":"小林環境課長","answer":"今、委員からご指摘ありました、例えば自動販売機に関して特化したような何か取組みというのは、今の段階では特に行ってはございませんが、先ほど申し上げましたように節電に対しては、各メーカーのほうで取り組んでいるというところまで把握したところです。","id":"exchange-012"},{"speaker":"大沢委員","kind":"意見","question":"特化してやるべきだと思うのですけれども、そこの取組みについて、可能であるのか可能でないのか。でもかなり難しいハードルがあるのかもしれませんとの意見を述べました。","respondent":"小林環境課長","answer":"台数の把握というところでいけば、一定調査すれば把握できるのかもしれませんが、そこについては今の段階では手をつけられる状況でございませんので、今後どういった方法が課としてできるかも含めて検討は進めてまいりたいと考えています。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"二酸化炭素よりメタンやフロンや一酸化窒素の方が悪影響が大きいとされているのですけれども、区としてはその量の問題もあるかと思いますけれども、二酸化炭素以外の温室効果ガスの削減などをこれから考えてはいかないのか尋ねました。","respondent":"小林環境課長","answer":"委員のほうからご指摘がありましたように、温室効果ガスのうち、二酸化炭素が占める割合が９５％です。あるいはフロン等については算出が非常に複雑だということもございまして、算定の合理化のために、二酸化炭素に絞って計画を策定したです。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。ただ、今後そうした目黒川のメタンガスの排出量とかは、計算するお考えというのはあるのか尋ねました。","respondent":"小林環境課長","answer":"二酸化炭素が９５％を占めるですので、まずはその二酸化炭素をしっかり減らしていくことが、温室効果ガスの削減につながっていくものと考えています。区としては、まずはそういったところでしっかりと対応して、今後につなげていきたいと考えています。","id":"exchange-015"}]},{"id":"topic-03","title":"東品川橋架替工事（その３護岸・道路復旧）","agenda":"東品川橋架替工事（その３護岸・道路復旧）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"東品川橋の架け替えについては、当時総務委員会だったので、いろいろなものが最初から出てきて大変だったということも記憶しております。ご参考までに教えていただきたいのですが、いわゆる金額がこれは増加するということになるのか、ご参考にお聞かせほしいと求めました。","respondent":"多並道路課長","answer":"工事の工程の中でのいろいろな増減を含めまして、現時点の工事金額を確認した結果、変更なしで済むというところで考えております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"その新設護岸が広がる理由があれば教えていただきたいのと、平成２０年度からやっているということなので、最終的に都や国などの補助金はどのくらいになるのかというのがわかれば説明を求めました。","respondent":"多並道路課長","answer":"平成２０年度から下部工、上部工、今の復旧も全部合わせて約２９億円。そのうち国費が約１０億円、都費が約１３億円となっております。","id":"exchange-017"}]},{"id":"topic-04","title":"都市計画道路補助１６３号線整備に伴う大井町線橋梁架替工事","agenda":"都市計画道路補助１６３号線整備に伴う大井町線橋梁架替工事","exchanges":[{"speaker":"西本委員","kind":"質問","question":"ここが通行止めになると、どこをどのように流していくのかと思うのですけれども、それから例えば案内板や警備の方が立つのか。ここが通行止めになると、近隣の方々も含め非常に迷惑をこうむると思うので、その対策についてお聞きします。","respondent":"多並道路課長","answer":"ただ、東急としてはそのちょうど１週間前に、その２日間通行止めする予定で考えております。来年１月ごろを予定しておりますので、う回路等もこれから協議して固めていきたいと、また地域とも話し合いながら詰めていきたいです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"１日でやるということなので。ちょっとお伺いしたいのは、財源構成というのはどのような状態で取り組むのか、お伺いします。","respondent":"多並道路課長","answer":"区としては協定を結んで、そこにお金を支払うような形の委託をするような感じで、実際には東急が事業として架け替えていくということになります。国が５５％、そのような東京都からの財源ということで、そのような構成になっている事業です。","id":"exchange-019"},{"speaker":"松永副委員長","kind":"質問","question":"私からはちょっと１点だけ伺いたいのですが、どういう形になるのか、ご説明。","respondent":"多並道路課長","answer":"今予定しておりますのが、シェアサイクルの近辺を今協議しておりまして、そこを予定しております。詳細についてはこれから詰めて、またお知らせしてまいりたいと思ってあります。","id":"exchange-020"},{"speaker":"松永副委員長","kind":"質問","question":"では、そのシェアサイクルが、また別のところに移動するという方向に進んでいくと聞き取れたのですけれども、どのようになるのか尋ねました。","respondent":"多並道路課長","answer":"今、それも含めて協議しています。","id":"exchange-021"}]},{"id":"topic-05","title":"小山台公園の都市計画変更","agenda":"小山台公園の都市計画変更","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今回削除されるところなのですけれども、これまで小山台公園の未供用部分というのがあったことの理由をちょっと教えていただきたいのと、これまではどのような用途に誰が使っていたのか伺います。","respondent":"溝口公園課長","answer":"そういった中で、公園の役割としては一定終えるといいますか、都市計画の公園の区域としては変更していくものになっております。今後そういったところも含めて土地の売買も含めまして、土地利用に合った形で都と区で連携しながら事業を進めていくといふうに聞いているものです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"確認","question":"社会福祉施設等とありますが、そういった施設の設置が可能になるということでよろしいのかということで、確認させてください。今回の変更で、何かいろいろ施設的な建設用途の縛りなどの点ではどのようになっていくのか、そこら辺を伺います。","respondent":"溝口公園課長","answer":"ただ、基本的にはこの裏面の跡地利用の方針図というのがありますので、こういったものに沿った形での土地利用が進められる。そういった中の一環の手続きとして、今回都市計画公園の区域の変更をするための都市計画を進めていくという形になっているものです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"計画の立案については、幅広い住民参加を位置づけることを改めて求めたいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-06","title":"かむろ坂公園改修工事","agenda":"かむろ坂公園改修工事","exchanges":[{"speaker":"西本委員","kind":"質問","question":"多目的広場のところ、キャッチボールができるという形になるのですが、これはほかの公園でもご相談を受けたのですが、バットは使えないのですか。そういうことを考えるならば、鳥かごみたいなものをつくってもいいのかなという感じがするのですが、その辺の考え方はどうなのか尋ねました。","respondent":"溝口公園課長","answer":"キャッチボール場を中心とした、公園の中でのキャッチボールの考え方です。基本的にはキャッチボール場内でのバットの使用というのは、野球場以外は公園の中では禁止しているというのが、公園管理の状況です。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"ゼロではないと思うのです。非常に助かっている部分もあると思うのですが、その考え方をもう少し説明を求めました。","respondent":"溝口公園課長","answer":"公園の中でも基本、全部掲示しているわけではありませんが、バットの使用の禁止というのをしっかり明示しているところもあります。ただ、少年野球はやはり練習の機会、今後もそういった同じような利用実態といったところも勘案しながら対応していきたいと考えておるものです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"できる限りベビーチェアですとか、そういったものもやはり整備していただきたいのですけれども、いかがでしょうか。それと３点目は、この工事は１０月１日からということで書かれていますけれども、説明会みたいなことは行われるのか、３点お伺いします。","respondent":"溝口公園課長","answer":"そういった問題も起きてくると思いますので、利用状況等見ながら、今後も誰もが利用しやすいトイレについては検討していきたいと考えているものです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"ベビーシートだけですと、やはり心身障害者の方とかがなかなか気軽に外出できないということで、ぜひ増やしてほしいという要望も挙げられています。やはり利用している利用者本人、そうした利用者の方々の意見も伺えるような機会をぜひ設けてほしいと求めましたけれども、いかがか尋ねました。","respondent":"溝口公園課長","answer":"かむろ坂公園につきましては、先ほどもご説明させていただいたように、近隣の地域の方たちがご利用されるところです。またこれまで公園課として蓄積した区民の声を含めて、いただいた声を大切にしながら公園整備に当たっていきたいと考えているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"確認","question":"１つ確認なのですけれども、こうした品川区の公園で、キャッチボール場がある公園は何カ所ぐらいあるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"もっと公園でそうしたボールを使えるような場所を増やしてほしいというご要望をいただいているのですけれども、バランスというのを考慮していくのか、方針としては今後どのようにお考えなのか尋ねました。","respondent":"溝口公園課長","answer":"基本的には先ほどお話ししました２２公園ありますので、そちらを使っていただくような形でお願いしています。皆様にご利用いただくといったことがまずは大切で大事だと考えておりますので、地域のご要望等も聞きながら検討していきたいと考えておるところです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"そのキャッチボール場のある２２カ所というのは、区のホームページとかでわかりやすく掲載されているものなのか尋ねました。","respondent":"溝口公園課長","answer":"ある程度公園の概要についてはホームページでご紹介していますので、そういった中でもわかるような形にはなってあります。公園課のほうに問い合わせていただければ、どこができるかというのはご案内できると思います。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"じゃあ、何か区のプレスとかでわかりやすくまとめていただければありがたいので、ぜひよろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"松永副委員長","kind":"確認","question":"ちょっと私から１点確認をさせてください。つけるのか、つけないのか、その確認したいと求めました。","respondent":"溝口公園課長","answer":"基本的には今年度を初年度として、３カ年かけて２６６公園すべてにつけることになっております。かむろ坂公園についても、今回の整備後にはなりますけれども、防犯カメラを設置したいと考えているところです。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問","question":"マンホールから水が大量に噴き出しているショッキングな映像が流れたのですけれども、あれがどこの場所なのかというのは把握をされているでしょうか。それと、東品川三丁目の道路冠水３０ｍということでしたけれども、具体的にはどこのことなのか、ちょっと教えてほしいと求めました。","respondent":"古巻防災課長","answer":"住所についてはそちらで、３０ｍの間で１０ｃｍ程度の冠水があったというような報告でした。住所だけで、正確などこという場所がちょっと今申し上げられませんけれども、住所としてはそちらだったです。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問","question":"それは支障がないのかどうかというところ、映像がかなりそういう映像だったものですから、改善ができないのかどうかというところ。ちょっとまだ昨日の今日ですから、まだそこまでの話はいってないのかもしれませんが、その辺についてのご意見を伺いたいと思います。","respondent":"持田河川下水道課長、多並道路課長","answer":"当然空気だけきれいに抜けるわけではなく、空気と水が混ざったようなものが抜けてしまうということで、かなり噴出するような映像になってしまうです。ちょっとああいった状況で何か改善策がないのかということにつきましては… 先ほどの道路の冠水の件ですけれども、今回の現場は、場所で言いますと東品川シルバーセンターの前あたりの区道になります。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"今度話す機会があったらということではなくて、やはり危険だと思うのですよ。何でそうなってしまうのか、それを防ぐ対策はないのかということでぜひ動いてほしいと求めましたが、いかがか尋ねました。","respondent":"持田河川下水道課長","answer":"繰り返すような答弁で大変申し訳ないところですが、やはりどこかから空気が抜けるということは、メカニズムとしてやむを得ない部分があります。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4244#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":29777,"voices":107}},{"id":"h30-20180918-9","meetingId":"h30-cm09","date":"2018年9月18日","dateIso":"2018-09-18","committee":"文教委員会","time":"午後 １時００分～午後 １時５８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"就学援助 新入学学用品費の入学前支給","agenda":"就学援助 新入学学用品費の入学前支給","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"入学準備に必要なものはどういうものがあると教育委員会としては考えているのか、１年生と７年生のその中身を教えてほしいと求めました。それから、１年生の場合、区の就学援助では、１年生の入学準備用品として２万３,８９０円となっているのですけれども、今回４万６００円か尋ねました。","respondent":"篠田学務課長","answer":"人数ですけれども、現在想定していますのは、小学校新１年生については、入学予定者が５５０人と見ております。入学の準備にかかるさまざまな費用についても、金額の１つの考え方として、今回引き上げられた国庫の補助基準額を参考にしているというものです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"そういうのがあって引き上げになったのだろうと思うのですけれども、この金額を決めるに当たって品川区は調査をされたのですか。その上で必要な額を算定して公表していくことがいいのかなと思っているのですけれども、そのあたりはどうだったのかを教えてほしいと求めました。","respondent":"篠田学務課長","answer":"区としまして、新入学に必要な経費を調査したということはございません。例えば先ほど委員からご指摘の国の調査ですとか、そういったものを踏まえつつ、今回は国の補助単価を踏まえた形で引き上げになっているものです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"２万円台というところもなくはないですけれども、多分そういうランドセルを購入する方が実際いらっしゃると思うのです。この金額でどうなのかなと思うので、その辺の４万６００円の構成をどういうふうに組み立てたのかというところを教えてほしいと求めました。","respondent":"篠田学務課長","answer":"１つ問題なのが、ご自身で負担されている方も当然いらっしゃいますけれども、結構いろいろご親戚の方等からいただいているという話もお伺いします。ですので、当然必要なことだと考えていますが、その辺を十分精査する必要があるのではないかと考えているところです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"そのあたりの周知はどういうふうにされようとしているのか、先ほど説明がなかったと思うので、伺いたいと思います。それと、７年生は４万７,４００円いただくわけですけれども、それに使った費用はこれだという領収証の添付とかというのは義務づけられるのか尋ねました。","respondent":"篠田学務課長","answer":"今後、社会情勢等さまざまな変化があれば、その辺は十分周りの状況を注視しながら進めてまいりたいと考えているところです。この後、例えば転入等でいらした方については、そのときに必ずお知らせするという形をとってまいりたいと考えています。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"漏れがないように、最大限努力をしていただきたいということが１つです。制服の標準服の金額が２万円となっているのですけれども、実態がどういうふうになっているかつかんでいるのか、その金額を教えていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"どういうふうになったとしても、自民党政権として今年の１０月から３年間の中で、生活保護基準の引き下げが予定されているという報道があります。そういう点についての認識、見解を教えていただきたいというのを最後に言って、終わりたいと思います。","respondent":"篠田学務課長","answer":"それから、就学援助の認定の基準等の考え方ですけれども、これまでも基本的には生活保護費の基準の１.２５倍ということで進めてきております。","id":"exchange-006"},{"speaker":"南委員","kind":"確認","question":"２万円の支給額に比して、男子も女子も相当オーバーしているという実態があり、それが確認できたと思います。したがって、この２万円も、私は引き上げる必要があるのではないかと思っておりまして、この点についてだけ答弁いただいて終わりたいと思います。","respondent":"篠田学務課長","answer":"確かにそういう面はありますので、今後、必要な検討は加えていく必要があるのかなと思いますけれども、基本的に、あくまで就学援助です。どこまで補助ができるのか、援助ができるのかといったことも考えながら、今後また進めていきたいと考えています。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問","question":"そんな中で、支給時期が１年生は２月下旬で、７年生が３月中旬と記載されているのですが、実態はどうなのでしょうか。事前に支給してもらうのでしょうから、この支給時期の後であれば、行われている時期の設定をされているのかどうかだけ説明を求めました。","respondent":"篠田学務課長","answer":"それでも１年生に関しましては、できるだけ早目にということで、２月の下旬の支給ということを考えているところです。７年生に関しましては、毎年度３回目の支給の３月のときに一緒に出させていただければということで、進めているものです。","id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"誰に支給をするかというのがわかっているわけですし、先ほど支給の人数が、新１年生と今の６年生を合わせても大体１,０００人ぐらいです。これは要望で終わりますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"石田しんご委員からもありましたけれども、実際に役立つ時期にしてほしいという意味では、その中身は何が含まれているのでしょうか。今回の４万６００円、自治体によっては上乗せもできるのかどうか、その辺も含めて説明を求めました。","respondent":"篠田学務課長","answer":"例えば２３区であれば財調の単価を基準にある程度考えているところが多うありますし、それを踏まえた区もありますし、品川区もそういったところです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"制服代は義務教育学校以外は出ていないのですから、金額を検討していただきたいのと、よりカバーしていただけたらと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"平成３０年度「秋の読書フェア」","agenda":"平成３０年度「秋の読書フェア」","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"この対象者というのは、どの層になるのですか。そこを説明するよう求めました。","respondent":"横山品川図書館長","answer":"３点のうち、１番と２番につきましては、あらゆる世代を想定しておりますが、講師が年配の方ですので、子どもさんはあまり来られないかとは思います。","id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"親御さんたちはインターネットを通じての情報収集をされる世代となっている中で、周知方法の中で唯一あるのはホームページです。区が求めている人たちにもっと届く、実行してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いいなと思っているのですが、図書館の利用状況というのは、地域的な差などはどこかで調べたことがあるのでしょうか。本当に地域の要望を聞くと、ぜひ図書館が欲しいという声がかなりあるのです。","respondent":"横山品川図書館長","answer":"大崎駅西口に、そちらでお受け取りできるように、図書館まで来なくても本を手に入れることができるような工夫はさせていただいているところです。非常に貸し出し数・返却数ともに伸びている状況で、こう言ってはなんですが、区外の方のご利用も非常に多い状況になっております。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"１つ、図書に親しんでほしいアピールをするというのは、アピールしてもらうようなことは考えられないのか尋ねました。","respondent":"横山品川図書館長","answer":"移動図書館そのものではないのですが、外に出てのおはなし会であるとか、ブックトークというような催しを積極的に行っているところです。５０冊、１００冊という単位で３カ月お貸し出しして、また検討してまいりたいと思います。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"意見","question":"年を重ねていく上でも、すごくいいことだと思うので、ぜひご検討いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"南委員","kind":"提案","question":"２番目の読書フェアなのですが、「ゆったり過ごそう」とか、少し違う部分もいろいろあるのかなと思います。提案になっているのか、その辺が何となく醸し出されてきたのかなと思ったりして、どういうふうになったのかなというのを知りたいなと思いますとの意見を述べました。","respondent":"横山品川図書館長","answer":"月に１回、秋の読書フェアについては年間で予定をしておりますので、個別のテーマをつくって本を集めてほしいと依頼しました。若いスタッフを中心に、いろいろ工作物をつくったりなど工夫しながら、テーマを決めているものです。","id":"exchange-017"},{"speaker":"つる委員","kind":"提案","question":"毎年報告されていますけれども、読書をしているとか新聞を読んでいる各家庭の子どもの成績にプラスの影響があるという報告があったと思います。どういう傾向にあるのか参考に教えていただければというのと、この間あったのかどうかというのを含めて、教えてほしいと求めました。","respondent":"横山品川図書館長","answer":"夏に行いました「読書の木」、読書のスタンプラリーで本を３冊読んでスタンプを集めると、ほかの人にも見てもらうという試みをしています。例えば、ケアが必要なお子さんであるとか、情報共有しながら一緒に後ろで見守るような形での協力の仕方をしています。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"いる場所としての図書館の、より一層の発展という意味で、そういう活用の仕方というのはあるのではないでしょうか。学習能力にプラスの効果があるわけですから、年間を通してもいろいろあるわけですので、そのあたりについて何かお考えか説明を求めました。","respondent":"横山品川図書館長","answer":"心安らいで、そこで自分の興味を広げていく場になっていくというのは、非常に大切なことだと考えています。その改訂を平成３１年度までの計画期間後に予定しておりますが、おはなし会をしたり、将来的には検討するような課題だと考えています。","id":"exchange-019"},{"speaker":"つる委員","kind":"提案","question":"前に、大きな本の持ち運びが大変なので、図書館で取り次ぎ等ができるといいのですけれどもとおっしゃっていて提案させていただいたことがありました。年間を通じていろいろな機会にあるフェア等を、一つひとつ発展のステップの機会にぜひしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"さきほど１８歳までが対象範囲だとおっしゃったので、そちらでも、区立図書館でこういうことをしているというのが在校生にわかるのでしょうか。特に２番の読書フェア、そういうところを具体的に進められているところがあれば、その例を教えてほしいと求めました。","respondent":"横山品川図書館長","answer":"『ＬｉＬｉＬｉ』という広報誌を発行はしているのですけれども、直接の行事を学校・高専向きにお知らせするようなルートがまだありません。こちらの部分についても、これから力を入れていかなければいけないと考えます。","id":"exchange-021"}]},{"id":"topic-03","title":"品川図書館エレベータ改修工事","agenda":"品川図書館エレベータ改修工事","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"一番下に書いてある誰でもトイレの３カ所というのは、１フロアに１カ所ということで、新たに誰でもトイレを設けるということなのか尋ねました。","respondent":"横山品川図書館長","answer":"各フロアに１カ所ありますので、改修工事をいたしまして、オストメイトほかの設備をつけていくような予定です。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほかのフロアに行ったりとか、大騒ぎになるので、ぜひご意見を聞いてほしいと求めました。いかがか尋ねました。","respondent":"横山品川図書館長","answer":"そういう意味では、品川図書館のトイレも狭いです。４階のトイレが一番広いので、２階・３階については狭くて、最小限の改修という形で対応してまいりたいと思ってあります。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4952#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":19571,"voices":69}},{"id":"h30-20180918-5","meetingId":"h30-cm09","date":"2018年9月18日","dateIso":"2018-09-18","committee":"総務委員会","time":"午後 １時００分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"「」を聴取いたします。 まず、(1)シティプロモーションの取組","agenda":"「」を聴取いたします。 まず、(1)シティプロモーションの取組","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"今回は東急バスではなく都営バスにしようというふうになった経緯を教えてください。例えば東急バスでは、五反田駅から川崎駅ラゾーナ広場行が結構の数１日往復していますので、なぜ都営バスだけなのかということです。","respondent":"木村報道・プロモーション担当課長","answer":"その結果として、今回もバスのラッピングをやっていくことになりました。検討はもちろんしてございまして、区外へ１台ですけれども走るというところもございまして、そういう思いでやっているところです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"走る以上は、お台場の一部に品川区があるんだよという周知も含めて事業を進めていただきたいというのが１点と、当たり前のようなものだと思うのです。それは１つの考え方で、そういう思いにさせるというのも大切なので、やはり幅広い視点で広告の打ち方はお考えになってほしいと求めました。","respondent":"木村報道・プロモーション担当課長","answer":"東八潮の紹介と、それから奇をてらった、もう少し違った観点での広報というところでございまして、ご意見を今頂戴いたしましたので、そういった観点からも検討を進めてまいりたいと思います。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"この事業の緊急性は私はないと思いますし、必要性についても、前回の委員会で申しましたような考えをもっています。伺いたいことは、日経新聞折込タブロイド紙、それぞれの費用についてご説明ほしいと求めました。","respondent":"木村報道・プロモーション担当課長","answer":"内訳ですけれども、ＪＲ京浜東北線に関しましては約３００万円で、車内ビジョン、それから中吊りを合わせてです。日経新聞の折込につきましては４４０万円、ＳＮＳ広告に関しましては４５万円、あとは諸経費となっております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"全体で１,５００万円弱ということですけれども、これは全部一般財源なのでしょうか。財源についても伺いたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"ご指摘のとおり一般財源です。","id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"一般財源を使った区独自の事業ということですけれども、苦しい区民生活がある中で、果たしてここに１,５００万円をかける必要性や緊急性があるのかどうか、やはりこれは十分検証していく必要があると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"予算のお話があって、この予算の中の全体がシティプロモーション推進経費になっている中で、どこにそれが計上されているのか。次の事業が進められるというように理解をしているのですが、効果検証というのはどのタイミングでされるのか、その辺についてお伺いします。","respondent":"木村報道・プロモーション担当課長","answer":"それから、効果検証につきましては、隔年で実施をしているメディア認知度という調査がございまして、そちらのほうは本年度末に実施をする予定です。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"常に私たち議員が事業を点検する１つの手がかりになりますので、その都度示していただけると検討がしやすいかなというふうに思います。当然、検証の結果というのは、また改めてご報告がいただけると考えてよろしいか尋ねました。","respondent":"木村報道・プロモーション担当課長","answer":"検証の結果につきましては、何らかの形でご報告をさせていただきたいというふうに思っております。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"区としては本当にこれでいいと思っているのですか。嫌な質問で恐縮なのですけれども、説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"それから龍馬に関するイベントも行いますけれども、３月に関しましては人の出入りがありいろいろな人が来る、やはり交通広告は高いのですね。その中で精査をいたしまして、委員ご指摘ありましたように、効果も検証しながら進めてまいりたいというふうには思っています。","id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"試行錯誤をしているのもよくわかります。ですけれども、やはり少し立ち止まってみるということも、私は大切なことだと思いますので、これは意見として言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今伺いましたので内容は理解をしておりますが、何点か確認なのですけれども、同じものが使用されていくと思っていいのでしょうか。このシティプロモーションの取り組みについてはどうやって発信をされていくのか、何かあるのか教えてほしいと求めました。","respondent":"木村報道・プロモーション担当課長","answer":"前回の委員会でＰＲ冊子をご説明いたしましたけれども、あるいはそれを実際に区民の方で、そういう形でご紹介をさせていただこうかと思っています。","id":"exchange-010"}]},{"id":"topic-02","title":"旧荏原第四中学校保育園仮移転改修その他工事請負契約","agenda":"旧荏原第四中学校保育園仮移転改修その他工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"どういう手法を用いるのか、周辺の方へのこの解体工事の説明はどのように行われるのか、そこを伺いたいと思います。さすがにこれはたまらないという話をたくさん伺っただけに、またできるのか、ご説明ほしいと求めました。","respondent":"小林施設整備課長","answer":"説明の方法については、１軒１軒近隣を回っております。騒音・振動を必要最低限に抑えるような工法で、現在努力してやっております。","id":"exchange-011"},{"speaker":"いながわ委員","kind":"確認","question":"済みませんが確認です。ここ５、６年か何年かずっと貸し付けと言うか、何か今後のことを見据えた改修工事なのかと思えてしまうのですけれども。","respondent":"小林施設整備課長","answer":"塀についてのご質問にお答えします。今回はプールサイドの周りの塀と一緒に、縦線のところですか、そちらのほうも今回やるということです。","id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問・要望","question":"別に何が云々とかそういうのではないので、もし、これだけ１億６,０００万円ぐらいかけて工事をするのであれば、また次に何かをするときに、また同じお金をかけてまた何かを壊すとかではなく、１回で終わればそれはいいのかなという思いがありますので、計画的にやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-03","title":"東品川橋架替工事（その３護岸・道路復旧）請負契約の変更","agenda":"東品川橋架替工事（その３護岸・道路復旧）請負契約の変更","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"もう抜かないでそのままやったとか、やらないという話も聞くのですけれども、埋設物があるかはわからないものなのですか。その都度、そこで費用がかかっているようにも思えるし、その辺がどうかということを教えてもらっていいか尋ねました。","respondent":"立木経理課長","answer":"２点ほどご質問いただいた件ですが、工期が伸びることによる費用の変更というのは、費用はかからないものと考えております。私のほうではお答えできないです。","id":"exchange-014"},{"speaker":"いながわ委員","kind":"確認","question":"絶対にそれは前の見積もりでは無理のような気がしたので質問させていただいたのですが、確認をしたほうが工事がスムーズに進むのではないかなと。そこまで建築に詳しくないのであれなのですけれども、ぜひその辺も考えて今後やってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"そもそもの変更理由が、仮締切工の構造を一部変更したことによるという、何かがずれたというふうに説明されたと思うのですけれども、ずらさざるを得ない事情があったのだとは思いますが、その理由を伺いたいと思います。","respondent":"立木経理課長","answer":"当初、囲むべきところよりも少し外側に出るような感じで、川の方に少し護岸から離れるような形にする必要となったということです。当初の計画と少しずれてしまったと聞いております。","id":"exchange-016"},{"speaker":"吉田委員","kind":"確認","question":"そうですかと言うしかないのですけれども、やってみて初めてわかったと言うか、事前の調査などで発見することは難しいものなのでしょうか。そうなることによって、橋の架けかえ自体への影響と言うのでしょうか、そういうことがないのか、その辺を確認したいと求めました。","respondent":"立木経理課長","answer":"事前の調査の部分や、設計の部分に関しては所管のほうにしっかり伝えてまいりたいと思います。こちらが半年伸びることによって大きな影響が出るというようなことは、今のところ所管から聞いてございませんので、大丈夫かと思います。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2118#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":13279,"voices":59}},{"id":"h30-20180919-14","meetingId":"h30-cm09","date":"2018年9月19日","dateIso":"2018-09-19","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時２３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"基礎自治体のあり方に関することのうち児童相談所移管","agenda":"基礎自治体のあり方に関することのうち児童相談所移管","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"２カ所視察された考察ということで、児童相談所と他機関との役割分担の２点が主に挙げられているのですが、もう少しほかにあれば伺いたい。それから、児童相談所と他機関との役割分担というのは、具体的にはどのような形なのか、イメージできるようにご説明いただけたらと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"特に熊本市は設置時期が比較的浅いというところではあるのですが、やはり同じように人材の確保が一番難しい。それとも、さらに誰かお願いされた人が行くのか、いろいろ役割分担があるです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"人材確保も含めてなのですが、どんな準備をどのようにするか、少し具体的に伺いたいのです。児童相談所は０歳から１７歳が対象だと思うのですけれども、両市はどういう年齢配分になるのか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"親御さんだからといって、必ずしも自由に子どもに会えるわけではないということを踏まえて対応していこうとしております。児童福祉法では、０歳から１７歳までという形になっておりますが、現実的に一時保護所で０歳から２歳の子どもさんを預かるというのは難しい。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"今回、視察された２カ所の一時保護所ではどのように対応されていたのかということを伺ったので、あらためてご答弁お願いします。","respondent":"二ノ宮児童相談所移管担当課長","answer":"そこについての直接的な質疑はなかったのですけれども、０歳から２歳の子ども、また車椅子が必要な子どもの設備はあったのですが、中を視察させていただいた限りでは、そういったお子さんは実際にはいらっしゃらなかったという状況です。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"秘匿性などを考えると、やはり近隣の区との連携を考えていかないと難しいのではないですかという話を担当の方がおっしゃっていました。そういうことをクリアしていかないといけないわけですから、いろいろな意味で大丈夫なのかと、私はすごく心配するのです。","respondent":"二ノ宮児童相談所移管担当課長","answer":"「おまえの家はどこだかわかっているぞ」といったことは、さすがにまた違う意味で対応しなければいけないことなのだろうなと当然認識しております。そういったさまざまな状況を見ながら、引き続き準備を進めてまいりたいと考えております。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、どんどん勉強されていると思うのですが、本当に慎重に進めてほしいと求めました。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"そのお考えをお伺いしたい。警察の方も入り、またこども総合相談センターですから、多分子ども家庭支援センターの機能も組み込まれていると思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"その後、そういった方が私どもが実施する場合でも来てくれたらいいなというところは、本当に心から思っているところであります。今回建設予定地の場所ですと、やはり庁舎からは遠い。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"品川区のハード面では、そこまでの平米数がとれるのかどうかというところもあると思うので、その辺の状況を教えてください。相談室のほかに、療育の部分での部屋などはどのように考えていらっしゃるのか、あわせて説明を求めました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"現在の建設予定地の建物の中にどこまで入るのかということなのですけれども、資料にありますとおり。おのずと入る人員数には限りが出てきてしまいますので、そこはできるだけ機能と連携を総合的に加味しつつ設計を行いたいなと考えています。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうすると、その点は非常に悩ましい点だと思います。どうか機能とハード面と両面からこのことは進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"松永委員","kind":"質問","question":"先ほど、こんの委員からも質問があったのですけれども、常勤弁護士に任期が決められているということなのですが、大体どのくらいなのか。その取組みについて示すよう求めました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"そういう問題ではないのですけれども、子どもの情操という面でもとても大事だと考えていますので、そういった面はフォローして設計する所存です。","id":"exchange-009"},{"speaker":"松永委員","kind":"意見","question":"やはり外で遊べる環境というのは、子どもたちにとってはとても大事ではないかなと思います。今後建物を建設するにあたっては、そうした場所の確保は必要だと思いますので、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"児童虐待をゼロにしていくには何が必要なのか、お考えをお聞かせいただきたいなと思います。児童虐待をゼロにするには何が必要なのか、区の考えをお伺いしたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"必要に応じて家庭訪問をするということをやった上で、今行っている区の子育て支援事業等につなげていくということが大事なのかなと考えています。そういったことを地道にずっと続けていくということがまずは大事なのかなと考えています。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"区設置の児童相談所における児童福祉司の体制は、何人ぐらいの配置を目指しておられるのか伺います。やはり時間がかかりますので、区の児童福祉司の資格を持っている方が研修に行くという計画を持って進めるべきだと思いますけれどもいかがか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"例えば法的対応が必要なケースもあれば、親御さんも子どもも非常に安定していて、あまり日常的に手をとられない業務もあろうかと思います。過去の委員会でもご説明申し上げました。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"児童福祉司と同数を目指して配置すべきとありますけれども、児童心理司の配置の考え方を伺いたいと思います。この設置基準、運営基準をどのように考えておられるのか伺いたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"ご指摘のあった児童心理司の充実というのも、当然それ相応にそろえなければいけないことですので、進めてまいりたいと考えているところです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"その辺をどのように考えているのか伺いたいと思います。東京都の児童相談所、または他区の児童相談所との連携した年齢配分も必要になるのかなと思いますけれどもいかがか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"一時保護所内での学習は、教員免許を持つ者などを配置しないといけないということは、十分認識しております。例えば朝の１限から昼の４限までと、明確に全部きっちりと分けるのは、正直なかなか難しいのかなというのは現実にあります。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"各種関係部署との連携を行うとともに、議会への丁寧な報告をこれからも求めていきたいと思いますけれどもいかがでしょうか。最後にお伺いします。","respondent":"二ノ宮児童相談所移管担当課長","answer":"仮に練馬区以外の２２区全てに児童相談所を設置したとしても、社会的養護の児童養護施設等は、都内各域に散らばっております。２点目は、ご質問というよりご要望というか、当然ご報告は折に触れて必要に応じてします。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"何か福岡市にお聞きできたり、現在のところでどうお考えなのかというところをお聞かせいただけたらと思います。今現在のお考えといいますか、福岡市や熊本市の事例をお伺いする中で、どういった可能性があるのかというところをお聞かせいただけたらと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"そういったことも必要かなと思う反面、今区内には１つ児童養護施設がございまして、そういった存在そのものを否定することもなかなか難しい。日常的な子育て支援を通じて、品川区の子どもたちがひどい状況にならないようにしていきたいなと考えています。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"世田谷区と荒川区と江戸川区の３区をモデル的確認実施区とすることが確認されたということで今進んでいると思うのです。検討する会議体の話の中で、恐らく区にも話が来ていると思うのですが、そのことも含めてご説明ほしいと求めました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"先行３区プラス中野区、東京都と世田谷区が直接協議する中で、恐らく世田谷区が説明している資料から出てくるもの。今の時点では、正直私どもとしてもまだ結論は見えていない、ずっと悩んでいるところの１つです。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひとも来年度の実施設計を含めて調査研究をしていただいて、児童相談所移管に向けて進めてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"たとえ少数でも、何人か一緒のお部屋よりもプライベートが保てるようなお部屋が必要ではないかと考えますというお話を伺ったと思うのです。集団生活を、できるだけその子のプライベートを保った部屋がある一時保護所も必要かなと思いますが、その点いかがか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"性的虐待を受けた子どもが安心して１人で寝られる場所、誰もいないでちゃんと１人でベッドで寝られる環境をつくることも必要だと思っています。男児・女児問わず、基本個室、場合によっては２人部屋もあろうかなというところで考えておりますが、委員ご指摘のとおりです。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"あるいは４カ月、１歳６カ月健診未受診のお子さん、そこと連携すれば所在も安否確認もできる。平成２９年度では、かなりの成果を上げていると承知をしておりますが、その辺をご紹介ほしいと求めましたが、いかがか尋ねました。","respondent":"高山子ども育成課長","answer":"住居も含めた総合的な住民記録を照会する中で、こういったものを確認するべく、年間を通じて確認作業を続けているところです。そのようなことができるのが区で児童相談所を設置する最大のメリットだと思いますので、このことを受けとめてまいりたいと感じています。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"どうかこれからもその辺の連携もしていただきながら、児童相談所の役割もぜひお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/237826?Template=document&Id=6058#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":25419,"voices":52}},{"id":"h30-20180920-18","meetingId":"h30-cm09","date":"2018年9月20日","dateIso":"2018-09-20","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時４０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"の１、特定事件調査","agenda":"の１、特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"提案も、質問も含め、させていただいてきました。ここについてどういうふうにすればいいか、まずどういうふうにお考えになっているか、説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"「それはどこでもらったの」とか、その方がまた宣伝のもとになってくださるような広がりが見える活動をしていきたいと考えています。２０２０年に向けて何ができるか、何か一緒にできることがあるのではないかということで、いろいろ策を練っているところだと聞いております。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"その上で、少し細かいことを伺います。どういうふうに盛り上げて、これを区民にどういうふうに周知していくのか、改めて具体的に伺います。","respondent":"立川文化観光課長","answer":"ＵＮＩＴＥ ＨＥＡＲＴ ＦＥＳＴＩＶＡＬにつきましては、文化観光課が取りまとめておりますので、私からご説明いたします。各種イベントへの回遊性を促すことで、日常触れる機会のないさまざまなジャンルの体験を通して、文化芸術の振興を図るものです。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"改めて伺います。区民の方にどういうふうに、２０２０年のオリンピック・パラリンピックとつながるのかということを伝えるのかという手段をお伺いいたしました。","respondent":"立川文化観光課長","answer":"このイベントの中身の説明を少ししますと、例えば「ギネス世界記録町おこしニッポン『巨大手形アート』」と題しましてイベントを実施するものですが。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"たしかこのギネス記録に挑戦というのは、職員の発案で、私も非常にいいアイデアだなと思います。文化プログラムへの理解について、ぜひもっと進めていただきたいと思うのですが、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私ども東京２０２０大会に向けて、やはり委員ご指摘のように、スポーツのほうが前面に立ってしまうことが多いこともあります。文化からも盛り上げていくのだということを、目でもわかるような形で表示したり、伝えていけるような仕掛けをしていきたいと考えています。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"提案","question":"実は私もたくさん質問を用意してきたのですけれど、後ほどの視察にかかわってくると思うので、あと２つぐらい質問させてほしいと求めました。たしか以前にも提案させていただいたことがあるのですが、そういったことについてどのようにお考えになるか、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"アール・ブリュット以外にも、障害者の方の芸術的な作品というのはたくさんあります。それをまた東京２０２０大会にどう結びつけるか、集客とダイバーシティが広がるような取り組みに、どんどんしていきたいと思います。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"ここから随分、２カ月、時間がたっています。今、どのぐらいの糾合ができて、どういう発信をこれからされていくのか、最後にそれだけお伺いしたいと思います。","respondent":"立川文化観光課長","answer":"現在、分科会を立ち上げる最終段階に入っておりまして、近々幾つかのグループが始動する形になります。いわゆる機運醸成に係るイベントを実施するかという具体的な中身を協議していただくという、そのスタートラインに立つ直前です。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"あえて数は伺いませんけれども、区内を代表するような芸術家団体、非常に名前が通っているような方たちがやはり表に出られていました。一つの大きなチャンスだと思いますので、網羅していただきたいということで、最後に意見を述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"でもそれは必ずやってほしいと思っていますし、ずっと継続して行えるよう、そういうことをしてほしいと求めました。３２件あるということですが、新たな文化の発掘ができたと思うような、実例があれば教えていただきたいです。","respondent":"辻オリンピック・パラリンピック準備課長、いながわ委員長、安藤文化スポーツ振興部長","answer":"それ以外には、今までもございました「品川薪能」ですとか、「もけいで学ぼう！けんちくのしくみ２０１８」というものですとか… そういった具体的なことを聞いていると思いますので、何かそれで事例があったらということで、お答えいただければと思うのですが。区民の皆さんに、ある意味では今まで知らなかったものを知らしめていくというようなことも、非常に大切なことだと思っています。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"継続しているところはずっと継続していくのですから、継続できるものとして考えますよとか、そういうお話がないような気がしてならなくて。その辺のお考えはどうか、お聞きしたいです。","respondent":"安藤文化スポーツ振興部長","answer":"そこでコラボの事業ができるなら、それを継続してやっていく。２０２０年以降も継続してそれが発展していけるような工夫を、今考えていたところですので、続けて行きたいというふうに思っています。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"別にどうということはないわけですから。これは文化プログラムですけれども、それを観光に結びつけていくとか、そういう方向性というのは何かお考えなのか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"４年目になりますけれども、私どもの部が今、文化スポーツ振興部ということで、観光行政を取り込んです。今後、当然のことながら観光行政、スポーツもそうですけれども一体となって、情報発信をしていきたいと思っています。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"アール・ブリュットという言葉を使わないでほしいというお話がありましたけれど、いわゆる生のままの芸術ということで定義をされました。それ以外の専門的な教育を受けていない方の芸術作品、そういったものを展示したらどうですかと、そういう意味でありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"例えば先ほどのしながわ文化プログラムのバッジも、「これ何ですか」と聞いた人に、説明をして、さらにそういう人たちに広げていってもらう。よくわからないけれども、その辺の考え方について、説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"皆さん、広めてくださいねと説明するとともに、バッジを差し上げていたというような状態です。それによって、文化プログラムに参加している団体の構成員の方が、また次の人につないでいくということは、できるかと思います。","id":"exchange-012"},{"speaker":"大倉委員","kind":"意見","question":"今、例えばイベントも含めた、よりいろいろな人たちに見てもらおうという形をとったというようなお話も聞いています。違うことをしに来た人たちに知ってもらわないと、広がっていかないのかなというところがあったので、そのことについての考え方を説明するよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"いわゆるイベントを回遊するといいますか、はしごをするようなイメージだと思うのです。相互に宣伝をし合い、相乗効果を出すということについて、今後も研究してやっていきたいと思います。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"地域プライドみたいなものを持ってもらうというところまで、見て、やってほしいと求めました。これは意見で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"東京２０２０大会に向けて、さらにはその一体感をつくっていこうというのが、このしながわ文化プログラムとして取り組んでいる意味だと思うのです。このしながわ文化プログラムが３８万、３９万区民お一人おひとりの中に、まずそこを教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"オール品川で取り組むという一体感や、今のところ認知度としてはやはり、全体から見ると多いとは言えないかなというふうに認識しております。オール品川で２０２０年に向かっていくということに関しましては、このあたり説明にもあるのですけれども、参画していただく。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"ですからブランディングではないですが、この辺の連携というのは庁内でどうとりながら、このあたりがすごく気になるところであります。そこの力を底上げしていただくとかというようなことが必要だと思うのですけれど、この辺はいかがか尋ねました。","respondent":"中山企画部長","answer":"全体の盛り上げについてのスタンスということもありますので、私のほうからお答えします。そういうことも位置づけの中でやっていくのだということを明確にし、所管とも連携しながら、行っていきたいと考えております。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"区民の方が、区外の方とか国内外にかかわらず伝えていただく担い手になるわけですから、主体者を一人でも増やしていかないといけないと思います。さまざまな課題がある中で一生懸命取り組んでほしいと求めましたし、何か一つやっていただけたらと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"前回のときにもしながわ文化プログラムのデザイン料を伺ったかもしれないのですけれども、このバッジの量、金額、あとその予算はどこから来ているのかというのを教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらはただいま見積もりをとっているところで、まだ作成ができておりません。それほど高いものにはならないかと考えています。","id":"exchange-018"}]},{"id":"topic-02","title":"ボランティアの募集","agenda":"ボランティアの募集","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのが、応募資格のところで１８歳以上の方ということですが、そういった方たちも参加できないのでしょうか。というようなこともできるのかなということを考えると、日頃からボランティアをやっていないといけない理由というのを教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"イベント等にボランティアとして参加していただいたり、道案内ということですので、なかなか小中学生ですと難しいかなです。地元の方が案内したほうが、よりよい案内ができるということで、そのような方に応募してほしいということで書いてあるものだと思います。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"小学生とか子どもたちがぜひ参加できるようなボランティアや、体験ができるような取り組みを考えてほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"お伺いするに当たってどこまでお答えいただけるかと思うのですが、例えば観客案内、都市ボランティアの方と一緒に行動することも想定されているのか。１５０人が上限とございましたけれども、考えられるのかどうかということについて、お伺いしたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"例えば暑いから何か水を渡すようなことを区で考えてみようとか、よりプラスの形、おもてなしの気持ちでやるということは考えております。都市ボランティアに関しましては今年の１２月５日までが応募期限ですが、ぜひ応募していただきたいと考えています。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。募集人数が一応５００人ということで、どういうふうに考えているのかというところを、最後にお聞かせほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"内容につきましても、イベントが好きな方も、嫌いな方もいらっしゃいますので、イベント以外もあればとは考えております。例えば文化プログラム的なものの案内とか、そういったことも想定としてはあります。","id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。ぜひやってよかったと思えるように、さまざまな形での活躍の場を提供していただけるよう、お願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問","question":"区独自ボランティアについて伺いたいのですけれども、区独自ボランティアというのは全ての区で設置するものなのでしょうか。今行っている区が幾つあるのかということを伺いたいのと、この観光案内というのは、そういう講習だったり講座等も行われるということなのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やろうと思っている区がやるということで、私の知っているところでは今のところ渋谷区が、独自ボランティアを予定しています。先ほど申し上げましたとおり、どういうふうに打ち出していいかわからないという区が多いのではないかと認識しております。","id":"exchange-024"},{"speaker":"田中委員","kind":"意見","question":"区独自ボランティアの設置は、特にやりたいと言った区がやっていくという感じで、必須ではないということでした。どういう内容のボランティアをしていくのかとか、９月２６日から募集を開始するということですけれども、ちょっと思いましたとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"なので、その中で身につけるのかなというふうには思っております。私どものほうも、観光と書いてはありますが、難しいところもありますので、そこは今後、検討するところです。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"区独自ボランティアのところで、健康に自信がある方というのがあるのですけれど、これをわざわざ書いた意味、ここに明記した意味を説明するよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今年の猛暑を考えますと、やはり健康に自信のない方に従事していただいて、具合が悪くなったら本末転倒ですので、そこは健康に自信がある方というふうに明記させていただいたところです。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"既に想定して２０２１年３月までとなっているのか、それとも行政的に年度で行うからそのくくりなのか、その辺を教えてください。区の場合は、レベルの差はあると思うのですけれど、それに準ずるようなものを用意する考えがあるのかどうか、説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"報告会等も考えられますし、可能性としてはありますので、一応２０２１年３月までとさせていただきました。区独自ボランティアのほうも、何の物品にするかは検討中ですが、同じように一体感の出るようなものを支給するつもりでおります。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう工夫を、どうせ打つのだったらそういうところもきちっと、事前に想定をして募集するということをぜひ検討ほしいと求めました。それと大会ボランティアと都市ボランティアのほうは、来年２月から５月が面接とか研修という段取りになっていると思うのですが、最後にお伺いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その方が従事する前に簡単な研修、ボランティアの心構えとか、そういったものはアナウンスするつもりではいます。従事する内容によっては、研修の内容とか長さといったものが変わると思いますが、もう少し手軽にできるようにというふうに考えております。","id":"exchange-028"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"それだけではなく、こちらからも呼びかける動きというか、そういうものがあったらいいなと思います。障害のある方たち一人ひとりに情報が届くような周知をしてほしいのですけれども、何かありますか尋ねました。","respondent":"池田スポーツ推進課長","answer":"今、当然スポーツ協会もしくは私どものほうからも、障害者団体にいろいろとご参加の呼びかけをしているところではあります。ホームページや広報紙等でもご案内しているところですけれども、さらに周知については研究するよう、努力いたします。","id":"exchange-029"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"最初に申請した時点で、今、課長がおっしゃった大井ふ頭中央海浜公園という正式名称で申請しているので、それを変えることはできないと、そういう意味で、一番最初に戻った、そういう回答だったと理解していますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"意見","question":"私が聞きそびれたのかどうかわからないのですが、１番のところで、我々は常々、ホッケー会場の多目的利用の話をしてきたと思っています。今、委員長がおっしゃった中に、多目的利用についてはなかったような気がするのですがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"確認","question":"大分違うと思っているので、どうなのかなと。この委員会では、多目的利用という確認は何度もさせていただいていると思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"私どもも党全体でそういう要望を出しているということもあるので、そういう意見も出るような場面に設定していただきたいと思っているのです。その辺の判断はどういうふうにされたのか、一つ伺いたいのと、いかがなものか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"南委員","kind":"提案","question":"ですから、私たちはそういうことをもっと考えていくべきだという提案もし、せっかく行くのですから伺いたいと思うのです。ですから、ぜひそこは範囲を広げていただいて、発言は許していただきたいと考えていますけど、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"確認","question":"皆さんの前で多目的利用をするというのも確認しながら、行政側もどうだという意見をまとめて、出しているつもりです。私は現実的でないと思うし、それならどういうことで暑さ対策ができるかという議論をしたほうが、よほどいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"遠い将来に先送りするわけではありません、９月か前回やった１０月が適切ではないかという意見は、一般的にはたくさんありますよね。ですからそういう点で、そういう声も届けるということを重要に捉えていくべきだと、そういうふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問・要望","question":"要望事項等に含まれているものが一つの下敷きになるかもしれませんけれども、そういうものに沿ってなされるのが妥当だろうと考えています。それはある意味、ここの委員会でそれをあえて取り上げてということに関していえば、それは少し違うのではないかと私も思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"南委員","kind":"意見","question":"もちろんこの委員会でそういうふうに言うのはまかりならぬと、そういうふうに皆さんが意見を出されて却下されれば、それは従おうと考えていますので、ぜひ全会派の、一人ひとりのご発言をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"ミストの設置というお話を委員長がされていたので、そこの部分だけを要望するとかではなく、というところを言いたかったのです。対策についてどのように考えているのかということと、ミストに限らず、命を守る対策をきちんと進めてほしいということについて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/125111?Template=document&Id=6544#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":34205,"voices":103}},{"id":"h30-20180921-10","meetingId":"h30-cm09","date":"2018年9月21日","dateIso":"2018-09-21","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5300#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":3521,"voices":22}},{"id":"h30-20181015-10","meetingId":"h30-cm10","date":"2018年10月15日","dateIso":"2018-10-15","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"たします。 なお、議席の変更届については、先ほどの説明にもありましたが、議運終了後お配りしますので、１０月１７日までに提出いただきますようお願いをいたします。…","agenda":"たします。 なお、議席の変更届については、先ほどの説明にもありましたが、議運終了後お配りしますので、１０月１７日までに提出いただきますようお願いをいたします。…","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"局長に確認させていただきたいのですが、改めて現在、委員会としてあいている空席がどこに幾つあるのかということを教えてほしいと求めました。それから、補欠選挙で当選した２人が、その空席の中から選ぶことができるというルールでいいのかということについても説明を求めました。","respondent":"久保田区議会事務局長","answer":"区民委員会が７名、厚生委員会が７名、建設委員会が西本議員が失職したことによりまして７名となっているものです。それと、最終的な常任委員会の割り振りにつきましては、この議会運営委員会の中でお話をしていただいてご決定いただければと思ってあります。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"基本的なルールとしては、そのあいた３つの中から選ぶことができるというルールでいいのか確認だけお願いしたいと思います。","respondent":"久保田区議会事務局長","answer":"今、欠員になっている中から選んでいただくですので、議運の中でお話し合いをした上で決めていただければと思います。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"委員長の提案ということは、厚生１ということでの提案なんですけれども、新議員ということになったわけです。公約を実現するというところからも、ぜひとも共産党としては、おくの晋治を建設委員会に所属させていただきたいということで希望したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"意見","question":"本来、区民、厚生が、都議選で失職された２名のあいている分であり、今回の補欠選挙というのは、その２名分の補充の選挙であるという意味でいけば、そのまま区民、厚生という枠でいいのかなというふうに思っていますので、委員長案に賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"あるのですか。〔「さっきと同じこと聞いているじゃない」と呼ぶ者あり〕 補選前に……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"いや、そういうふうにされては困りますので、改めて発言をしているわけです。改選前のものにしなければならないという理由はあるのかどうか、局長に確認したいと求めました。","respondent":"久保田区議会事務局長","answer":"改選前にしなければならないルールというものは特に規定はございませんけれども、議運の中でお話し合いをしていただいて、割り振りを決めていただくというのがルールだと思います。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それで、現在３つのポストがあいているわけです。その中で、希望しているわけですから、その希望のところに入れないというのは、委員長としての考え方はどういうことで提案をされたのか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"３つのあいた中から選ぶといったことはできるというのがルールと言えばルールなわけですよ。なぜ、その希望が受け入れられないのかというふうなことを説明するよう求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこの中で、この委員会を希望しているわけですから、そこの希望が認められない理由というのが……。〔「認められない理由はないですよね」と呼ぶ者あり〕 認められない理由というのが何かあれば説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"誰もかれもなれるわけない」と呼ぶ者あり〕 ですから、特別なものがあるのであれば別ですけれども、特に何もないわけじゃないですか。あくまで委員長の案ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"来年４月に選挙があったときに４０人が選出されて、それでは我々の会派が１０人であれば２人ずつ５常任で、会派の中で選出してください。私はどうしてもこれがいいといって会派の中でご理解をいただけるならば、ずっと４年間文教委員会やる方がいる、何をする方がいるとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だけれども、かぶらないのであれば、なぜ本人の希望を認めないのですか。しかも、そのルールを委員長として認めないで、それを押しつけるというやり方は横暴ではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"だから、これは希望を通すというふうなことで、ルールにのっとってやるべきだということで言っているわけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"提案","question":"この候補が述べたから、この委員会に入るというルールはありませんので、それはあまり押しつけないでほしいと求めました。それで、私どもの会派の意見としては、委員長がご提案をされたこの案に賛成だということは、ここではっきりともう一度申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"提案","question":"どうでしょうか。どうでしょうかというところなので、問題がなければというか、ぜひご理解をいただきたいと思っての提案なのですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"石田（し）委員","kind":"意見","question":"ないとかというお話を言っていますが、権利があるとかないとかというのは、我々も希望した委員会になれないときもあるわけですよ。今回は補充の２名というのは区民委員会と厚生委員会に所属をされていた方たちの２名なので、ぜひそこはご理解をいただければというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"だから、建設委員会を選ぶことに不都合があるのかどうかというところをぜひ聞かせていただきたい。なければ、希望というか、そこがあいているので選ばせていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問","question":"不都合どうのこうのというのは、では逆に、区民委員会と厚生委員会を埋めることに対して何か不都合があるのですか。別に建設委員会がどうしても８人にならなくてはいけないとか、委員長案の２名の補充に対して逆に不都合があるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問","question":"そういう質問に対してはどう答えていいのかわかりませんが、３つの委員会というのは同じだと思います。そういった面で、特に建設委員会を選びたいということに対して、先ほどから聞いていますけれども、何か不都合があるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"提案","question":"不都合がどうとか、今委員長が提案しているのは、委員長案があるので我々はそれでいいでしょうということを意見として言っていること。その欠員が生じた中の補充をするという話をしているわけで、それはその構成でいいのではないですかということを話しているだけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新たに１名増えた議席ですので、そこのところでもし不都合がないのであれば３つの中から選ぶということで、選ばせていただきたい。それを多数決という形ではなくて３つの中から選ぶ、かぶった場合は調整をするという形で議運の中でも決めていくべきだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"質問なのですけれども、資料No.６、議会改革各会議メンバーの資料が出ていますけれども、こちら１０月１日現在になっています。資料No.６のほうは補選が終わった後の資料を出されていて、ここら辺の矛盾というのはどういうふうに考えればいいのか説明を求めました。","respondent":"久保田区議会事務局長","answer":"議会改革検討組織のメンバーにつきましては、私どものほうとしましては、最新のものとしてこれをお示しさせていただいたというものです。もともと議会改革のメンバーは、西本前議員は議会報告会等準備会議に入っていたというものですので、念のためお知らせをしたいと思います。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"ですから、２人が補充されたとしても、１つの委員会は必ずあきが出てしまうわけです。ですから、そこでやはり希望を考慮に入れても何も問題ないと思いますので、ぜひ……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"自分の意見と違う意見が出ているからといって、議会が硬直化しているとか、恣意的だとか、そういう発言というのはぜひ控えてほしいと求めました。自分の意見が１００％正しいというわけではなくて、ぜひ発言を控えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"本多委員","kind":"質問","question":"共産党の要求をどうすればかなえられるかとずっと今考えていたのですが、それは会派内で話し合いができるではないですか。そんなに希望、希望というのであれば、会派内で建設委員会１議席をメンバーチェンジするとかでいいのではないかというアドバイスをして終わります。","respondent":"久保田区議会事務局長","answer":"先ほど議会改革検討組織のほうで、私１点答弁が漏れたのですけれども、都議選に出る方はもともとこのメンバーの中には入っておりません。","id":"exchange-025"}]},{"id":"topic-02","title":"そのように決定をいたします。 自民党・子ども未来におかれましては、議運終了後、附属機関等議会選出委員届を事務局までご提出ください。 次に、(5)議会改革検討組織","agenda":"そのように決定をいたします。 自民党・子ども未来におかれましては、議運終了後、附属機関等議会選出委員届を事務局までご提出ください。 次に、(5)議会改革検討組織","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"なので、その２名がご希望を出されて、まずは委員長に一任をしたいと、我々としては。〔「共産党もいらっしゃるから正副で話してもらえればそれが一番いいのではないですか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"品川区長期基本計画策定委員会委員の推薦","agenda":"品川区長期基本計画策定委員会委員の推薦","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"そのためにも、議会選出の委員もそういう構成ですべきであると思いますし、できるだけ多くの会派を入れてほしい、入れるべきだと。具体的には、無所属品川と生活者ネットワークも委員に入れるという提案を議会に通して提案すべきではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりすべての会派を入れていただきたいと思いまして、多様な会派構成にしてこそ、よりよい長期基本計画の策定になると思いますけれども。ぜひ、入れないという理由があれば……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"あるならば、副委員長がいらっしゃるのであれば、正副の中で諮り方も変える。それは正副案として、それは今までのやり方を根本から変えるような発言を毎回されるのであれば、それは注意してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"決して多数決ではなく話し合いによって結論を導いていくというやり方はこれまでどおり踏襲してほしいと求めましたけれども、従来どおりでオーケーというのではなく、やはりそれと違った意見が出たときには議論をしてほしいと求めましたけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問","question":"逆に伺いますけれども、これは区民の代表である私どもの議席の数に応じて配分をするということだと思うのですけれども、逆に不都合があるのですか。〔「普通のことですよね」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"安藤委員","kind":"意見","question":"多様な代表で、いろいろな会派の方が区民の付託を受けて選出されているので、なるべくいろいろな会派が入ったほうがいいのではないか。比例で議席を案分するということ自体が全く民主的ではないとか、そういうことを言っているわけではないですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"確認","question":"安藤委員からも確認できたので、そういうことではなく、民主的にのっとった形で一番わかりやすい形だからこれに賛成しますと申し上げただけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"石田（し）委員","kind":"意見","question":"区民の声がどう届く、これはあくまで策定委員会ですので、議員はそれぞれ本会議や各委員会等でこのことについても発言をする機会は十分あるわけです。先ほど賛成ということで意見を述べさせていただきましたとの意見を述べました。","respondent":"久保田区議会事務局長","answer":"公明党が１名、共産党が１名、国民民主党・無所属クラブが１名となるというものです。今回の選出方法についてご確認いただきまして、各会派で１０月３０日までに氏名報告を事務局までお願いいたします。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5302#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":19108,"voices":108}},{"id":"h30-20181024-10","meetingId":"h30-cm10","date":"2018年10月24日","dateIso":"2018-10-24","committee":"議会運営委員会","time":"午前１０時３０分～午後 ０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"の順番を入れ替えまして、予定表の３、平成３０年第３回定例会についての(1)理事者から発言を求められている件","agenda":"の順番を入れ替えまして、予定表の３、平成３０年第３回定例会についての(1)理事者から発言を求められている件","exchanges":[{"speaker":"本多委員","kind":"提案","question":"発言を求めます。本会議が明日から開かれますが、議会の正常化に関する決議を提案したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"現在、提出者は２０名で、表題は議会の正常化に関する決議であります。文面をお読みいただきましてご確認をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"飯沼副委員長","kind":"質問","question":"今、お読みになってということなので、ちょっと読み切れていないのですが、この取扱いについて、どのように取り扱われるのか、ちょっと説明を求めました。","respondent":"久保田区議会事務局長","answer":"この議案が出されましたので、これにつきましては本会議のほうで追加議事日程という扱いになるかと思います。議事日程の整理をしなければならないのですけれども、追加議事日程として入れていいかどうかというのをこの後確認をしていくという流れになります。","id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問","question":"ということは、ここで別に議論することではなく、本会議場で議論をするということか尋ねました。","respondent":"久保田区議会事務局長","answer":"最終的な採決については、これまでの例にならいますと無記名投票によって採決を本会議で行うといったことになってありますので、実質的な議論はここの議会運営委員会の中でいろいろと行っていただければと思います。","id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問","question":"副委員長の立場でお聞きしますが、委員長はいつこれをお知りになったのか。今日突然なのかどうか、委員長は事前に把握をされていたのかどうか、お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ぜひこういうことについては、事前に伝えてほしい。ここでちょっと話して終わる問題ではないですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今、今出された本多委員のほうから提案があったということなので、もう少しこの趣旨についてご説明いただきたいと思うのですけれども。これを出された趣旨の説明を、書かれているとおりですというだけではなくて、もう少しご説明ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"本多委員","kind":"意見","question":"明日から始まる第３回定例会に向けて、いろいろと議会では議会の意思決定があったわけですね。このような、あとは文面の内容のとおり、こういった文面で決議を出したいという考えですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"現議長のもとで今までどおりのというか、正常の議会運営のため自分たちは行動していきますよということを、改めて決議で出すということでいいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"出席するということを決議で上げる……。前ももう既に出席もされていますし、そこをあえてこの決議という形で出された意味というのは何なのかということもちょっと説明を求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"本多委員","kind":"意見","question":"思いはそういう思いです。はその決議を上げた上で、議会活動を進めていきましょうという趣旨ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問","question":"よろしいですかって、では取扱いはどうなるのでしょうか。ここで議論ということにこれ以上ならなくて、それを取り上げていくかどうかは、これは出されたのだから取り扱うということでいいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これに対してどう考えたらいいのかというところの検討をする時間というのを、委員長のほうから言われたように、休憩をとってほしいと求めました。議事日程の運び方というか、もっと各会派が検討できるような時間の配慮もぜひしていただきたいと、ちょっと意見として申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"意見","question":"やはり議会運営委員会に与えられた使命だと思うのですが、このような出し方は甚だ遺憾に感じています。それだけはちょっと言っておきたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"本会議場で動議です。しっかりちゃんと議会運営委員会に提出をして議事日程に入れていこうという意思を我々はそこで表明をしているということで、ご理解いただければとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"石田（し）委員","kind":"確認","question":"局長に確認をしますが、先ほどから提出方法についていろいろとおっしゃっている方たちがいますが、これは正式なルールにのっとって提出をされているのかどうか、確認したいと求めました。","respondent":"久保田区議会事務局長","answer":"議会運営委員会に提出するということになってありますので、その意味では、そういったルールにのっとった形でこちらは出されているというものです。議会運営委員会には提出されておりますので、今日の議題というか、本多委員のほうから提案があったというものです。","id":"exchange-016"},{"speaker":"石田（し）委員","kind":"確認","question":"正式なルールにのっとっているというのを確認をしまして、それに無理がない、普通にルールにのっとった提出方法をされているので、そのことに関してああでもない、こうでもないと言われても、ルールにのっとってしっかりと提出をされているので、そこはぜひご理解ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことで出すルールがあるわけですから、やはりこの件に関しては、この間もう何度も何度も議論をこの場で重ねてきたわけなのです。これだけ議論がされてきた問題ですから、配慮すべきものではないかということで、意見を申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問","question":"鈴木ひろ子委員から、もうこの件に関しては議論をたくさんしてきたと言っているのであれば、もう議論はされているのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問","question":"いやいや、だって自分で今言ったではないですか。今、ここでまた何かを今後議論するというのは必要なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、今までそれを回避するためにここでやってきたわけでしょう。それを今までずっとやってきたということですので、正確な表現に気をつけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点については、「本会議の定刻に出席しないで１日議論ができなかった」という表現に改めさせてほしいと求めました。新たな決議ということで、決議という形で出たわけですから、そして意見を述べたいということで申し上げております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"そこはもう正副に我々は信頼をしてお任せしているわけですから、それをこの場で、ほかの方が言うのはいいですよ。ですから、あまりここでそういうことを言わないほうがいいのではないかなということは申し添えておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"意見","question":"把握してどう受けとめられるのかというのを含めて、私たちは発言をし、行動をしなくてはいけないと思っているのです。そういった意味では、副委員長であろうと私が発言しても許されると思うので、今日は発言させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"繰り返しになりますけれども、先ほどそのことは同じことを伺いました。そのことを何度も何度もおっしゃって、それで何か物事が進むのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"元々共産党の区議団としては、見解を発表しておりますけれども、この指摘は全く当たらないというところを一つしっかりと述べたいと思います。辞職や辞任を求める決議、この３本の決議そもそもが、議長職を辞めなければならない理由には相当しないということで私たちは主張してきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-02","title":"議会運営上の変更","agenda":"議会運営上の変更","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。ちょっと教えていただきたいのが１つと、１名はやはりＩＣＴ推進会議として選んであげたほうがいいと思うのですけれども、そういった意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"意見","question":"私個人はどうこういう立場ではありませんけれども、ＩＣＴ推進会議としては８名以内で進めするわけでありますので、ご報告をします。お２人のところでおっしゃいましたけれども、そちらに入っていただくことがよろしいと思って、そういう判断をさせていただきましたとの意見を述べました。","respondent":"久保田区議会事務局長","answer":"定員の話ですけれども、今、伊藤委員のほうからもありましたように、前身の会議体の状況等を踏まえ、平成２９年５月１９日の議会運営委員会の中で定員を決めていただきまして、それぞれ申し合わせ確認事項の中に記載をされているというものです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"定員のことはわかりました。皆様そうですけれども、議員としての思いを持って議会に入ってきたわけですから、どちらか１人は入れてあげたほうがいいのではないかという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"意見","question":"お２人入っても定数にはいかないわけでありますので、１人ずつでも構いませんが、そういう方向で進めてほしいと求めました。","respondent":"渡部委員長","answer":"その前にはＩＣＴ推進会議のリーダーの伊藤昌宏委員からもそのような話がございました。結局、私自身もこの２つに割り振りしていただくのがいいのではないかと考えておりますが、他会派の方々のご意見を聞かせていただけますか。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"提案","question":"これはフラットに伺いまして、私も今このご提案を初めて聞いたのですけれども、確かに欠員が多いですよね。というところで、たしか前回の会議の中でも、最後全体の意思で決めていくという仕切りだったと思うので、それが一番いいのではないのかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"石田（し）委員","kind":"質問","question":"定員１４名のうち１０名、１４名のうち１１名ですから、広報と議会報告会等準備会議にそれぞれ１人ずつ入っていただければ特段問題はないかなと。そこは入られるお２人でお話をされるのか、そちらのほうへ行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-03","title":"決算特別委員会","agenda":"決算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"資料No.１５なのですけれども、態度表明したものをもう少し編集しなくてはいけないので、ちょっと大変なのです。もし可能であれば、翌日とかそういったことにできないのか、そうしていただければ助かると思ったのですがとの意見を述べました。","respondent":"久保田区議会事務局長","answer":"すみません。１１月１６日が金曜日ですので、月曜日になってしまうと作業上厳しいところがありますので、できましたら１６日金曜日にお願いをしたいと思います。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5304#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":20488,"voices":118}},{"id":"h30-20181026-4","meetingId":"h30-c-settlement","date":"2018年10月26日","dateIso":"2018-10-26","committee":"決算特別委員会","time":"午後 ２時１６分～午後 ２時２３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/295139?Template=document&Id=1450#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":1887,"voices":17}},{"id":"h30-20181029-6","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"区民委員会","time":"午前１０時００分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"平成２９年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２９年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この改善を求めたいわけですけれども、事業報告書を一緒に添付してほしいと求めましたが、いかがでしょうか。経営会議に出されるときに、この資料１枚で経営会議でも議論が行われているのかを伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"少し口頭で説明が必要なものについてはフォローするようなところで、４,１９８時間という、これが分母になるところです。これは大体４割ぐらいをまず目標にしようということでございましたけれども、その半分の７６９時間というのが、今回平成２９年度の実績です。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"わかりやすくなると思うので、ぜひそうしてほしいと求めましたけれども、いかがでしょうか。ここでもぜひ、事業報告書などの資料をさらに充実させてほしいと求めましたが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"委員会におきましても、指定管理の施設の適正な運営、あるいは改善が必要な事項といったものを議論していただく場ですので、そうした資料の最適な部分といいますか、そこは十分、本日の報告以外の部分にも係る話だですので、いろいろ研究してまいりたいです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"事業報告書全てがホームページにアップされているということでよろしいのかというところは確認させてほしいと求めました。区の認識を伺いたいのですけれども、目的が達成されていると考えているのか、各施設について伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"なかなか一口で説明するのも難しいところではありますが、本施設が開設して、十分寄与しているかなと。現時点でなかなかリンクはしていないですけれども、狭い意味では十分貢献しているということは、今言えるかなと思っています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"あわせて、先ほどご説明もありましたが、インキュベーションマネジャーの配置が１月にずれ込んだ理由も伺います。要望意見箱とか、どういったところが評価されて、どういったところが指摘されたのかというところをご紹介ほしいと求めました。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"１０％と申しますが、低いということを、かなり精緻なアンケートを実施しました。指定管理者のほうで、なかなかそれに見合う人材ですとか手法が整わず… 基本的に、窓口対応については大変重要ですので、その辺の満足度を常に聞いているところです。事業も実施しておりますので… 要望意見箱というものを用意していますので、特段アンケートを実施するということは、現在のところは考えはございません。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。ホールの稼働率も約９４％ということで、またとりにくくなるのかなという思いもありまして、このところの区の認識を伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"３階につきましては、あの手のホールで稼働率が９０％を超えるというのは、非常に驚異的な数字です。それから持っているポテンシャルといったものも加味されて、今、非常にホールは満足度が高い状況だです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろなことがあると思いますが、いわゆるアンケートとかも行っていらっしゃいますので、ぜひ、全て４つの施設の利用者の意見をしっかりと聞いて、利用しやすいようにしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"品川区立品川産業支援交流施設は、（ＳＨＩＰ）とかというのを書いていないのは、何か意味があるのですか。区民満足度についてのお話があったのですけれども、そもそも区民満足の視点をどのように調査されたのか、それぞれお知らせいただけますか。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"接遇する職員の説明事務の正確さですとか、施設の相談体制ですとか、幾つかの項目に分けてアンケートはとっております。… それから、満足度の関係です。こちらは両施設ともアンケートを実施しておりまして、その辺を分析した結果です。 ただ、ご意見・要望を聞いて、区民の方に満足していただけるような事業を行っているということです。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"要望意見箱等を活用しながらということだったのですけれども、そして反映しているのかというのを聞かせてほしいと求めました。区ではどういう形で財務に関してモニタリングを行っているのかということを伺いたいのと、報告書にないのはなぜなのかということを説明するよう求めました。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"会員が大体、先ほど個人・法人１５０程度ですけれども、有効回答が１０９ということでいただいております。それから、日ごろ… １つが、事業者として運営される方に対して、利用受付のときにアンケートをお渡ししまして、事業が全て終了したときに、それを回収しているものです。… 一斉のアンケートは特に実施はしてございませんが、利用者からの意見を指導者からも頂戴してということで、利用者の意見を反映しています。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"労務についてもそれぞれどうなのでしょうか。伺わせていただきたいのですけれども。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"それを、財団法人に属する専門の税理士などを含めた監事役が当然いますので、そうした形のチェックということでされているということで考えております。 事業団の労務の関係については、社会保険労務士等を活用して適正にやっていると報告をいただいているところです。 実際に労務関係についての変更等がありますと、全ての職員がきちんと福利厚生等を含めて業務ができるような形をとっているところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれやられているというのは、よかったです。今後は労務のモニタリングの報告も、ぜひ資料としていただきたいと思うのですが、いかがか尋ねました。","respondent":"堀越地域振興部長","answer":"全体的に企画部門で検討して、検討している途上ですので、幾つかの施設で試行的に行っているという部分もあります。そういったところも含めて今、企画部門で検討していると私どもは伺っておりますので、今後考えていきたいと思っているところです。","id":"exchange-010"},{"speaker":"田中委員","kind":"意見","question":"指定管理なので、がちがちなのはよくないとも思っています。もっと自由にあるべきとは思っているのですけれども、ぜひ報告がされるように、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"何がいいのですかと言ったら、広報だとか、チラシ１つとってみても、企画がおもしろいと。別にそんなに私はこだわるものではないという思いがあったので、その辺の定義というか、利用料収入についての考え方を説明するよう求めました。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"４階の事務室も１６室満室になっておりまして、ここもそうした民間の事業所に比較して、極端に安価で安いということではありません。あるいは… こちらは、これまで３０年以上にわたりまして運営してまいりました。完売御礼が多いですが、情報発信につきましてはさまざま工夫して実施してきたというと… 日曜日については１００％近い利用率ということで、これ以上の利用料金というのは伸びがあまり見込めないところは事実です。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問","question":"それで、最後に伺いたいのは、２０２０年というものが、多分こういう全ての事業団にしろ施設にしろ、非常に大きなタイミングだと思います。どうしても場の提供というところに行き着くと思うのですが、活動の場の確保というのでしょうか、行政として。","respondent":"立川文化観光課長、池田スポーツ推進課長","answer":"来年、順調に行けば実施設計。これまでなかなか直せなかった、いじれなかった部分についても、あわせて実施したいと考えているところです。機会を捉えて、地域スポーツの施設を新たにつくっていただくということを調整しながら、働きかけをしていきたいと思っているところです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"それぞれなのですけれども、事業報告書をもとに、その後、調査に入ったりということはしているのかということを伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"品川区立品川産業支援交流施設をまずお伺いしますが、入りと出という意味において言うならば、利用料金というのが入りで大きい部分ではないですか。入りがこういうふうに出ているわけですから、この１枚にまとめたいというお気持ちはわかるのですけれども、私は出すべきだと考えています。","respondent":"山崎商業・ものづくり課長","answer":"それから、平成２９年度の本施設の運営につきましては、１億６,０００万円ということで、収支は黒字で８,８００万円です。平成２９年度につきましては、品川区に本施設運営の歳入として５,６００万円、区に戻っているという状況です。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"きゅりあんについてお伺いするのですけれども、今の理事長はどういう経歴の方がやっているのか教えていただきたいのと、理事長はじめ。行かれているなら、人数はどのぐらい行かれているのか尋ねました。","respondent":"立川文化観光課長、池田スポーツ推進課長、山崎商業・ものづくり課長","answer":"区の職員のＯＢですけれども、今、正確な数字を持っていないのですが、管理職のＯＢは３名と聞いております。それから、品川都市整備公社ですが… スポーツ協会です。スポーツ協会で区の元管理職としまして、１名行かれているです。 一般財団法人品川ビジネスクラブには１名です。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"これは絶対プラスにして、連携をとってやっていかないといけないと思うし、思う気持ちで質問させていただいているので、これはよくわかってください。ぜひ連携をとって、行政が区民のためになるように一生懸命働いてくれれば幸いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"浅野副委員長","kind":"質問","question":"こちらの承認取消しですとか使用停止についての基準というのでしょうか、どういうことをしたら、１つ教えてほしいと求めました。使われる方が窮屈なところでやられると、ちょっとかわいそうなところがあるかなというのがありますので、この点をまず説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"４階のラウンジでは、１００％混み合っているという状況にはありませんので、５０％でかなり見た目が相当混み合っているような状況。そのあたりが瞬間的なピークとすると、そのあたりかなと、数字としては捉えているです。","id":"exchange-018"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"もう１点、非構造部材ということもなかなか聞かなくなったということは、これは品川区としても定着がしたのかなと私は考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"今定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、区民委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"前々回か前々々回質問したときよりも進展があったということで、特に品川区という意味で注目される事件の一つですから、ちょっと説明を生活安全担当課長からしていただければ幸いです。","respondent":"菅生活安全担当課長","answer":"詳細についてはなかなかわからないところもありますけれども、報道等によりますと、１０人目の逮捕者が出たと聞いております。詳しいことは私のほうでも承知をしておりません。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2822#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":27824,"voices":78}},{"id":"h30-20181029-7","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"厚生委員会","time":"午前１０時００分～午後 ３時７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件整理しています。","topics":[{"id":"topic-01","title":"第７８号議案、品川区公衆浴場の設置場所の配置および衛生措置等の基準に関する条例の一部を改正する条例","agenda":"第７８号議案、品川区公衆浴場の設置場所の配置および衛生措置等の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが平成１５年２月１４日に国から通知が来た、この平成１５年に技術的助言があって、それを現在平成３０年に実施する理由も伺いたいなと思います。それと、２３区内で同じように条例改正または規則を改正しているところというのがわかれば教えてほしいと求めました。","respondent":"鈴木生活衛生課長","answer":"これは国の助言、それから環境に鑑みて都のほうでしばらくはこの現状の毎日１回の換水を維持したいというのが都の当時の考え方だと聞いております。それから、２３区の改正状況ですが、今年度から来年度にかけて各２３区においても改正が行われていくという状況です。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"もしもわかれば、もう結構進んでいるのかどうかというのを伺いたいなと思ったので、お願いしたいと思います。この１０％を下回っているということの評価というのか、それとあとどういう検査、そういうところもわかれば説明を求めました。","respondent":"鈴木生活衛生課長","answer":"インターネット等で調べたところ、数区で既に改正の手続をしたり、終わったりしているという状況だと認識しております。お湯を入れかえた時点で１回洗浄・消毒をして、感染症も発生していないというのが現状としての評価、認識です。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういうことを区あるいは保健所としてやったり周知といいますか、安全性を高めるためにそういったことはされているのかどうか伺いたいと思います。それで、週１回以上の換水で良いとされる要件、1)、2)、3)を満たす施設は区内にどれくらいあるのかを伺いたいと思います。","respondent":"鈴木生活衛生課長","answer":"区内で該当する施設は銭湯で３件、その他の公衆浴場等の施設で２件、合計５件が一応要件を満たす施設になります。実際に週１回の換水が認められるためには保健所に届け出が必要になりますので、週１回の換水を認めるという形になります。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"聞き逃していたらすみません、もう一度お願いしたいと思います。この公衆浴場の条例に該当する区内の施設の数との意見を述べました。","respondent":"鈴木生活衛生課長","answer":"区の衛生の基準等が適用される公衆浴場ということであれば、総数は平成２９年度末、今年の３月で６０件になります。そのうちこの３要素を全て満たすものが、先ほど申し上げた５件ということになります。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっとできれば内訳を教えていただけたらなと思うのですけれども、多分シルバーセンターのお風呂とかも入ってくるのかなと思うのですけれども。それから要件を満たす５件のうち、その他の２件は何なのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"その他の２件、３つの要件を満たす５件のうちのその他の２件は何なのかというのも伺ったのですけれども。これが品川区内のどういった施設でこの条例が改正されることで週１回になっていくのかというのを知りたかったので伺っているのですけれども。","respondent":"鈴木生活衛生課長","answer":"先ほど申し上げましたように、シルバーセンターのお風呂であったり、それからスポーツジム等に入っていて大きな浴槽があるものがその他の２件になると思います。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"シルバーセンターがゆうゆうの２カ所も入れて１０件で、サウナ等が２４件で、個室つき浴場が２件でしたよね。そうしたら、スポーツジムというのはどこに入るのか尋ねました。","respondent":"鈴木生活衛生課長","answer":"一番最後のシルバーセンター等というくくりでカウントしております。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ゆうゆうが２カ所で、これで私は１０件かなと思ったのですけれども、スポーツジムが何件かというのがわかったら教えてほしいと求めました。こういう研修がされているかどうかを品川区として把握されているのかについても説明を求めました。","respondent":"鈴木生活衛生課長","answer":"これは先ほど申し上げましたように、区の保健所のほうで年１回の菌の検査、そのときに数十項目にわたる衛生の管理チェックをしております。ただし、都の主催ですので、詳細の参加者数や参加率については情報が来ていないので把握はしておりません。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、私はそこら辺のところはぜひここでもご答弁いただけるようにしておいていただきたかったなと一言言っておきたいと思います。は私、そのうち１名の方が命を落としたという状況もあるということでありましたので、なぜかというところもお聞かせほしいと求めました。","respondent":"鈴木生活衛生課長","answer":"先ほど申し上げましたように、検査を行って検出された場合には、それが放置されて感染が広がるという現状がないというのが現実だと考えております。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"１５年のときに原則毎日換水で、あらゆるところに浴槽水は毎日完全にかえることが原則と書かれているのですよね。そうなると区としては認められるということになった場合、この検査の頻度というのはどういうふうに上げていく考えなのかについても説明を求めました。","respondent":"鈴木生活衛生課長","answer":"事業者のほうが自主的に行う検査が１回、もし区のほうに申請をして週１回の換水にするということであれば、それを２回か３回以上に上げていただくということになるのがこの規定の内容です。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"品川区としては１回で、業者がやった検査についても区としてしっかりと把握していくと、そういう体制をとるということでよろしいか尋ねました。","respondent":"鈴木生活衛生課長","answer":"水質検査につきましては、自主的に行ったものについても区の保健所のほうに報告をいただいておりますので、区の検査と自主検査両方を把握しております。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認だけよろしいですか。シルバーセンターはゆうゆうプラザを含めて１０カ所ということになるかと思うのですけれども、毎日換水するということでよろしいのか尋ねました。","respondent":"鈴木生活衛生課長、宮尾高齢者地域支援課長","answer":"シルバーセンターはゆうゆうプラザも含め、ちょっと新しい浴室は私は直接見ていないのですが、循環式でなければ対象にはならないので、毎日１回になると思います。 シルバーセンターおよびゆうゆうプラザの浴室に関しては、毎回全部お湯を入れかえて清掃しています。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それが今質問していた内容かと思ったので。シルバーセンター等１０件でサウナ等が２４件になっているから、ジムはサウナ等に入っているのではないのと書類見ながら思ったので、一応確認だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"そうなると、次確認ですけれども、この６０件中５件以外は全て毎日換水するということでいいかと。ここをお聞きしたいと思います。","respondent":"鈴木生活衛生課長","answer":"基本的には従業員や施設の規模、事業者の規模等何か理由があって衛生面が維持できるのであればということだと考えております。それから、当然対象になっていないそのほかの施設については週１回の換水は認められませんので、毎日の換水を継続していくということになります。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"意見","question":"それとやはり換水頻度を現行の毎日から週１回以上であればいいという規制緩和になってくると思いますので、ここはやはり慎重にすべきと考えますので、この条例には反対をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"第８１号議案、指定管理者の指定","agenda":"第８１号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今課長からもありました８月の委員会で報告いただいたとき、人員体制、人員が９人と前回答弁いただいたかと思うのです。子育て世帯のポップンルーム、オアシスルームのところも何人受け入れて何人体制でどういった資格の方がやられるのかというのを伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"オアシスルーム、ポップンルームにつきましては、保育部門は管理者を含めて全部で７人と今事業者の方と話を進めさせていただいているところです。こちらも基準にのっとって適切な体制だと考えていますので、万全を期して今後打ち合わせをさらに深めていきたいと考えています。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"提案","question":"やはりどういったサービスでどういう人員配置にされるのかというのが、大枠わかってないというか、そういう提案が今からされるということなのですか。前回の答弁のところでは非常勤を含めると９人だとおっしゃっていたのですけれども、非常勤を入れると９人になるということでいいのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"そして、人員体制の７人、９人というところですが、９人というのは施設全部の管理スタッフも含めて９人。うち、オアシス・ポップンルームの従事職員が常勤換算で７人と考えています。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"社協でやっているのは社協の職員が１人来て、それで１週間に一遍やると、そこら辺のところを教えていただきたい。非常勤の方は保育士が常勤換算で２名分で、それで常勤が８名と聞いた気がするのですけれども、そこら辺のところの人数を説明するよう求めました。","respondent":"宮尾高齢者地域支援課長","answer":"保育部門の人員に関しましては、まず常勤でいきますと管理者も含めまして常勤の職員は５名今のところ配置する予定です。ですから、この２名という常勤の枠を実際には非常勤の職員で充当するというような形で考えてあります。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、トータルで常勤が７名で、プラス非常勤が常勤換算で２名と、そういうことになるということですね。総合事業でミニデイをやるわけですから、あと、そういうふうな形での使われ方ということでいいのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"それと課題等々ありますので、そういったほかの場所での事業をしっかりと参考にさせていただいて進めてまいりたいと考えています。それ以外の使わない部分に関しましては、当然地域の方に使っていただける、こういった仕組みも導入させていただこうと考えているところです。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"この４億２,０００万円というのは変わらないかということと、東京都の補助金はわかっていたら教えてほしいと求めました。それはもう事業計画書ということで福栄会から既に品川区に対しての提案書としておおよそこういう事業でこれぐらいの予算でやるということはできてい…との意見を述べました。","respondent":"宮尾高齢者地域支援課長","answer":"工事、それと監理、こういった経費を全部含めておおむね２億５,０００万円強です。東京都の補助金につきましては、すみません、今手元に詳細な資料がないので、わかりかねます。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"下がったということは、これは歓迎すべきことだと思うのですけれども、ぜひここで答弁できるように準備をしておいていただきたかったと思います。２番、３番でそれぞれの点数みたいなのがわかっているのであれば、それも教えていただけたらと思います。","respondent":"宮尾高齢者地域支援課長","answer":"もちろん指定管理者の候補者の選定につきましては、定められた基準、ルール等にのっとり今回も選定をしています。トータルで８割程度の点数だったと前回お答えをさせていただいたとおりですが、そのトータル全てでそれに十分近い数字を今回出していただいたです。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひそういうふうなところも、私たちもそういうことだったのかというところがわかるような形での資料というのはぜひ検討してほしいと求めました。先ほどの４億２,０００万円が２億５,０００万円になったというものの理由とかがわかれば、最後教えていただけたらと思います。","respondent":"宮尾高齢者地域支援課長","answer":"工事の金額につきましては、最終的に工事が１月末の竣工に向けて金額がしっかり固まってきたというところで、２億５,０００万円という数字が見えてきたです。","id":"exchange-022"}]},{"id":"topic-03","title":"第７４号議案、平成３０年度品川区一般会計補正予算（厚生委員会所管分）","agenda":"第７４号議案、平成３０年度品川区一般会計補正予算（厚生委員会所管分）","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それは要望です。補正ということで確認なのですが、債務負担が加わることによって総工事費は幾らになるのかが見えないので、総工事費はお幾らぐらいになりますか。","respondent":"飛田障害者施策推進担当課長","answer":"総工事費としまして、５４億４,４８０万円となります。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一遍に聞けばよかったですけれども、工事監理費も説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"それにプラスしまして、工事監理費となりますと５,４７９万６,０００円という額になります。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"去年の決算が１０億９,０００万円で今年の予算が４３億円なのですね。これで５０億円になるのだけれども、実際幾らここで工事費が増えるか見えてこないのだけれども、そこの数字はどうとったらいいのか説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"現在平成３０年度は出来高払いということで、その後平成３１年度がその残りとなります。そのほかのところでは、増額分、工事監理費としてはこちらのほうも工事延伸に伴う人件費として１,３００万円プラスとなっております。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この今回の債務負担の２９億５,０００万円はこの１億１,２３０万円が乗っかっているのですか。それがトータルなのか。","respondent":"飛田障害者施策推進担当課長","answer":"詳細となりますと、当初の予定でした工事の出来高払いというのが工事費として２８億３,７７０万円。工事監理費としまして、当初のところで５００万円のところ、プラス１,３００万円ということで１,８００万円となります。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、今年度は２８億３,７７０万円の出来高予定だということですか。予算４３億円のうち２８億円が今年度の出来高で支払いするということでいいのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"平成３０年度の出来高のところが１４億３７０万円というところです。今回のところがプラス１億１,２３０万円ということで２９億５,０００万円となります。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"確認","question":"債務負担を設定することは了解をするのですけれども、その辺できるだけ聞かせてもらうことはできないでしょうか。監理ということで確認だけお願いします。","respondent":"飛田障害者施策推進担当課長","answer":"今回騒音のこととか地中障害物の撤去、また近隣の車両の搬入口ということで、今まで２カ所予定していたところを１カ所というところです。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"お近くの方から工事がおくれていることでちょっとお話がいろいろ出ています。工事がおくれることによって騒音の問題だとか、早くでき上ってほしいねということを言っていることもあるので、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、地中の障害物の発生があった、それの処分作業もというところでは、これはいつ発見したものなのかというところも伺いたいと思うのです。この時点でも工期がおくれるということは想定できなかったのか、それでも頑張って進めようと思っていたのか、ちょっとそこら辺を伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"７月の段階で我々も工期のところは１.５カ月おくれということは聞いていました。２月竣工ということでやっていたと私も聞いておりましたけれども、工期がおくれてしまうということになったと聞いています。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"日中一時、日中一時は２０人ということで想定してつくるという図が出されたと思うのですが、特別支援学校卒業生は何人ぐらいになるのでしょうか。さらに定員を大きく超えて受け入れるのか、それとも他区を利用せざるを得なくなるのか、そういった今後の利用者の対応のところを伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"既存の施設を中心にどういうふうにその方々に対応したほうがいいのか、もしかしたら希望が変わるかもしれない。そういういろいろな可能性があると思いますので、保護者に対して、また利用者に対して丁寧に対応できればと考えております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは特別支援学校にも事業所にも障害者団体へもこの告知をするということですので、誰でも説明会には参加できるということでいいでしょうか。それと、あと町会長へ報告というのがあるのですけれども、これは近隣町会長ということなのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"この１１月１５日の説明会なのですが、学校等、この施設に興味のある方に来ていただいて周知を図ろうとしているところです。特に今回近所の方のところ、近隣の区民の方にも情報、工事がおくれることを伝えていく必要があると考えております。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど第１希望が３名で、第２希望とかさまざま入れると１１名というのは、これは生活介護ということでしょうか。教えていただきたいのと、区内のそういう可能性ですか、そこら辺があるのかというあたりも教えていただけたらと思います。","respondent":"飛田障害者施策推進担当課長","answer":"先ほど新施設の希望者ということで第１希望、第２希望合わせると１１名程度ということですが、就労支援Ｂ型を合わせての数となります。どれだけの施設でどれだけの受け入れができるのかというところもまた区内の法人を中心に今話し合いを進めようとしているところです。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"１１名という、これは本当にやむを得ないという状況なのですが、今後に向けてさらに施設を増やしていただくということも含めてぜひ具体化もしていっていただけたらと希望をしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"１１月１５日の説明会なのですけれども、どうなのでしょう、説明をお届けするというやり方は考えておられないのか。そこについての周知のやり方、説明のより丁寧なあり方について、さらにお考えがあればお聞かせほしいと求めました。","respondent":"飛田障害者施策推進担当課長","answer":"きちんと出向いて説明をしないといけないと考えております。もちろんこのときの説明会だけではなく、受け入れていただく実習先のほうにも説明していかなければいけないと考えております。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問・要望","question":"２つ確認というか、要望というか。しっかりこれは１１月１５日の区役所講堂で昼と夜１回ずつやりますよということ以上に、より丁寧にやっていただきたいという要望をします。","respondent":"飛田障害者施策推進担当課長","answer":"３つの理由で今回、工期の延期となりました。このところについて、また施設整備課とも関連するところでありますので、詳細なことを聞きながら情報提供していきたいと考えております。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今、学校という話が出たけれども、最初の説明会でも学校が音を物すごく気にしていました。今言ったように学校側は最初からそれを指摘していた部分だと思うので、よくその辺注意しておいてもらいたいと思うとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"木村委員","kind":"質問・要望","question":"一応３つの延長理由に対して、また学校に対してもいろいろとあろうかと思いますけれども、しっかりしてやっていただきたいと考えています。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回施設のところが問題というか訴えられているわけですけれども、施設の職員による虐待が３件というのは、いつのことなのでしょうか。今回の分もきっと入っていると思うのですけれども、３件を教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"３件のうち１件はこちらに報告しているものです。その他２件については、本日資料を持ち合わせておりませんが、東京都が必ず公表をしているものです。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはりどう対処がされたのかというところでは、それがいつなのかが大事かと思って知りたかったので伺ったのですが、持ち合わせていないということで。これはどういう間隔で、１から１２まで改善させましょうというふうに出されているのですけれども、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"区だけではなく東京都と一緒に報告は受けております。現在は通常のほかの法人と同様に指導・検査を機会を捉えて行っております。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして虐待対応の終結というのを出すことになっているということなので、これに基づいて虐待対応の終結がされたということなのでしょうか。伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"先ほどの答弁の繰り返しになってしまいますが、平成２９年５月に最終報告を受けまして、この事案についてはそちらで一旦区切って終結ということになっています。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"その４人は満たしているのだということだったのですけれども、区としては把握されているのでしょうか。でも徹底したところでやはり人員が少ないとなかなか難しいと堂々巡りになってくると思うのですが、そこの辺区としてどうお考えになられているのか。","respondent":"松山障害者福祉課長","answer":"８名のところ、平均障害支援区分が５.１、配置基準上必要な職員数は２.６のところを４名の方を配置して対応しております。昨年看護師のほうも１名だったところをプラス１名して２名にしているというところでは、医療的な部分で対応というのを図ってあります。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"実態がどうかは私たちもまだ見ていないですけれども、こういった改善計画書だけでもちょっと疑問があるなという思いがするのです。そこら辺、先ほど職員研修をされているということでしたけれども、中身はどのように改善をされているのかを改めて伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"では、質の部分というところなのかというところで、どういう中身で改善計画がされているのかということをお聞きしました。一応改めて人員をさらに配置していく、利用者が安心して通える施設にするためにも、人員体制をというところには区としてはどうお考えか尋ねました。","respondent":"松山障害者福祉課長","answer":"どうやったらそれぞれの個別支援計画でご利用者が希望されたこと、効果的に支援ができないだろうかというまだまだ工夫の余地はあると考えています。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"虐待認定という形で認定されたわけですけれども、この虐待認定というのはどこがどういう仕組みで行うのかということも教えてほしいと求めました。それから、どういう体制で役割を果たすのかという、障害者福祉課の中の虐待防止センターの体制についても教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"３件のうちの１件、残り２件についてなのですが、先ほど申しましたように、今手元にはない状況ですので、今お答えしかねます。これら品川区と東京都が連携をして認定をするということになっています。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうしますと、あとの２件というのは、区内の事業所ではないということがわかったら、そこら辺のところは教えてほしいと求めました。そういう点では私は厚生委員会にもぜひ虐待認定がされた事案については今後に向けて報告をしていただきたいと要望したいと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"配置はされているかもしれないけれども実際毎日の状況というのは２４人を３人で見ているという状況になっていると利用者の方からお聞きしたのです。そこら辺のところはいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"支援のお一人おひとりに合わせた内容ということになりますけれども、ご家族と相談しながら過ごし方をつくっていくというのが基本だと考えています。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"あらゆる法人、あらゆる事業所、そういうところにぜひとも活かしていただきたいと。その点で最後にちょっとお伺いできたらと思います。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、品川総合福祉センターだけの問題ではないと考えております。本当に人権意識の向上を図って、二度とこういうことが起こらないようにということで、区の指導もきちんと行ってまいりたいと考えています。","id":"exchange-048"},{"speaker":"若林委員","kind":"確認","question":"これは会館のほうですか、先ほどの説明では、看護師等も含めて常勤換算で０.５と０.５を足して４になるのですと。そこら辺のご説明がこういう利用者およびご家族、一つちょっと入り口のポイントにあるのかと思うので、そこの対応を確認したいと求めました。","respondent":"松山障害者福祉課長","answer":"こちら、この方が担当者ですというような、そういった意味ではリーダーや看護師をどう捉えるかといったところでは説明が不足していたかと思われます。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"その上で足りないよねとかいう話は当然よくわかりますので、まずそこのボタンのかけ違いは今後なくしていただきたいということと、あともう一つ確認。違う原因なのか、そこら辺どのような改善報告書の中身なのかというのを確認しておきたい。","respondent":"松山障害者福祉課長","answer":"そういった中で、要約しますと、区といたしましてはまずは利用者への人権意識が不足していたということ、あるいは職員への指導が不足していた。","id":"exchange-050"},{"speaker":"若林委員","kind":"質問","question":"自己分析、第三者が報告しているわけですので、今の要約というのはそういうことなのかなと理解いたします。はい、そうですかとできるものでは人間ないというのはそれは当然ですけれども、今後はしっかり取り組みをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"意見","question":"先ほど来虐待防止委員会とか研修をやっていく、質疑の中でその辺はなかったというふうに判断ができると思いました。その意味で、自民党・子ども未来については、今回不採択ということでお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"結論を出すで、採択をお願いします。人員配置をさらに充実させてほしいと求めましたし、そして施設のあり方にしていってほしいと求めましたので、採択をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"木村委員","kind":"意見","question":"不採択でお願いします。今回このようなことで人的要因ではないと、数が少ないからどうのこうのではなくて、本当に違うところに原因があるのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"質疑というか、これは仕方がないかなと思うのですが、この方、けがは大丈夫ですか。事故を起こすと本人も大変なことだし、その辺だけちょっと確認をしておきたい。","respondent":"矢木生活福祉課長","answer":"幸いにもけがはございませんで、一旦停止はしたのですけれども、前に出たところでぼーんというふうに、前輪に当たって前輪が破損したという、その程度で済んです。","id":"exchange-055"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"どういう形で。会議体はあったにしても共有していくというか、そういう場、そういうものがあるのでしたかとの意見を述べました。","respondent":"大串福祉計画課長","answer":"ただ、地域福祉計画の策定委員会をこれまで３回実施をしておりまして、なおかつ説明もさせていただいているところです。こういった全部を載せるということは難しいですけれども、主なご意見、あるいはこういった意見があったということで一定触れする予定です。","id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"包括的な支援体制の構築を国から求められているということなのですが、これは基本的に品川ではどこが担う考えなのか。それと、各地区支え愛活動会議の委員というのが、どういうメンバーか説明を求めました。","respondent":"大串福祉計画課長","answer":"どこがというのはなかなか難しいところかとは思っております。一定、どういった形が一番地域を支える上で有効なのかというのは今後とも考えながらやっていきたいと考えているところです。","id":"exchange-057"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"包括的支援事業等を地域において一体的に実施する役割を担う中核的機関として設置される」ということが書かれているのですけれども、この地域包括支援センター、国の中核的位置づけというところでは品川区としてはどう考えられているのか尋ねました。","respondent":"大串福祉計画課長","answer":"ただ、地域包括支援センターが中核的な役割といったところで求められていると考えておるところです。あるいはすみ分けといったところも考えながら、全体的に包括する支援体制、流れといったものをつくっていければと考えております。","id":"exchange-058"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その中で世田谷区で話を伺ってきたところでは、そこで障害者の相談も受けるというふうなことにしたというお話を伺って、地域包括の役割というのも。つながっていくのかなと、そんな思いがしているのですけれども、その点は。","respondent":"大串福祉計画課長","answer":"このつなぎがスムーズに進めていければ品川区なりの包括支援体制といったものが構築できると考えているところです。","id":"exchange-059"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その在支のところから保健師や社会福祉士も３職種が大体配置されていたので、そういう形でされていたというところでお聞きしたのですけれども。そういう点では、改めてその辺のところは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"こんの委員","kind":"確認","question":"ちょっと現状というか確認です。そうした支え愛・ほっとステーションの実績など、各地区で具体的にどのような独自の取り組みをしてきたのか、まず説明を求めました。","respondent":"大串福祉計画課長","answer":"そういった形で、本当に各地区それぞれいろいろな取り組み方があるところですけれども、そうした中で少しずつでも進めていく。","id":"exchange-061"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる会議体、各地区で進める温度差はある。その点はどういうふうにされているのかというのと、困っている人をどういう人がつなげてくるのか、そこら辺の様子を説明するよう求めました。","respondent":"大串福祉計画課長","answer":"だから、一律１３地区全体に何かというところはやはり難しいのかなと考えているところです。そこから先のところで、しかるべき専門機関、例えば在支とかそういったところへのつなぎもあわせてステーションでもやっているといったところです。","id":"exchange-062"},{"speaker":"こんの委員","kind":"意見","question":"では誰が先導してどういうふうに具体的にしていくのか、自分たちでできるのだなという思いになっていくと、こういう報告があったのです。","respondent":"大串福祉計画課長","answer":"当然それが全てその地区に当てはまるわけではありませんけれども、そうした中で、すごくそれが大きく回っていく予感はしているところです。そういったものも皆様方にご説明しながら、方向性といいますか、そういったものを皆さんと探っていきたいと考えております。","id":"exchange-063"},{"speaker":"こんの委員","kind":"質問","question":"協働というところでは、それは必要だよね、これがきっかけとなってほかもそうかもしれないという捉え方で予算化していくという話もあったのです。もし予算が必要であれば、そういったところもつけていくような進め方が必要ではないかと思うのですが、その点はいかがか尋ねました。","respondent":"大串福祉計画課長","answer":"先行事例も幾つかあると認識しておりますので、その辺も見させていただきながら、あるいは各１３地区それぞれ個性がある地区展開をしております。丸ごとというふうに捉えて地区をどのようにつくっていくのかといったところを踏まえた上で考えていきたいと思っているところです。","id":"exchange-064"},{"speaker":"若林委員","kind":"質問","question":"どうやって行政も地域も専門機関も一緒になって、まさに区役所の中で横断的にはこれはできないものですから、さっきもご答弁がありましたけれども。すみません、ちょっと質問というか議論というか、そういう感想を持っていますので、何かコメントがあれば。","respondent":"大串福祉計画課長","answer":"そこに対して区のほうでさまざまな支援等々考えられてこようかと思いますので、やはり既存のもの、さまざまな形があります。そういったものをうまく連携させるような形、連携させていくにはどうしたらいいかといったところはこれからも考え続けていきたいと考えております。","id":"exchange-065"},{"speaker":"若林委員","kind":"提案","question":"提案型というテーマを決めないでと、やはりご提案に対して区としては策定委員会を設けてこれはできます、お互いの意見をぶつけて。感想だけでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"こんの委員","kind":"意見","question":"ですので、ぜひ私もそれをお願いしたいと思います。何かあれば、お願いしますとの意見を述べました。","respondent":"大串福祉計画課長","answer":"地域の皆さんの思いを受けとめた上で、それは我々だけが一方的に考えるものではなく、やはり地域の皆さんと一緒に考えていく。どういうことをやればいいのかというのを本当に皆さんと一緒に考えていきたいと思いますし、まさに話を進めていきたいなと考えています。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3520#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":66391,"voices":204}},{"id":"h30-20181029-8","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"建設委員会","time":"午前１０時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件整理しています。","topics":[{"id":"topic-01","title":"の第７９号議案 品川区手数料条例の一部を改正する条例","agenda":"の第７９号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"現状で省令事項にあるような1)と2)の条件を満たしていて、これから不要になるような例が区内にどれくらい存在しているのでしょうか。防災、安全の上で問題が生じてくるということはあるのかどうか、伺いたいと思います。","respondent":"長尾建築課長","answer":"これまでの許可実績等も確認してみたのですが、品川区内では想定されるような案件がなさそうであるという見込みです。避難経路を２つ以上確保するとか、そういった観点では、通常の建築基準法の基準を守ったものと同程度の安全性は担保されていると考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"続きまして、２点目の改正内容なのですが、仮設興行場等とは何を差すのか、まずお伺いします。そのことによって安全上、問題が出てこないのか伺いたいと思います。","respondent":"長尾建築課長","answer":"仮設の興行場が何を差すかということですけれども、１つの例としましては、例えばサーカスのテントなどが考えられると思います。原則としては、原則的には仮設許可をするにしても、できる限り基準を守ってくださいというところをベースにして許可は出してきている状況です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとお伺いしたいのが、最初から１０年の貸し出しの期間が決まっていてつくられているような建物とかもありますけれども、そういったものがこういう仮設興行場というものに当たってくるのかどうか伺いたいと思います。","respondent":"長尾建築課長","answer":"個別の建物に関しては、仮設許可を得ているか得ていないのかというところは捕捉をしかねるのですけれども、今までは１年以内の期間である場合は仮設の許可をとってというところになっておりますので、おそらく仮設ではなくて常設の建築物として建てていたものと考えられます。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"確認","question":"先ほどのやりとりの中で、それはすごい画期的なことだなと思ったのですけれども、実際にこれは本当に当たるものがないのかどうかというところが１つ。１番目と２番目も含めて、法律上のことですけれども、説明を求めました。","respondent":"長尾建築課長","answer":"今回新しくできるもので、１年を超える期間を設定して建築する仮設建築物ということは考えていないというふうに聞いております。１年を超えて設置することも想定されるというところから、国の法改正もなされているということです。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"最初に背景を伺えばよかったんですけれども、１番については、逆に裁量の幅が大分狭くなったという形で捉えればいいということですね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"第４３条第２項というのは、よく理解しかねるところがあったので、簡単に説明していただけると助かります。お願いします。","respondent":"長尾建築課長","answer":"別紙２の上段、２、道として通行ができるように一定の舗装がなされていることといった条件を満たしているかどうか。通常の建築基準法の基準では建てられない敷地であっても、建てることができるようになるというところになります。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"これはどのような世の中の具体的な動きがあったのかということを伺いたいと思いまして、そういう背景を伺いたいと思いまして、質問をさせていただいた趣旨です。","respondent":"長尾建築課長","answer":"敷地を隣地から買い増していただいて２ｍ以上の接道幅がとれるように努力していただいたりというところで建築できるようになっているのですけれども、例としましては、人の通行のある通路部分に２ｍ以上接している形で戸建住宅を建てる場合というところであります。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"品川はどう見ても農道はあり得ないわけでして、そういう事例が増えてきたということで、こういうような法律の改正がなされたのかというふうに理解をしてよろしいのか尋ねました。","respondent":"長尾建築課長","answer":"全国的に見れば、そういった側面もあると思います。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"手数料についてお伺いしたいのですけれども、特に仮設興行場等で、手数料１９万５,０００円となっておりまして、一見すると結構高額な料金かなと思っているのですけれども、その手数料は、どのような基準というか、趣旨で決まったのかを示すよう求めました。","respondent":"長尾建築課長","answer":"今回、新しくできました１年を超える期間を設定して許可をする場合については、建築審査会の同意を得る必要があります。都についてはもう既に改正が行われておりますが、同様の改正をしておりますので、そういったところの金額も整合性を見ながら設定しております。","id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"ちょっと確認になってしまうのですけれども、定義というか、そのあたりはまた別ということでよろしいのですね。例えば、保育施設ですとか、別の施設に関しては、こちらに関しては適用はされないということで、範囲についても確認させてほしいと求めました。","respondent":"長尾建築課長","answer":"仮設建築物として設置するかというところにつきましては、あと、実際に設置が許可される期間については変わってくるものになります。この用途だけという限定もございませんので、基本的にはどのような建物であっても仮設建築物というのはあり得ることにはなります。","id":"exchange-010"}]},{"id":"topic-02","title":"の第７４号議案 平成３０年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"の第７４号議案 平成３０年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"助成内容、2)のほうも細かく言えばブロックとフェンスの部分に分かれていると思うのですが、そこら辺は併用ができるのかどうか確認させてください。４点目は、そこら辺の現行制度との兼ね合いといいますか、お伺いしたいと思います。","respondent":"長尾建築課長、溝口公園課長","answer":"緊急対応としてというところで書いておりますけれども、現時点では、特に期限を設けるといったところは考えておりません。こちらの軽量フェンスの設置工事については、補助率が２分の１となっておりますので… やはりそれぞれ制度を目的を持ってやっていくところです。はうるおいのある品川区をつくる、そういったところの観点で、両課しっかり連携しながら進めていきたいというふうに考えておるところです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"調査のほうはぜひそういったことで今後の啓発といいますか、制度を区民に実際に使ってもらうというときに生かしてほしいと求めました。もちろん最優先すべきは防災上の安全の確保だと思いますけれども、区民の皆さんにとってもいいのではないかと思いますので、それは意見で述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１つ、確認の意味で伺いたいのですけれども、建築基準法上の道路については全て調べるということでいいのかどうかというところが１つ。一般質問でもありましたけれども、確認で、もう一度確認したいと求めました。","respondent":"長尾建築課長","answer":"都道や国道、私道も含めて、区内の建築基準法上の道路というふうな位置づけがあるもの全てということにしております。大阪府の地震が起こった際に、助成制度を活用して道路の安全性の確保を皆さんにご協力いただけるようなところに持っていきたいと考えております。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問","question":"９月１１日ですか、私どももこれを推進してきたものですから、周知の難しさを非常に体験をしたところです。ですから、パッと目に飛び込むような掲載の仕方をお願いしたいのと、所有者に届くような周知の方法の検討をお願いしたいところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問","question":"幾つかお伺いいたします。状態ですか、可能な範囲でお願いできたらいいのかなというふうに考えているのですが、そのあたりをお聞かせいただけたらと思います。","respondent":"長尾建築課長","answer":"予防といいますか、啓発といいますか、そういったところもあわせて行っていけるようなところを今後検討していきたいと考えております。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"重要なことですので、正確に優先順位をつけながら、無理のない計画の中で進めていただけるということがわかりました。２０件ということで助成をされるようなのですけれども、次年度以降のことも計画的に進めていただけたらと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、本日いただいた資料に、工事の助成予算額１,０１１万２,０００円とありますけれども、この額の内訳は、補正予算の事項別明細書の工事費助成１,００８万円と、事務費の３万２,０００円を合わせた合計額ということでよろしいか尋ねました。","respondent":"長尾建築課長","answer":"委員がおっしゃっているとおり、助成の費用と事務費を足した金額となっております。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"基礎調査は先ほど目視とおっしゃられましたけれども、大体どのくらいの期間がかかるものなのでしょうか。２点示すよう求めました。","respondent":"長尾建築課長","answer":"調査期間につきましては、助成制度と同じように１２月に入りましたらすぐ調査を開始できるようなことを想定しております。３カ月前後はかかると考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"資料の２についてですけれども、落下防止基準とは何でしょうか。これで区の求めるような落下物ゼロというのは実現するものなのかどうか伺いますとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"項目としては１９０項目ほどあるですが、整備点検の実施、あるいは教育訓練等々がうたわれているです。実施の効力といいますか、この基準を実施計画に位置づけないと、例えば外国の飛行機は日本のほうに来ることはできないという内容になってあります。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"情報発信拠点はつくられればいいというものではないですけれども、ぜひ早めに設置できるように努力してほしいと求めました。それが実際に守られるかどうかというのは、これで区の求めるような落下物ゼロというのは実現するものなのか、改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"まだ実施の担保といいますか、今後、しっかり示していかなければいけないです。こうした取り組みがしっかり実施されていくように、引き続き、国のほうに求めていきたいです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"出席状況は２５区市とありますが、この４月３日の幹事会には、品川区の部長は参加したのでしょうか、しなかったのでしょうか。それと、来るべき連絡会、品川区としては何を発言をするのか、ぜひ伺わせてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"区民への丁寧な説明、騒音影響の軽減に向けた取り組みというところを強くその場で、求めたです。区としましては、これまでどおり、先ほどの３点について強く求めていくというところです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"今の時点で行われることは明らかなのですから、どういったことを発言するのか、区長選挙でも新ルート計画の問題が争点となって大議論となりました。この連絡会で、品川区が区民の意見を代弁するのかというのは非常に重要な点だと思いますので、もう少ししっかりとお答えほしいと求めました。","respondent":"鈴木都市計画課長","answer":"先ほど、あるいは騒音影響に対する区民の不安を払拭していただく取り組みを、やはりその場でも強く求めるというところになろうかと思います。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"自民党にもお伺いしたいのですけれども、あと１年少し後には飛んでしまうわけですから、タイムリミットはおのずとあると思うのです。そこら辺をどう考えていらっしゃるのか、ぜひ伺いたいと求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"私の質問ではないので、そこの行間を読むところは非常にはかり知れぬところがあるのですけれども、質問者のニュアンスをもう１回私のほうから確認をし、よく理解をしなければ、この質問には答えられませんので、この場でのお答えは差し控えさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそこは確認していただいた上でお答えいただきたいのですが、ぜひそこら辺は自民党・子ども未来としてのお答えを伺いたかったところなのですが。そういった意味で、国交省に対して、その後、求めていただいたのか、それともこれからなのか、ぜひお伺いさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"安藤委員が１人で長々とご質問をされたのですけれども、先ほどからの質問を聞いていて、私も意見を述べさせてほしいと求めました。この問題も非常に大事な論点の１つとして、これは国の問題ですから、戦略であって……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは課長にお伺いしたいのですが、この前の私どもの定例会の一般質問で、もう一度言います。この前の陳情審査、具体的な手法をさらに求めていくと区はおっしゃっているのですけれども、そこについて品川区の具体的な見解を求めたいと思います。","respondent":"鈴木都市計画課長","answer":"具体的な取り組みとして、区としても強く申し上げている教室型説明会の実施について、調整しています。ご説明しました落下物の取り組みについては、やはり実施担保性をどうやってとっていくのかというところも、今後。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区としての考え方を伺ったのですけれども、品川区上空を飛行しないルートの再考を強く求めていくということに関しては、このように考えております。１つ確認をさせていただきたいのですが、反対をされる方の中に、資産価値が３０％下がるということを確定的におっしゃる方がいました。","respondent":"鈴木都市計画課長","answer":"やはり伊丹においてもですが、直接的な因果関係は、これをもって土地価格の下落につながったということはないというところは聞いてあります。区としては、今後も国のほうにこういったところは情報をしっかり確認しながら進めていきたいです。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"確認","question":"私はどうしても看過できなかったのは、こういう不安をあおるような未確認の情報を選挙に勝つがために、これを喧伝をされたということ。本当に区民のことを考えているのかというところで、私は非常に個人的に、ちょっとこれは見過ごせないなと思ったので、確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"伊丹の空港へ行って担当の方にお話を伺ったところ、交通の利便性が上がる、まちづくりが推進できたという部分を多く聞きました。あくつ委員の質問の中で、伊丹はそういうことは一切なかったというような話を伺っておりますけれども、ご答弁願います。","respondent":"鈴木都市計画課長","answer":"伊丹、また福岡空港周辺ですが、航空機騒音により不動産価格が下がるといった直接的な因果関係は把握されていないということで聞いております。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"せめて一般の住宅の防音措置はやってほしいという声が非常に多いのですけれども、これをしっかり求めていっていただきたいのですけれども、そういったお話は継続的にされているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"夕方３時から７時までの時間を切ったということは、結果として対象になるようなところはないというところで、国のほうからは聞いてあります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"まさに一般住宅の防音措置は最低限やっていただきたいことなので、引き続き、粘り強く交渉していっていただきたいと考えております。そういった問題の可能性もあるのですけれども、そのあたり、国としてどういうふうに捉えているのか。","respondent":"鈴木都市計画課長","answer":"国が今年の３月に示しました総合パッケージの中で、落下物が起こった場合の補償の取り組みについては公表されているものがあります。ただ、共同してそういった事例に対応していこうと、そういったところの中で対応も図られていくのではないかというふうに感じておるものです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"区としても撤回していくことも求めていくべきかと、撤回してくださいというふうに申すべきだと考えておりますけれども、いかがでしょうか。別の代替案をぜひ検討していただきたいということをお伝えするべきだと考えているのですけれども、そのあたり、いかがお考えなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"国としましては、引き続き必要な調整を進めていく、新ルート案の実施に向けて必要な調整を進めていくです。その中身を区のほうで１つ１つ確認をするということは、そういったことは当然ながら考えてございませんが、状況については確認していきたいです。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"この際ですから、このルートを見直したほうがいいのではないでしょうかといことを交渉として言っていくべきかと考えておりますけれども、その点はいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"それを考え、検討を進めていくのは国の責務、国がやるべきことというふうに考えてあります。国が計画案を進めるということを申しておりますので、丁寧な説明あるいは落下物対策、あるいは騒音軽減に向けた取り組みを国のほうに求めていくです。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも、端的にお伺いしたいのですけれども、区が国に対して撤回を求めることができない理由は何なのでしょうか。撤回は求めるだけですから、撤回ということを求めていくべきだと、撤回を求めることができない理由は何か尋ねました。","respondent":"鈴木都市計画課長","answer":"今、この計画案について国に対して求めていくことについては、何度もこの場で述べさせていただいているとおりです。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"やっぱり交渉内容の１つとして、今こそ撤回されたらいかがでしょうかということも述べていってもよろしいかと考えておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"先ほど、あくつ委員とのやりとりの中でちょっとわからなかったことがあったので、それは新たな動きがあったということなのでしょうか。そこら辺についてもう少し尋ねました。","respondent":"鈴木都市計画課長","answer":"１つの用途的な拡充と、羽田空港における新たな飛行経路の運用に対応した航空機騒音の強度および頻度の基準を追加ということで、航空機騒音。結果、品川区にとどまるものではございませんが、他区も含めて拡充がされてきたです。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"単純に今までは１日の中でならしていたから、１５時から１９時という規定が加わることで、それが変化する可能性があるということなのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"そういった国の拡充ということで、まず告示の内容は、基準的なことしか示されておりませんので、先ほどご答弁申し上げたとおり、そういった拡充がされて、区内のどういった建物が対象になるかというところを、今、国のほうに情報を求めているところです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"区からも２つの政党に対して、にもかかわらず、新ルートは住民の理解が得られていないということを区は認めるのですかと質問しました。伺います。","respondent":"鈴木都市計画課長","answer":"区としてもそういう認識です。やはり教室型説明会等、直接的に区民の方に説明いただける場を国にしっかり求めて、周知を国のほうで行っていただきたいです。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"しかし、品川区としては、区民にこの計画の理解を得られていないということを認めないのですか。もう一度お伺いします。","respondent":"中村都市環境部長","answer":"そういった二択ではなくて、今現在は、区民の理解が十分ではないという認識です。したがいまして、国に対してさらなる丁寧な説明を求めているです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"ルートの通る地域を中心にとったアンケート、２,３００の回答が返ってきましたけれども、８３％の方が反対と答えております。このルートに対する反対の声を受けとめていくべきだと思いますし、それを受けとめた上でしっかりルートの撤回を国に強く求めていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"松永副委員長","kind":"質問","question":"区としてはなかなか周知ができていないというところで伺ったので、区としてどのような形で区民の方に周知をされてきたのか伺いたいと思います。ですので、何か区として新たな周知方法はご検討されているのか、その辺を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区民に広く実施について知っていただくということは非常に大事かというところでございまして、これは今後の検討ですが、そういったとこで広く第５フェーズの実施について案内していけたらです。","id":"exchange-042"}]},{"id":"topic-03","title":"平成３０年陳情第２０号 コミュニティバスの運行を求める陳情","agenda":"平成３０年陳情第２０号 コミュニティバスの運行を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"一般質問でも聞いたのですけれども、運行することに方針を変えた理由は、何か状況の変化とか何かあったのでしょうか。とりわけなぜ移動の権利を求めるかというと、さまざまな事業の施策の土台になるというのが、こういう移動の権利の保障だと考えています。","respondent":"鈴木都市計画課長","answer":"バス、こういった地域交通につきましては、非常に区民にとって日常生活に必要不可欠なライフラインだという認識です。生きがいや健康づくりにもつながっていくというところもありますので、そうした視点を踏まえて検討をしていきたいというものです。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"最終は２１時２８分ということで、こうした本数があまりにも少ないというところでの不便をどのように考えるかということを伺いたいのが１つと。以上２点伺います。","respondent":"鈴木都市計画課長","answer":"競合するような選定ということは基本的にできないというふうに考えてありますので、そうしたところを大きな課題と据えながら検討はしていきたいです。検討していくかというのは、当然ながら優先順位をしっかり整理検討しながら、検討していきたいです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"提案","question":"難しいというのは、ちょっと理由がわかりませんが、なぜ全域で走らせるのが難しいと考えておられるのかお伺いしたいと思います。ルート選定の調査内容の中に、そちらを提案したいと思いますけれども、こちらについてはいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"そうしたところとの競合を踏まえながら検討していく中では、そうした点で課題が非常に大きいという趣旨で答弁差し上げたものです。当然ながら検討を進める中ではさまざまな手法を使って地域の方の声を聞きながら検討を進めていくというところはしっかりやっていきたいです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"提案","question":"バス停からの距離、駅からの距離ということにとどまらず、そこら辺については調査をするおつもりがあるのかどうか伺いたいのが１点です。","respondent":"鈴木都市計画課長","answer":"これはさまざまな形で、どういった形の区民意見を集約するのが効果的かというところも含めて、しっかり検討していきたいです。道路の狭い荏原地域ですとか大井地区が、バス停から遠い地域ということで、そういった地域を中心に検討しているところであります。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望になりますけれども、実際に暮らしていて、移動に不便を感じているのは区民の皆さんなわけですから。上大崎などの地域も、ぜひそういった地域からの声をしっかり踏まえて、コミュニティバスの運行に向けて努力してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特定の会派がいたずらに根拠もないような要望を出して、平成２４年の第３回定例会の一般質問で地域公共交通会議、この設置を求めて。区民の声も伺っていただいて、これは実現に至ってほしいと思うのですけれども、ここについてご答弁をお願いしたいと思います。","respondent":"鈴木都市計画課長","answer":"来年度以降のルートの検討、あるいはスキームの検討につきましては、ここの地域を限定して検討をスタートしますとか。しっかり区内のコミュニティバスの効率的なあり方について、検討会でもご意見をいただきながら、しっかり検討していきたいです。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどの私の質問を訂正させていただきたい。これは意見ですけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"大沢委員","kind":"質問","question":"区長のご認識と行政側の今のご認識として、どのように課題についてお考えなのか。そこはやはり首長と現場をお考えになっている行政当局の考え方、どうなっているか、現状をお伺いしたいのですが。","respondent":"鈴木都市計画課長","answer":"民間の交通事業者に関しましては、基本的には地域交通についての足を提供していただきながら、やはり最終的には事業採算性が課題となるです。","id":"exchange-050"},{"speaker":"大沢委員","kind":"質問・要望","question":"地域の方に対して耳を傾けて地域の要望に十分にこたえていくというのは大前提でありますけれども、現状でそこのところはどのような形で考えていらっしゃるのか、ご答弁願いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはり実施検討に当たっては、その事業採算性的なところは重要な課題ですので、しっかり検討してまいりたいと思います。運行後の、本当にさまざまな視点を多角的に検討して、事業採算性についてはしっかり視野に入れながら検討していきたいです。","id":"exchange-051"},{"speaker":"大沢委員","kind":"質問","question":"この間、コミュニティバスということで質疑がありましたが、タクシーという存在も欠かせない交通手段だと思います。今、２つの事業主体が出ましたけれども、タクシーはどのようにお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"先ほどご紹介いただきました区が立ち上げております地域交通検討会の中には、バス事業者とともにタクシーの協会の方々にも入っていただいております。","id":"exchange-052"},{"speaker":"筒井委員","kind":"質問・要望","question":"この陳情にもありますとおり、福祉目的はもちろん、各地域間の交流、商業、観光の活性化という視点からでも、ぜひルートとかバス停の所在等々を考えていただきたいのですけれども、この各地域間の交流、商業、観光の活性化という点において、区としては現時点でどうお考えなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"新宿駅周辺にコミュニティバスを巡回的に走らせて、人の流れ、観光客の流れをつくっていくというところを行っていると聞いてあります。観光視点、あるいはそういったところが品川区としてなじむかどうかというところも含めて、あらゆる視点で検討は進めていきたいです。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問・要望","question":"その点に関連しまして、補助２６号線は、ほかの民間のバス会社も２６号線開通とともに運行するということは決定されているような状況でしょうか。その現状を示すよう求めました。","respondent":"鈴木都市計画課長","answer":"２６号線を活用してそうした民間のバス事業者の新たなルートというところは、折に触れて要望、意見交換を行っているです。コミュニティバス導入の検討に当たっては、補助２６号線の開通は大きいところですので、こうしたところも視野に入れながら検討していきたいです。","id":"exchange-054"},{"speaker":"筒井委員","kind":"確認","question":"そうした確認をとらせていただいたのは、補助２６号線開通とともに、確定には至っていないということでよろしいのか尋ねました。","respondent":"鈴木都市計画課長","answer":"２６号線のバスルートの運行につきましては、文書をもって区のほうから要望という形で出しています。それについてバス事業者から前向きな回答はいただいているところですが、状況としては変わっていないです。","id":"exchange-055"},{"speaker":"安藤委員","kind":"意見","question":"本日を結論を出すで、採択ですが、やはりこれまでこのような陳情をはじめとする区民の意見が今の区長をしてコミュニティバス運行にこぎ着けたということで、この陳情は採択して、今後さらに区政を進めていく必要があると思いますので、採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"松永副委員長","kind":"質問","question":"我が会派は、継続でお願いします。先日行われました第３回定例会でも、コミュニティバスについての質問があり、この陳情に関しては継続とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"}]},{"id":"topic-04","title":"の戸越六丁目東地区のまちづくり","agenda":"の戸越六丁目東地区のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"なぜ公聴会を開かないのかという質問に対して、８月７日の説明会で出された意見というのは、資料として提出されるのでしょうか。ぜひされるべきだと思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"前回の説明会でいただいたご意見、またこれから開催する説明会でいただいた意見の都市計画審議会への提出につきましては。そのため２通（４名）という記載をさせていただいているものです。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"これ以上の形骸化を防ぐために、ぜひそういった措置はやっていただきたい、これは要望です。説明会の案内の仕方、どういうふうに多くの方に参加してもらうような工夫ができるのか、対象の範囲ややり方について伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちら、今日配付している資料と同様の案内書をポスティング、それから郵送の資料としてご案内をする予定となっています。区のホームページでもご案内の予定もありますし、それから、広報しながわの１１月２１日号にも掲載の予定としております。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"少なくとも時間帯を変えて、曜日を変えて、増やすべきだと思いますけれども、いかがでしょうか。伺います。","respondent":"東野まちづくり立体化担当課長","answer":"それから、説明会の開催は月曜日の夜だけで大丈夫なのかというようなことです。この日程で、２回目の説明会となりますので、十分な内容のお知らせができるというふうに考えてあります。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"資料であと２点ほど気になる点があったので伺います。この３００％、７ｍというのは、具体的な根拠は何かあるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"説明会の中で補助２９号線自体は東京都が平成３２年度を目標に掲げて取り組んでいるというところのご説明をさせていただきました。今回、補助２９号線上を外れた沿道地区につきましては、明確に目標年度を切って外側の延焼遮断帯の形成を図っているというお話をしなかったです。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"今のご説明を聞いても、補助２９号線、やはり防災とは関係ないのかなというふうにどうしても思わざるを得ないような印象です。私が伺ったのは、３００％が延焼を防ぐ機能を果たすという根拠はあるのですかということで、何も根拠はないということでよろしいか尋ねました。","respondent":"鈴木都市計画課長","answer":"延焼遮断効果につきましては、沿道の方々の住宅であったり、あるいは違う用途の建物であったり、さまざまだと思います。３０ｍというのは、２階建て、７ｍというところを設定させていただいているところです。","id":"exchange-062"},{"speaker":"安藤委員","kind":"意見","question":"あるいは、特に目標年度はありませんというようなところで、やはり防災のことを考えている事業だとは到底思えません。この計画案を私はやめるべきだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"}]},{"id":"topic-05","title":"の平成２９年度指定管理者による管理に対するモニタリング・評価","agenda":"の平成２９年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"１回でも滞納したら連帯保証人に連絡をとるというのが現実的なのか、そこについて、そこについてのご見解を伺いたいです。平成２７年度から名称が変わって「宅地建物取引士」になっていますけれども、確認をしていないのではないかというような、ご指摘をお願いします。","respondent":"森住宅課長","answer":"ただ、６カ月を超えてしまうような場合につきましては、明け渡しを求めるということを進めているところです。ですので、同じような形で毎年改善等もありますけれども、これはそれぞれケースごとに取り扱っていきたいというふうに考えてあります。","id":"exchange-064"},{"speaker":"あくつ委員","kind":"確認","question":"ちょっと私も意地悪な言い方をしましたけれども、ただ、すごい高い水準での収納をしていることは間違いないので、実態的にはものすごい良いお仕事をしていただいたいるのかなとは思いますので、そこのところを指摘したかったわけではないので、ただ、文書の表現的に確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"人がどういうふうにかわっているのか、かわっていないのかとか、そういうところは把握されているのでしょうか。伺います。","respondent":"森住宅課長、古郡交通安全担当課長","answer":"今回、先ほども申しました定期的な連絡をとりながら、早い段階で対応ができているということで進めてきた結果だというふうに考えております。今年度やっているということもありますので、そういった中では… 人員体制の関係については、職員については全部で７４名、場長が全部で１１名ということで、離職率については把握はしておりません。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"少なくとも人員体制のところもお伺いすればこういうふうに答弁で出てくるわけですから、ぜひわかるような形で毎年報告していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"森住宅課長","answer":"大きく変えるということは考えてございませんけれども、２ページ目の４番で専従職員６名というような記載をさせていただいているところです。","id":"exchange-067"},{"speaker":"横山委員","kind":"質問・要望","question":"区民優先制導入ということがあるのですけれども、こちらはどのようなシステムなのか詳しく教えていただけたらと思います。管理者の方がいらっしゃって、どういう運用や利用の補助をされているのかというところを教えていただきたいと思うのですけれども、お願いいたします。","respondent":"古郡交通安全担当課長","answer":"以前は番号を指定して、そこだけしか使えないという状況でございました。自転車のチャイルドシートの関係で、お子さんを乗せている場合や物が多かったりした場合について、管理員が補助をしてやっているという状況です。","id":"exchange-068"}]},{"id":"topic-06","title":"の品川区空き家等対策計画の素案について（パブリックコメントの実施）","agenda":"の品川区空き家等対策計画の素案について（パブリックコメントの実施）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"大きいＡ３の１枚目の資料の左下のほうに、２０１７年度末現在の状況が書いてありますけれども、空き家を改善していくお考えがあるのか。目標についてお伺いしたいと思いますし、どの程度進むと想定されているのか伺います。","respondent":"森住宅課長","answer":"セミナーを進めていく等、定期的に所有者等に通知を送りながら、しっかりと改善していただくというところです。あるいは記載しておるそれぞれの事業を進めまして、適正管理がなされていないものについては、対策を進めていきたいというように考えております。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういったような目標も特にこの計画では書かれているものではないということでよろしいのか確認させていただきたいのと、母数が１９というちょっと少ないですけれども、一番の理由は何だと考えていらっしゃるか伺いたいと思います。","respondent":"森住宅課長","answer":"それから、維持管理を行っていない理由、１９件になってありますが、アンケートの中で回答をいただいたものがこの数です。管理を自分でやらないといけないという認識がなかったという方もおられます。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"今のお話ですと、実際、維持管理をどうにかしたいと思って悩んでいるというのではなく、そもそも維持管理をしなくてはいけないという認識がないということが一番の要因だということで、そういう区の認識ということでよろしいか尋ねました。","respondent":"森住宅課長","answer":"返ってきた答えとして、なかなか日常の生活の中で品川区内にある空き家について考えるということがなかなかないというようなところなのかというのは、それぞれの所有者とのやりとりの中では感じているところです。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"あるいは、これは情報提供というのは、どういうことを意味するのか伺いたいと。公園や活動スペースなどを生み出すというふうなことにつなげていくということは非常に有効だと思いますので、伺いたいと思います。","respondent":"森住宅課長","answer":"それに対する検討状況であったり、所有者の活用状況であったり、そういうようなことを情報提供していきたいと考えております。利活用についても、地元の方が使っていただく施設、そういうことも含めて利活用方法については考えていきたいと考えています。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの質問させていただいたところで、地域の公共的な役に立つということになるわけですから、そういった活用も必要なのではないかと思います。いかがか尋ねました。","respondent":"森住宅課長","answer":"あるいは、ＮＰＯが使うとなると、できるだけ低廉のということで書かせていただいているところです。用途変更に応じて固定資産税が上がるものを対策してもらえばとか、活用については所有者の意向にこたえながら進めていきたいと考えております。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどの専門家の団体の方たちからお話を伺うと、年に１回でしょうか、２回でしょうか。たしかそういう区のお考えもあると思うのですけれども、もう少し利活用について、どのようにお考えなのか尋ねました。","respondent":"森住宅課長","answer":"居住支援協議会のお話がありまして、今の検討状況ですが、各課長と情報共有を行っているところです。それから、他区あるいは東京都でヒアリングを行いまして、実施に向けての課題だとかを、体制だとか、ヒアリングを行ったところです。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本当に１件でも２件でも、１件でも突破していただきたいというのが正直な思いですので、しっかりそういうことをしてもらいたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問","question":"住む家はあるけれども、入る人間が少なくなってくるわけですから、そこら辺のバランスが崩れていく。空き家を今後防ぐ意味で、全体的な人口と家の総量に対する考え方というのは、その審議会なり会合の中で出ているのか尋ねました。","respondent":"森住宅課長","answer":"今後、その分は空き家としても増えていくだろうというふうに考えているところです。空き家になる前から、まずは発生予防を進めていこうというところを１つ大きな目標として挙げまして進めていきたいと考えているところです。","id":"exchange-076"}]},{"id":"topic-07","title":"の都市再生機構（ＵＲ）との木密事業に関する協定について（西品川２・３丁目地区）","agenda":"の都市再生機構（ＵＲ）との木密事業に関する協定について（西品川２・３丁目地区）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ご紹介いただきたいというのと、資料の４番目の協定の骨子というところで、これは具体的に何をどのように周知するのか伺います。それと、こういった手法は、他区や全国、ほかのところでも一般的に行われていることなのか伺います。","respondent":"高梨木密整備推進課長","answer":"そういった土地がありましたら、どんどん情報をくださいといった土地の提供に対する住民への啓発も同時に行いたい、このように考えているところです。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"どのような状況になっているのか少しご紹介いただきたいということが１つと、なぜＵＲとなのかというのは、もしそれ以外で何かあればお伺いします。","respondent":"高梨木密整備推進課長","answer":"ＵＲとは、平成２０年に品川区における防災まちづくりに関する協定ということで、双方協力して進めようといった旨の確認を締結しております。ＵＲとタッグを組んで品川区の木密地域を改善していこうといったことで運用しているといった状況です。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問・要望","question":"西品川３丁目で、４階建てのマンションが建ったことに対して、なぜ４階が建つのだというような相談をいただきました。区としてはしっかり求めていく必要があるのではないかと思いますけれども、あと、区としてはどのように考えているかあわせて伺います。","respondent":"高梨木密整備推進課長","answer":"西品川２・３丁目地区におきましては、先ほど冒頭で説明いたしましたとおり、今年度から密集市街地整備の新事業を入れております。締結します協定は、西品川２・３丁目全体のまちづくりに関するものではなく、共同化についての文言を協定に入れる考えはございません。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ住民の方のご意見をよく伺って、地域環境との調和という点でも、ぜひ関係部署と連携をしてしっかり配慮していってほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"}]},{"id":"topic-08","title":"のゆうぽうと跡地のにぎわいのあるまちづくりに関する協定","agenda":"のゆうぽうと跡地のにぎわいのあるまちづくりに関する協定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"店舗が１階ということですけれども、店舗は１階だけなのかという部分と、固める時期はいつごろと聞いているのか伺いたいと思います。そこら辺についてもお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"店舗ですが、現在、日本郵政が計画しているのは、１階部分を店舗等にしていきたいです。メートル数ではわからないのですけれども、以前の建物は地上１５階、地下４階建てというふうに記録されております。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問・要望","question":"周辺地域環境への配慮はすべきだと思いますので、ぜひそこら辺はきちんと指導してほしいと求めました。民間は民間ですから、地域からの要望に基づきということで、そこら辺が実現した経過を教えてほしいと求めました。","respondent":"稲田都市開発課長","answer":"そういうことで以前から日本郵政に対しては、にぎわい施設の検討、ホール施設の検討を協議してまいったところです。何とかやっていこうというところで、今、こぎつけているところです。","id":"exchange-082"},{"speaker":"安藤委員","kind":"質問・要望","question":"地元要望に基づきということで、そのほか、こういった要望もあるのですというようなことがあれば教えていただきたいというのが１つです。ホールを使うに当たっての空き状況の確認ですとか、日本郵政不動産のほうにも要望していってほしいと求めましたけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"ホールにつきましても、日ごろはフラットなのですけれども、そういう話では日本郵政とは協議を進めているところです。使い方等々ですが、これは今後の運営方法というところで、当然その辺は考えているところですが、今後、検討していくです。","id":"exchange-083"},{"speaker":"筒井委員","kind":"質問","question":"区がホール施設を賃借するということになっていますけれども、丸々品川区が通年ずっと借りて、貸出とかの管理も区がやるということなのでしょうか。どのような仕組みになるのかを示すよう求めました。","respondent":"稲田都市開発課長","answer":"今、委員おっしゃったように、区が丸々借りて、委託とか指定管理とかの手法はあるかもしれませんけれども、区が運営するという形を考えています。","id":"exchange-084"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"所管質問というよりも、その他でもしかすると報告があるかもしれないのですけれども、１０月２５日の自民党・子ども未来の鈴木真澄議員の一般質問で、大井町のまちづくりの中で、区庁舎のオイルダンパー、免震装置について……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"安藤委員","kind":"質問","question":"実際に品川区庁舎のところの免震装置４つのうち１つのダンパーがそれに関係していたということもあったかと思うので、現状どうなっているか。その対策の見通しについてお伺いします。","respondent":"長尾建築課長","answer":"今、ＫＹＢ株式会社が製造したオイルダンパーが４本使われており、そのうちの１本が不適合であるというふうな報告内容であると聞いております。その後の対応の状況のところまでは、この総合庁舎につきましては、東京都が是正指導を必要に応じて行うようなことになっております。","id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4246#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":77724,"voices":272}}]);
